    // Passkeys & Anmelde-Richtlinie (Core\Passkeys, Core\Mfa)
    '0 = bei der nächsten Anmeldung einrichten. Sonst erinnert die Anmeldung bis zum Ablauf der Frist daran; danach geht es erst nach der Einrichtung weiter.' => '0 = set up at the next sign-in. Otherwise sign-in reminds the user until the grace period ends; after that, they can only continue once it is set up.',
    '6-stelliger Code aus einer App auf Ihrem Telefon (z. B. 2FAS, Aegis, Google oder Microsoft Authenticator, 1Password).' => '6-digit code from an app on your phone (e.g. 2FAS, Aegis, Google or Microsoft Authenticator, 1Password).',
    'Abgebrochen oder Zeit abgelaufen. Bitte erneut versuchen.' => 'Cancelled or timed out. Please try again.',
    'Anmelde-Richtlinie' => 'Sign-in policy',
    'Anmelde-Richtlinie der Netzwerk-Konten gespeichert.' => 'Sign-in policy for network accounts saved.',
    'Anmelde-Richtlinie geändert' => 'Sign-in policy changed',
    'Anmelden mit Fingerabdruck, Gesicht oder Geräte-PIN statt mit einem Code – sicher gegen Phishing. Der Passkey bleibt auf Ihrem Gerät bzw. in Ihrem Passwortmanager; die Website speichert nur einen öffentlichen Schlüssel.' => 'Sign in with your fingerprint, face or device PIN instead of a code – safe against phishing. The passkey stays on your device or in your password manager; the website only stores a public key.',
    'Anmelden mit Fingerabdruck, Gesicht oder Geräte-PIN – auf Mac und iPhone (iCloud-Schlüsselbund), Android (Google Passwortmanager), Windows Hello, in Passwortmanagern oder mit einem Sicherheitsschlüssel.' => 'Sign in with your fingerprint, face or device PIN – on Mac and iPhone (iCloud Keychain), Android (Google Password Manager), Windows Hello, in password managers or with a security key.',
    'Anmeldung & Sicherheit' => 'Sign-in & security',
    'Anmeldung absichern' => 'Secure your sign-in',
    'Anmeldung bestätigen' => 'Confirm sign-in',
    'Anmeldung läuft …' => 'Signing in …',
    'Anmeldung ohne Passwort mit Passkey' => 'Passwordless sign-in with a passkey',
    'App einrichten' => 'Set up app',
    'Authenticator-App' => 'Authenticator app',
    'Authenticator-App (6-stelliger Code)' => 'Authenticator app (6-digit code)',
    'Bestätigen Sie die Anmeldung mit Ihrem Passkey – per Fingerabdruck, Gesicht, Geräte-PIN oder Sicherheitsschlüssel.' => 'Confirm the sign-in with your passkey – using your fingerprint, face, device PIN or security key.',
    'Bitte am Gerät bestätigen (Fingerabdruck, Gesicht, PIN oder Sicherheitsschlüssel) …' => 'Please confirm on your device (fingerprint, face, PIN or security key) …',
    'Bitte bestätigen Sie zuerst Ihr Passwort.' => 'Please confirm your password first.',
    'Bitte bis {date} einrichten – danach ist die Anmeldung ohne zweiten Faktor nicht mehr möglich.' => 'Please set this up by {date} – after that, signing in without a second factor is no longer possible.',
    'Bitte richten Sie zuerst in der Netzwerk-Verwaltung einen Passkey ein.' => 'Please add a passkey in the network administration first.',
    'Damit Sie ihn später wiedererkennen. Ohne Namen verwenden wir den Anbieter, z. B. „iCloud-Schlüsselbund“.' => 'So you can recognise it later. Without a name we use the provider, e.g. “iCloud Keychain”.',
    'Das Gerät hat Sie nicht per Fingerabdruck, Gesicht oder PIN bestätigt.' => 'The device did not verify you by fingerprint, face or PIN.',
    'Das hat nicht geklappt.' => 'That did not work.',
    'Das ist Ihr letzter zweiter Faktor – für Ihr Konto vorgeschrieben. Richten Sie zuerst einen anderen ein.' => 'This is your last second factor – required for your account. Set up another one first.',
    'Der Passkey gehört zu einer anderen Adresse.' => 'The passkey belongs to a different address.',
    'Der Passkey wurde nicht bestätigt.' => 'The passkey was not confirmed.',
    'Der Passkey wurde von einer anderen Adresse aus verwendet.' => 'The passkey was used from a different address.',
    'Der Wiederherstellungscode stimmt nicht.' => 'The recovery code is not correct.',
    'Die Anfrage ist abgelaufen. Bitte erneut versuchen.' => 'The request has expired. Please try again.',
    'Die Anmeldung mit Passkey ist auf dieser Website ausgeschaltet.' => 'Signing in with a passkey is turned off on this website.',
    'Die Anmeldung ohne Passwort ist für Ihr Konto ausgeschaltet. Bitte mit Passwort anmelden.' => 'Passwordless sign-in is turned off for your account. Please sign in with your password.',
    'Die Antwort des Geräts ist ungültig.' => 'The response from the device is invalid.',
    'Die Antwort des Geräts ist unvollständig.' => 'The response from the device is incomplete.',
    'Die Antwort des Geräts konnte nicht gelesen werden.' => 'The response from the device could not be read.',
    'Die Authenticator-App ist auf dieser Website abgeschaltet. Richten Sie stattdessen einen Passkey ein.' => 'The authenticator app is turned off on this website. Set up a passkey instead.',
    'Die Authenticator-App ist auf dieser Website nicht freigegeben.' => 'The authenticator app is not allowed on this website.',
    'Die Bestätigung des Geräts ist ungültig.' => 'The device attestation is invalid.',
    'Die Signatur des Passkeys ist ungültig.' => 'The passkey signature is invalid.',
    'Dieser Browser unterstützt keine Passkeys.' => 'This browser does not support passkeys.',
    'Dieser Browser unterstützt keine Passkeys. Bitte den Code aus der App oder einen Wiederherstellungscode verwenden.' => 'This browser does not support passkeys. Please use the code from the app or a recovery code.',
    'Dieser Passkey gehört zu einem anderen Konto.' => 'This passkey belongs to a different account.',
    'Dieser Passkey ist bereits eingerichtet.' => 'This passkey has already been added.',
    'Dieser Passkey ist hier nicht (mehr) eingerichtet. Bitte mit E-Mail-Adresse und Passwort anmelden.' => 'This passkey is not (or no longer) set up here. Please sign in with your email address and password.',
    'Dieser Passkey ist hier nicht eingerichtet.' => 'This passkey is not set up here.',
    'Dieser Passkey wurde abgelehnt (Zähler ungültig). Bitte einen anderen Passkey verwenden oder die Administration informieren.' => 'This passkey was rejected (invalid counter). Please use another passkey or contact your administrator.',
    'Dieses Gerät bzw. dieser Browser unterstützt keine Passkeys.' => 'This device or browser does not support passkeys.',
    'Dieses Gerät hat für Ihr Konto bereits einen Passkey.' => 'This device already has a passkey for your account.',
    'Erlaubte Verfahren' => 'Allowed methods',
    'Erlaubte Verfahren für Netzwerk-Konten' => 'Allowed methods for network accounts',
    'Für Ihr Konto ist ein Passkey vorgeschrieben – er schützt zuverlässig vor gefälschten Anmeldeseiten. Eine Authenticator-App genügt hier nicht.' => 'A passkey is required for your account – it reliably protects against fake sign-in pages. An authenticator app is not sufficient here.',
    'Für Ihr Konto ist ein Passkey vorgeschrieben.' => 'A passkey is required for your account.',
    'Für Ihr Konto ist ein zweiter Faktor vorgeschrieben. Wählen Sie ein Verfahren – danach geht es weiter.' => 'A second factor is required for your account. Choose a method – then you can continue.',
    'Für den Fall, dass Sie keinen Passkey zur Hand haben. Noch {n} Codes übrig.' => 'In case you do not have a passkey at hand. {n} codes left.',
    'Für diese Adresse ist kein Passkey eingerichtet.' => 'No passkey is set up for this address.',
    'Für diese Adresse ist noch kein Passkey eingerichtet. Bitte über die Netzwerk-Übersicht anmelden („Öffnen“) oder hier nach der Anmeldung unter „Konto“ einen Passkey hinzufügen.' => 'No passkey is set up for this address yet. Please sign in via the network overview (“Open”), or add a passkey here under “Account” after signing in.',
    'Für dieses Konto ist hier kein Passkey eingerichtet.' => 'No passkey is set up here for this account.',
    'Hinzugefügt {date}' => 'Added {date}',
    'Höchstens {n} Passkeys je Konto.' => 'At most {n} passkeys per account.',
    'Kein Zugriff auf Ihren Passkey? Geben Sie einen Ihrer Wiederherstellungscodes ein.' => 'No access to your passkey? Enter one of your recovery codes.',
    'Keine gültige Antwort vom Server. Bitte Seite neu laden.' => 'No valid response from the server. Please reload the page.',
    'Mindestens ein Verfahren muss erlaubt sein – Netzwerk-Konten melden sich immer mit zweitem Faktor an.' => 'At least one method must be allowed – network accounts always sign in with a second factor.',
    'Mit Passkey anmelden' => 'Sign in with a passkey',
    'Mit Passkey bestätigen' => 'Confirm with passkey',
    'Mit einem Passkey können Sie sich auch ganz ohne Passwort anmelden.' => 'With a passkey you can also sign in without a password.',
    'Mit jedem dieser Codes können Sie sich einmal ohne Passkey anmelden – z. B. wenn das Gerät verloren ist. Sie werden nur jetzt angezeigt – ausdrucken oder im Passwortmanager speichern.' => 'Each of these codes lets you sign in once without a passkey – e.g. if your device is lost. They are shown only now – print them or save them in your password manager.',
    'Name des Passkeys (optional)' => 'Passkey name (optional)',
    'Name von Passkey {n}' => 'Name of passkey {n}',
    'Netzwerk-Konten melden sich immer mit zweitem Faktor an (App oder Passkey). Passkeys gelten je Domain – für die direkte Anmeldung auf einer anderen Website dort einen eigenen Passkey hinzufügen; „Öffnen“ aus dieser Übersicht braucht keinen.' => 'Network accounts always sign in with a second factor (app or passkey). Passkeys are tied to a domain – to sign in directly on another website, add a separate passkey there; “Open” from this overview does not need one.',
