    'Strukturierte Daten (schema.org)' => 'Structured data (schema.org)',
    'Für Suchmaschinen: So wird die Detailseite eines Eintrags beschrieben. Titel, Bild, Beschreibung, Datum, Preis, Funktion usw. werden automatisch aus den passenden Feldern übernommen.' => 'For search engines: how an entry’s detail page is described. Title, image, description, date, price, job title etc. are taken from matching fields automatically.',
