    // Anfragen / Eingangs-Tabellen
    '0 = nie. Gezählt ab dem Tag, an dem die Anfrage als erledigt markiert wurde.' => '0 = never. Counted from the day the request was marked as done.',
    'Aktion' => 'Action',
    'Alle' => 'All',
    'Alle Angaben werden Ende-zu-Ende verschlüsselt gespeichert; lesbar nur unter „Anfragen“ mit dem geheimen Schlüssel. Keine Detailseiten, keine Ausgabe auf der Website, nicht in Suche, Sitemap, API-Inhalten oder Kalender-Abos. Jedes Entschlüsseln wird protokolliert.' => 'All information is stored end-to-end encrypted; readable only under “Requests” with the secret key. No detail pages, no output on the website, not in search, sitemap, API contents or calendar subscriptions. Every decryption is logged.',
    'Als erledigt markieren' => 'Mark as done',
    'Anfrage endgültig löschen?' => 'Delete this request permanently?',
    'Anfrage gelöscht.' => 'Request deleted.',
    'Anfragen lesen' => 'Read requests',
    'Art der Tabelle' => 'Table type',
    'Auf einer Seite mit dem Block „Formular (Datentabelle)“ einfügen.' => 'Place it on a page with the “Form (data table)” block.',
    'Auf einer Seite mit dem Block „Formular (Datentabelle)“ einfügen. Mehrstufiger Spamschutz, ohne Cookies.' => 'Place it on a page with the “Form (data table)” block. Multi-level spam protection, without cookies.',
    'Aus den früheren Online-Anfragen übernommen' => 'Taken over from the former online requests',
    'Automatisch gelöscht' => 'Deleted automatically',
    'Bitte den geheimen Schlüssel eingeben.' => 'Please enter the secret key.',
    'Das Protokoll sehen nur Administratoren.' => 'Only administrators can see the log.',
    'Datenschutz' => 'Privacy',
    'Datenschutz: Erledigte Anfragen bitte regelmäßig löschen (Datensparsamkeit).' => 'Privacy: please delete completed requests regularly (data minimisation).',
    'Datenschutz: Erledigte Anfragen werden nach {days} Tagen automatisch gelöscht.' => 'Privacy: completed requests are deleted automatically after {days} days.',
    'Der Schlüssel passt nicht zum hinterlegten öffentlichen Schlüssel.' => 'The key does not match the stored public key.',
    'Detail' => 'Detail',
    'Die E-Mail enthält keine Inhalte – nur den Hinweis auf eine neue Anfrage und einen Link.' => 'The email contains no content – only a notice about a new request and a link.',
    'Die Felder bilden das Formular. Eingänge speichern alle Angaben gemeinsam Ende-zu-Ende verschlüsselt (keine Spalte je Feld) – Felder lassen sich daher jederzeit ändern, ohne dass Anfragen verloren gehen. Keine Bilder, Verknüpfungen oder Karten; Dateifelder nur bei Zustellung per E-Mail.' => 'The fields make up the form. Inboxes store all information together, end-to-end encrypted (no column per field) – so fields can be changed at any time without losing requests. No images, relations or maps; file fields only with email delivery.',
    'Die letzten 200 Ereignisse: Entschlüsseln, Status, Zuweisung, Löschen. Es werden nie Inhalte protokolliert, die IP-Adresse nur als Kürzel (Hash). Aufbewahrung: {months} Monate (Grundeinstellungen → Spamschutz).' => 'The last 200 events: decryption, status, assignment, deletion. Contents are never logged, the IP address only as a short hash. Retention: {months} months (Basic settings → Spam protection).',
    'Diese Anfrage konnte mit dem Schlüssel nicht entschlüsselt werden (evtl. mit einem älteren Schlüssel verschlüsselt).' => 'This request could not be decrypted with the key (possibly encrypted with an older key).',
    'Diese Person darf die Anfragen dieser Tabelle nicht lesen.' => 'This person may not read the requests of this table.',
    'Drucken' => 'Print',
    'Eingang (verschlüsselt)' => 'Inbox (encrypted)',
    'Eingang (verschlüsselte Anfragen)' => 'Inbox (encrypted requests)',
    'Eingang anlegen' => 'Create inbox',
    'Eingang „{name}“ angelegt. Formular mit dem Block „Formular (Datentabelle)“ auf einer Seite einfügen – eingegangene Anfragen lesen Sie unter „Anfragen“.' => 'Inbox “{name}” created. Place the form on a page with the “Form (data table)” block – read incoming requests under “Requests”.',
    'Eingang: Einträge entstehen nur über das Formular und werden Ende-zu-Ende verschlüsselt (z. B. Gesundheitsdaten). Nur änderbar, solange die Tabelle leer ist; die passenden Einstellungen erscheinen nach dem Speichern.' => 'Inbox: entries are only created via the form and are end-to-end encrypted (e.g. health data). Can only be changed while the table is empty; the matching settings appear after saving.',
    'Eingangs-Tabelle: Anfragen unter „Anfragen“ bearbeiten.' => 'Inbox table: handle requests under “Requests”.',
    'Eingangs-Tabelle: Einträge entstehen nur über das öffentliche Formular (verschlüsselt).' => 'Inbox table: entries are only created via the public form (encrypted).',
    'Eingänge' => 'Inboxes',
    'Eingänge (verschlüsselte Anfragen)' => 'Inboxes (encrypted requests)',
    'Einleitung (optional)' => 'Introduction (optional)',
    'Einträge' => 'Entries',
    'Einträge werden nicht verschlüsselt gespeichert. Für vertrauliche Angaben (z. B. Gesundheitsdaten) einen verschlüsselten Eingang (Vorlage „Anfragen“) nutzen.' => 'Entries are not stored encrypted. For confidential information (e.g. health data) use an encrypted inbox (template “Requests”).',
