    'Gelöscht' => 'Deleted',
    'Gilt für die Rechte im Bereich „Daten“ (außer „Tabellen und Felder ändern“) und für „Anfragen“ – z. B. nur eine Eingangs-Tabelle lesen.' => 'Applies to the permissions in “Data” (except “Change tables and fields”) and to “Requests” – e.g. read only one inbox table.',
