    'Eingangs-Tabellen (verschlüsselte Anfragen) lassen sich nicht teilen.' => 'Inbox tables (encrypted requests) cannot be shared.',
    'Das Feld „{name}“ ist in geteilten Tabellen reserviert – bitte zuerst umbenennen.' => 'The field “{name}” is reserved in shared tables – please rename it first.',
    'Feld „{label}“ verknüpft die lokale Tabelle „{target}“. Verknüpfungen sind nur zu geteilten Tabellen derselben Website möglich – bitte zuerst „{target}“ teilen.' => 'Field “{label}” links to the local table “{target}”. Links are only possible to shared tables of the same website – please share “{target}” first.',
    'Zum Zusammenführen gibt es keine geteilte Tabelle „{key}“.' => 'There is no shared table “{key}” to merge into.',
    'Zusammenführen kann nur die Website, der die geteilte Tabelle gehört.' => 'Only the website that owns the shared table can merge.',
    'Eine geteilte Tabelle „{key}“ gibt es schon – mit --merge zusammenführen.' => 'A shared table “{key}” already exists – merge with --merge.',
    'Geteilte Tabelle „{key}“ angelegt (Eigentümer: {site}).' => 'Shared table “{key}” created (owner: {site}).',
    '{n} Einträge übernommen.' => '{n} entries transferred.',
    'Verweise in „{table}“ → „{field}“ umgeschrieben.' => 'References in “{table}” → “{field}” rewritten.',
