    'geteilt' => 'shared',
    'Einträge von „{site}“ – nur lesbar. Sie entscheiden, ob sie auf dieser Website erscheinen (Anzeige auf dieser Website) und können einzelne ausblenden oder hervorheben.' => 'Entries from “{site}” – read-only. You decide whether they appear on this website (Display on this website) and can hide or feature individual ones.',
