    'Ansehen' => 'View',
    'Dieser Eintrag stammt von „{site}“ und ist hier nur lesbar. Ändern kann ihn nur diese Website.' => 'This entry comes from “{site}” and is read-only here. Only that website can change it.',
    'Vorschlag ablehnen' => 'Reject suggestion',
