    'ja' => 'yes',
    'Geändert' => 'Changed',
    'ab / größer gleich' => 'from / greater or equal',
    'bis / kleiner gleich' => 'until / less or equal',
    '– kein Filter –' => '– no filter –',
    'Wert, z. B. Kurzname der Auswahl' => 'Value, e.g. option key',
    'Anzeige auf dieser Website' => 'Display on this website',
    'Diese Website zeigt {n} veröffentlichte Einträge, davon {own} eigene. Blöcke können die Quelle einzeln überschreiben (Datenliste, Kalender, Nächste Termine → „Quelle“).' => 'This website shows {n} published entries, {own} of them its own. Blocks can override the source individually (Data list, Calendar, Upcoming events → “Source”).',
    'Eigene Einträge' => 'Own entries',
    'Diese Website ist Eigentümerin der Tabelle. Einträge der übrigen Websites erscheinen hier, wenn Sie einen Vorschlag übernehmen oder wenn sie zu den Regeln der automatischen Übernahme passen. Ausgeblendete und abgelehnte Einträge erscheinen nie.' => 'This website owns the table. Entries of the other websites appear here when you accept a suggestion or when they match the rules for automatic inclusion. Hidden and rejected entries never appear.',
    'Automatische Übernahme' => 'Automatic inclusion',
    'Veröffentlichte Einträge der übrigen Websites automatisch zeigen, wenn sie zu den Regeln passen' => 'Automatically show published entries of the other websites that match the rules',
    'Nur von diesen Websites (keine Auswahl = alle):' => 'Only from these websites (none selected = all):',
    'Nur Einträge, bei denen … (alle Bedingungen müssen passen)' => 'Only entries where … (all conditions must match)',
    'Einträge von „{site}“' => 'Entries from “{site}”',
    'Auf dieser Website zeigen' => 'Show on this website',
    'Einzelne Einträge blenden Sie unter „{label}“ aus.' => 'Hide individual entries under “{label}”.',
    'Einträge der übrigen Websites' => 'Entries of the other websites',
    '„{site}“ hat nicht freigegeben, dass die Websites Einträge untereinander zeigen.' => '“{site}” has not allowed the websites to show each other’s entries.',
    'Nicht zeigen' => 'Do not show',
    'Von allen Websites' => 'From all websites',
    'Nur von ausgewählten Websites' => 'Only from selected websites',
    'Verlinkung fremder Einträge' => 'Linking of other websites’ entries',
    'Direkt auf die Ursprungs-Website verlinken (statt Detailseite auf dieser Website)' => 'Link directly to the origin website (instead of a detail page on this website)',
    'Detailseiten fremder Einträge auf dieser Website verweisen per Canonical auf die Ursprungs-Website – Suchmaschinen werten sie nicht doppelt.' => 'Detail pages of other websites’ entries point to the origin website via canonical – search engines do not count them twice.',
    'Ändern darf, wer Einträge veröffentlichen darf.' => 'Anyone allowed to publish entries can change this.',
    'Geteilte Daten' => 'Shared data',
    'Datentabellen für mehrere Websites dieser Installation, z. B. Neuigkeiten oder Termine eines Verbands und seiner Vereine. Eine Website ist Eigentümerin und legt die Felder fest; jede beteiligte Website pflegt ihre eigenen Einträge und entscheidet, welche fremden Einträge sie zeigt. Bilder und Dateien der Einträge liegen automatisch in geteilten Medien – ein Pool je Tabelle, sobald sie Bild- oder Dateifelder hat.' => 'Data tables for several websites of this installation, e.g. news or events of an association and its clubs. One website owns the table and defines the fields; every participating website maintains its own entries and decides which entries of others it shows. Images and files of the entries are stored in shared media automatically – one pool per table, as soon as it has image or file fields.',
    'Diese Website nimmt an keiner geteilten Tabelle teil.' => 'This website does not participate in any shared table.',
    'Eigentümer: {site}' => 'Owner: {site}',
    'Beteiligte Websites' => 'Participating websites',
    'pflegen eigene Einträge und nutzen die Tabelle auf ihrer Website' => 'maintain their own entries and use the table on their website',
    'Beteiligte Websites dürfen Einträge der anderen Beteiligten zeigen' => 'Participating websites may show entries of the other participants',
    'Automatische Übernahme und die Auswahl für die eigene Website stellen Sie bei der Tabelle ein (Daten → Tabelle → Anzeige auf dieser Website).' => 'Automatic inclusion and the selection for your own website are set at the table (Data → table → Display on this website).',
    'Freigabe beenden …' => 'Stop sharing …',
    'Die Tabelle wird wieder eine eigene Tabelle dieser Website – mit den eigenen Einträgen. Die übrigen Websites verlieren den Zugriff; die geteilten Daten bleiben als Sicherung erhalten. Zum Bestätigen den Kurznamen eintippen:' => 'The table becomes a local table of this website again – with its own entries. The other websites lose access; the shared data is kept as a backup. Type the handle to confirm:',
    'Kurzname zur Bestätigung' => 'Handle for confirmation',
    'Freigabe beenden' => 'Stop sharing',
