    'Beteiligte sehen sich gegenseitig' => 'Participants see each other',
    'Neue geteilte Tabelle' => 'New shared table',
    'Diese Website wird Eigentümerin: sie legt die Felder fest und entscheidet über Vorschläge der übrigen Websites.' => 'This website becomes the owner: it defines the fields and decides on suggestions of the other websites.',
