    'Geteilt mit anderen Websites dieser Installation' => 'Shared with other websites of this installation',
    'Erscheint je nach deren Einstellung auch auf den übrigen Websites dieser Tabelle.' => 'Also appears on the other websites of this table, depending on their settings.',
    'Diese Website pflegt ihre eigenen Einträge; „{site}“ legt die Felder fest.' => 'This website maintains its own entries; “{site}” defines the fields.',
    'Zur Übernahme vorschlagen ({owner})' => 'Suggest for adoption ({owner})',
    'Übernommen – erscheint auf der Website von „{site}“.' => 'Accepted – appears on the website of “{site}”.',
    'Übernommen und hervorgehoben.' => 'Accepted and featured.',
    'Vorschlag wurde abgelehnt.' => 'Suggestion was rejected.',
    'Dort ausgeblendet.' => 'Hidden there.',
    'Vorgeschlagen – noch nicht entschieden.' => 'Suggested – not decided yet.',
    'Veröffentlichte Einträge mit Häkchen erscheinen dort unter „Vorschläge“.' => 'Published entries with this checkbox appear there under “Suggestions”.',
    'vorgeschlagen' => 'suggested',
    'Geteilte Tabelle: Änderungen an Feldern und Einstellungen gelten für alle {n} beteiligten Websites. Die Detailseiten-Vorlage gestaltet jede Website selbst.' => 'Shared table: changes to fields and settings apply to all {n} participating websites. Each website designs its own detail page template.',
    'Die Felder dieser geteilten Tabelle legt die Website „{site}“ fest.' => 'The fields of this shared table are defined by the website “{site}”.',
    'Geteilte Tabellen löscht man nicht hier: Mitglieder entfernen bzw. die Freigabe beenden unter Grundeinstellungen → Geteilte Daten.' => 'Shared tables are not deleted here: remove members or stop sharing under Basic settings → Shared data.',
