    'Adresse (base_url) ist ungültig.' => 'Address (base_url) is invalid.',
    'Alle eingerichteten Fähigkeiten laufen auf einem eigenen Server (z. B. Ollama) – Inhalte verlassen die Infrastruktur nicht.' => 'All configured capabilities run on your own server (e.g. Ollama) – content never leaves your infrastructure.',
