    'Begriff' => 'Term',
    'Besucher suchen unter {path} in Seiten, Einträgen mit Detailseite und – wenn gewünscht – PDF-Dokumenten. Tippfehler und Umlaute sind egal. Der Index aktualisiert sich nach jeder Änderung automatisch.' => 'Visitors search at {path} across pages, entries with a detail page and – if enabled – PDF documents. Typos and accents do not matter. The index updates automatically after every change.',
    'Bild' => 'Image',
    'Bild konnte nicht gelesen werden.' => 'Image could not be read.',
    'Bild nicht gefunden.' => 'Image not found.',
    'Bilddatei nicht gefunden.' => 'Image file not found.',
    'Bilder: Alt-Texte vorschlagen' => 'Images: suggest alt texts',
    'Bisher keine.' => 'None so far.',
    'Braucht KI mit Embeddings (Reiter „KI“). Bei einem externen Anbieter wird der Suchtext der Besucher dorthin übermittelt – Hinweis in der Datenschutzerklärung nötig.' => 'Requires AI with embeddings (tab “AI”). With an external provider, visitors’ search text is sent there – a note in the privacy policy is required.',
    'Datenschutz: Suchtexte gehen an einen externen Anbieter ({endpoint}).' => 'Privacy: search texts are sent to an external provider ({endpoint}).',
    'Datum' => 'Date',
    'Den KI-Anbieter legt die Agentur bzw. Netzwerk-Administration fest.' => 'The AI provider is set by the agency or network administration.',
    'Der KI-Anbieter ist gerade nicht erreichbar. Bitte in einer Minute erneut versuchen.' => 'The AI provider is currently unreachable. Please try again in a minute.',
    'Der Suchindex ist nicht lesbar – bitte „Index neu aufbauen“.' => 'The search index cannot be read – please use “Rebuild index”.',
    'Der Suchindex wird gerade abgeglichen – bitte gleich noch einmal ansehen.' => 'The search index is being updated right now – please check again shortly.',
    'Die semantische Suche ist eingeschaltet, aber KI mit Embeddings ist für diese Website nicht aktiv (Reiter „KI“). Bis dahin sucht die Website nur nach Stichworten.' => 'Semantic search is switched on, but AI with embeddings is not active for this website (tab “AI”). Until then the website searches by keywords only.',
    'Diese Datentabellen nicht durchsuchen' => 'Do not search these data tables',
    'Dokumente' => 'Documents',
    'EU-Datenresidenz' => 'EU data residency',
    'Eine Zeile je Gruppe, Begriffe mit Komma getrennt. Wer einen Begriff sucht, findet auch die anderen.' => 'One line per group, terms separated by commas. Searching for one term also finds the others.',
    'Embeddings: semantische Suche' => 'Embeddings: semantic search',
    'Empfehlung: eigener Ollama-Server (z. B. Modelle gemma3 für Text und Bilder, bge-m3 oder nomic-embed-text für die Suche) oder ein EU-Anbieter wie Mistral AI.' => 'Recommendation: your own Ollama server (e.g. gemma3 for text and images, bge-m3 or nomic-embed-text for search) or an EU provider such as Mistral AI.',
