    'Fähigkeiten' => 'Capabilities',
    'Für diese KI-Funktion ist kein Modell konfiguriert.' => 'No model is configured for this AI function.',
    'Für große Websites und geteilte Daten zusätzlich per Cron: {cmd}' => 'For large websites and shared data also via cron: {cmd}',
    'Für „{cap}“ ist kein Modell konfiguriert.' => 'No model is configured for “{cap}”.',
    'Gefunden werden nur veröffentlichte Einträge mit Detailseite (Adresse unter „Website“).' => 'Only published entries with a detail page (address under “Website”) are found.',
    'Geteilte Tabelle: gilt für alle beteiligten Websites; welche fremden Einträge eine Website zeigt (und findet), stellt jede Website selbst ein.' => 'Shared table: applies to all participating websites; each website decides which foreign entries it shows (and finds).',
    'Gewichtung' => 'Weight',
    'Gewichtung Titel' => 'Title weight',
    'Gewichtung Überschriften' => 'Heading weight',
    'Gezählt werden nur Aufrufe, Tokens und Dauer – nie Inhalte. Kosten nur mit Preisangaben in der Konfiguration (\'prices\').' => 'Only calls, tokens and duration are counted – never content. Costs only with prices in the configuration (\'prices\').',
    'Gilt für alle Websites dieser Installation (storage/ai/config.json, nicht im Webroot). Werte aus config/config.local.php bzw. config/sites/*.php haben Vorrang und sind hier gesperrt.' => 'Applies to all websites of this installation (storage/ai/config.json, outside the web root). Values from config/config.local.php or config/sites/*.php take precedence and are locked here.',
    'Größe: {size}' => 'Size: {size}',
    'In der Website-Suche' => 'In website search',
    'Index neu aufbauen' => 'Rebuild index',
    'KI' => 'AI',
    'KI auf dieser Website (Symfony AI)' => 'AI on this website (Symfony AI)',
    'KI ist für diese Website nicht eingeschaltet (Grundeinstellungen → KI).' => 'AI is not switched on for this website (Basic settings → AI).',
    'KI-Anbieter gespeichert. Mit „Verbindung testen“ prüfen.' => 'AI provider saved. Check it with “Test connection”.',
    'KI-Anbieter: Adresse (base_url) fehlt oder ist ungültig.' => 'AI provider: address (base_url) is missing or invalid.',
    'KI-Anbieter: {error}' => 'AI provider: {error}',
    'KI-Anbieter: {error} – die Stichwortsuche funktioniert weiter.' => 'AI provider: {error} – keyword search keeps working.',
    'KI-Dienstleister' => 'AI service provider',
    'KI-Funktionen auf dieser Website einschalten' => 'Switch on AI features for this website',
    'KI-Funktionen nutzen (Texte, Übersetzung, SEO, Alt-Texte)' => 'Use AI features (texts, translation, SEO, alt texts)',
    'Kein Embedding-Modell konfiguriert.' => 'No embedding model configured.',
    'Kein KI-Anbieter konfiguriert.' => 'No AI provider configured.',
