    'Kosten' => 'Cost',
    'Kurztext' => 'Summary',
    'Letzter Fehler: {error}' => 'Last error: {error}',
    'Liste der Suchbegriffe ohne Treffer leeren?' => 'Clear the list of search terms without results?',
    'Liste geleert.' => 'List cleared.',
    'Liste leeren' => 'Clear list',
    'Mindestens eine Fähigkeit nutzt einen externen Anbieter. Texte, Bilder oder Suchbegriffe, die eine KI-Funktion verarbeitet, gehen dorthin – nur wenn jemand die Funktion auslöst (bzw. bei der semantischen Suche: bei jeder Suche). Mit dem Anbieter ist ein Vertrag zur Auftragsverarbeitung nötig; bevorzugen Sie Anbieter mit Sitz/Rechenzentrum in der EU oder einen eigenen Ollama-Server. Keine Patientendaten oder andere besondere Kategorien personenbezogener Daten eingeben.' => 'At least one capability uses an external provider. Texts, images or search terms processed by an AI feature are sent there – only when someone triggers the feature (for semantic search: on every search). A data processing agreement with the provider is required; prefer providers based/hosted in the EU or your own Ollama server. Do not enter patient data or other special categories of personal data.',
    'Modell' => 'Model',
    'Modell: {cap}' => 'Model: {cap}',
    'Nach dem Speichern wird der Suchindex automatisch aktualisiert.' => 'The search index is updated automatically after saving.',
    'Nicht finden, wenn Feld …' => 'Do not find if field …',
    'Noch kein KI-Anbieter eingerichtet – unten unter „Anbieter der Installation“ festlegen.' => 'No AI provider set up yet – configure it below under “Provider for this installation”.',
    'Noch kein KI-Anbieter eingerichtet. Das übernimmt die Agentur bzw. Netzwerk-Administration.' => 'No AI provider set up yet. This is done by the agency or network administration.',
    'Nur Begriff und Anzahl – keine IP-Adresse, keine Uhrzeit. Begriffe mit E-Mail-Adressen oder langen Zahlen werden nie gespeichert.' => 'Only term and count – no IP address, no time. Terms with e-mail addresses or long numbers are never stored.',
    'Nur Bilder können beschrieben werden.' => 'Only images can be described.',
    'Nur künftige Termine (vergangene nicht finden)' => 'Only upcoming events (do not find past ones)',
    'Nutzung (letzte 30 Tage, diese Website)' => 'Usage (last 30 days, this website)',
    'Ollama: http://127.0.0.1:11434 · OpenAI-kompatibel: Basis-URL des Dienstes · Mistral/OpenAI: leer lassen' => 'Ollama: http://127.0.0.1:11434 · OpenAI-compatible: base URL of the service · Mistral/OpenAI: leave empty',
    'PDF-Dokumente der Mediathek finden (Titel, Alt-Text, Dateiname)' => 'Find PDF documents in the media library (title, alt text, file name)',
