    'Text kopieren' => 'Copy text',
    'Texte schreiben und übersetzen, SEO-Vorschläge, Alt-Texte für Bilder und semantische Suche. Welcher Anbieter genutzt wird, legt die Agentur für die Installation fest (unten).' => 'Write and translate texts, SEO suggestions, alt texts for images and semantic search. The agency decides which provider is used for the installation (below).',
