    'Website-Suche' => 'Website search',
    'Website-Suche: Suchbegriffe werden ausschließlich auf unserem eigenen Server verarbeitet (auch die KI-gestützte Suche) und nicht an Dritte übermittelt. Wir speichern Suchbegriffe nicht personenbezogen.' => 'Website search: search terms are processed exclusively on our own server (including the AI-assisted search) and are not passed on to third parties. We do not store search terms in a personally identifiable way.',
    'Website-Suche: Wenn Sie unsere Suche nutzen, wird Ihr Suchbegriff zur Verbesserung der Ergebnisse an {name} übermittelt und dort in einen Zahlenvektor umgerechnet (Art. 6 Abs. 1 lit. f DSGVO, berechtigtes Interesse an einer hilfreichen Suche). Ihre IP-Adresse und weitere Daten werden dabei nicht übermittelt; wir speichern Suchbegriffe nicht personenbezogen. Mit dem Anbieter besteht ein Vertrag zur Auftragsverarbeitung.' => 'Website search: when you use our search, your search term is sent to {name} to improve the results and converted into a numeric vector there (Art. 6(1)(f) GDPR, legitimate interest in a helpful search). Your IP address and other data are not transmitted; we do not store search terms in a personally identifiable way. A data processing agreement is in place with the provider.',
    'Website: aus' => 'Website: off',
    'Welche Einträge?' => 'Which entries?',
    'Wer KI nutzen darf, steuert das Recht „KI-Funktionen nutzen“ unter Benutzer & Rollen (Standard: Redaktion und Administration).' => 'Who may use AI is controlled by the permission “Use AI features” under Users & roles (default: editors and administrators).',
