    '„Hoch“ zählt wie eine Überschrift. IBAN, Bilder und Dateien werden nie durchsucht; E-Mail, Telefon, Links und Zahlen nur, wenn Sie sie einschalten. Gruppen gehen ohne IBAN/E-Mail/Telefon ein. Filter: Auswahl- und Verknüpfungsfelder erscheinen auf der Ergebnisseite als Filter, sobald nach dieser Tabelle gefiltert wird.' => '“High” counts like a heading. IBAN, images and files are never searched; e-mail, phone, links and numbers only if you enable them. Groups are included without IBAN/e-mail/phone. Filters: select and relation fields appear as filters on the results page once results are filtered by this table.',
