    '0 = unbegrenzt. Die Suche zählt nicht mit; der heutige Stand steht unten unter „Nutzung“.' => '0 = unlimited. Search does not count; today’s figure is shown below under “Usage”.',
    'Adresse (URL)' => 'Address (URL)',
