    'Ausgewählte übernehmen' => 'Apply selected',
    'Bearbeitet wird der ganze Inhalt des Feldes. Tipp: Text markieren, um nur einen Teil zu ändern.' => 'The whole field will be edited. Tip: select text to change only part of it.',
    'Bearbeitet wird der markierte Text.' => 'The selected text will be edited.',
    'Beschreibung für Suchmaschinen' => 'Description for search engines',
    'Beschreibung in Ordnung ({n} Zeichen).' => 'Description OK ({n} characters).',
