    'Beschreibung ist lang ({n} Zeichen) und wird in Suchergebnissen abgeschnitten.' => 'Description is long ({n} characters) and will be cut off in search results.',
    'Beschreibung wurde auf {n} Zeichen gekürzt.' => 'Description was shortened to {n} characters.',
    'Beschriftung im Menü' => 'Menu label',
    'Bild {a} von {n} …' => 'Image {a} of {n} …',
    'Bilder ohne Alt-Text ({lang}): {list}' => 'Images without alt text ({lang}): {list}',
