    'Bisher' => 'Current',
    'Bisherige Übersetzung' => 'Existing translation',
    'Bitte beschreiben Sie kurz, was die Tabelle enthalten soll.' => 'Please briefly describe what the table should contain.',
    'Bitte beschreiben Sie, was die KI schreiben soll.' => 'Please describe what the AI should write.',
    'Bitte mindestens einen Text auswählen.' => 'Please select at least one text.',
    'Bitte prüfen – im Original, aber nicht in der Übersetzung: {list}' => 'Please check – in the original but not in the translation: {list}',
    'Bitte zuerst Zeilen auswählen.' => 'Please select rows first.',
    'Das Feld ist leer – beschreiben Sie unter „Freier Auftrag“, was entstehen soll.' => 'The field is empty – describe under “Custom instruction” what should be written.',
    'Das Feld ist leer – für einen neuen Text „Freier Auftrag“ wählen.' => 'The field is empty – choose “Custom instruction” for a new text.',
    'Das Tageslimit für KI-Aufrufe dieser Website ist erreicht ({n}). Morgen geht es weiter – oder die Administration erhöht das Limit unter Grundeinstellungen → KI.' => 'The daily limit of AI requests for this website has been reached ({n}). It resets tomorrow – or an administrator can raise the limit under Basic settings → AI.',
    'Das eingestellte KI-Modell ist nicht verfügbar. Bitte die Administration informieren.' => 'The configured AI model is not available. Please inform the administrators.',
    'Der Artikel ist noch leer.' => 'The article is still empty.',
    'Der Eintrag ist online: Eine neue Adresse macht alte Links und Lesezeichen ungültig (keine automatische Weiterleitung).' => 'The entry is online: a new address breaks old links and bookmarks (no automatic redirect).',
    'Der KI-Anbieter ist gerade ausgelastet. Bitte etwas später erneut versuchen.' => 'The AI provider is busy right now. Please try again a little later.',
    'Der KI-Anbieter lehnt die Anfrage ab (Zugangsdaten). Bitte die Administration informieren.' => 'The AI provider rejected the request (credentials). Please inform the administrators.',
    'Der KI-Assistent ist für Sie auf dieser Website nicht verfügbar.' => 'The AI assistant is not available to you on this website.',
    'Der Vorschlag enthält einen Platzhalter [bitte ergänzen: …] – bitte ausfüllen oder entfernen.' => 'The suggestion contains a placeholder [bitte ergänzen: …] – please fill it in or remove it.',
    'Der Vorschlag enthält {n} Platzhalter [bitte ergänzen: …] – bitte ausfüllen oder entfernen.' => 'The suggestion contains {n} placeholders [bitte ergänzen: …] – please fill them in or remove them.',
    'Die Adresse „{slug}“ ist auf dieser Ebene schon vergeben – vorgeschlagen ist „{alt}“.' => 'The address “{slug}” is already taken on this level – suggesting “{alt}”.',
    'Die Antwort der KI war unvollständig. Bitte erneut versuchen.' => 'The AI response was incomplete. Please try again.',
    'Die Beschreibung für Suchmaschinen kommt aus dem Beschreibungsfeld der Tabelle. Aufgeführt sind Einträge, bei denen es leer oder länger als 160 Zeichen ist.' => 'The search engine description comes from the table’s description field. Listed are entries where it is empty or longer than 160 characters.',
    'Die KI arbeitet …' => 'The AI is working …',
    'Die KI beschreibt ein Bild nach dem anderen. Prüfen und ändern Sie jeden Vorschlag – gespeichert werden nur angehakte Bilder.' => 'The AI describes one image after another. Check and edit every suggestion – only ticked images are saved.',
    'Die KI erfindet keine Fakten: Fehlende Angaben erscheinen als [bitte ergänzen: …]. Bitte jeden Vorschlag prüfen.' => 'The AI does not invent facts: missing information appears as [bitte ergänzen: …]. Please check every suggestion.',
    'Die KI hat keine Antwort geliefert. Bitte erneut versuchen.' => 'The AI did not return an answer. Please try again.',
    'Die KI hat keine Felder vorgeschlagen. Bitte die Beschreibung genauer fassen.' => 'The AI did not suggest any fields. Please describe the table more precisely.',
    'Die KI hat keinen verwertbaren Text geliefert. Bitte erneut versuchen.' => 'The AI did not return usable text. Please try again.',
    'Die KI hat zu lange gebraucht. Bitte mit einem kürzeren Text oder später erneut versuchen.' => 'The AI took too long. Please try again with a shorter text or later.',
    'Die KI hält das Bild für rein dekorativ – dann „dekorativ“ ankreuzen statt Alt-Text.' => 'The AI considers the image purely decorative – if so, tick “decorative” instead of writing alt text.',
    'Die KI hält das Bild für rein dekorativ – dann „dekorativ“ ankreuzen.' => 'The AI considers the image purely decorative – if so, tick “decorative”.',
    'Die KI konnte das Bild nicht beschreiben.' => 'The AI could not describe the image.',
    'Die KI macht nur Vorschläge – sie werden erst gespeichert, wenn jemand sie prüft und übernimmt. Sie erfindet keine Fakten, sondern setzt „[bitte ergänzen: …]“.' => 'The AI only makes suggestions – they are saved only after someone reviews and applies them. It does not invent facts but inserts “[bitte ergänzen: …]”.',
    'Die KI schaut sich das Bild an …' => 'The AI is looking at the image …',
    'Die KI-Anfrage ist fehlgeschlagen ({n}).' => 'The AI request failed ({n}).',
    'Die KI-Anfrage ist fehlgeschlagen. Bitte später erneut versuchen.' => 'The AI request failed. Please try again later.',
    'Die Nachricht enthält schon Text. Ersetzen?' => 'The message already contains text. Replace it?',
    'Die Seite hat kaum eigenen Text – der Vorschlag stützt sich fast nur auf den Titel. Bitte besonders sorgfältig prüfen.' => 'The page has hardly any text of its own – the suggestion is based almost only on the title. Please check it especially carefully.',
    'Die Seite hat keine Überschriften.' => 'The page has no headings.',
    'Die Seite ist online. Nach dem Speichern ist sie nur noch unter der neuen Adresse erreichbar – alte Links funktionieren nicht mehr. Trotzdem übernehmen?' => 'The page is online. After saving it will only be reachable at the new address – old links will stop working. Apply anyway?',
    'Die Seite ist online: Eine neue Adresse macht alte Links und Lesezeichen ungültig (keine automatische Weiterleitung).' => 'The page is online: a new address breaks old links and bookmarks (no automatic redirect).',
    'Diese Angaben aus dem Original fehlen im Vorschlag: {list}' => 'These details from the original are missing in the suggestion: {list}',
    'Diese Seite ist in der Standardsprache – übersetzt wird in ihren Übersetzungen.' => 'This page is in the default language – translating happens in its translations.',
    'Diesen geteilten Pool darf diese Website nur verwenden.' => 'This website may only use this shared pool.',
    'Eine Zeile je Begriff. „Begriff“ bleibt in jeder Sprache gleich (z. B. Marken- und Eigennamen), „Begriff = Übersetzung“ wird immer so übersetzt.' => 'One term per line. “Term” stays the same in every language (e.g. brand and proper names), “Term = translation” is always translated that way.',
