    'Die Tonspur ist für den Anbieter zu groß (max. 25 MB, etwa 100 Minuten). Bitte kürzeres Medium oder whisper.cpp verwenden.' => 'The audio track is too large for the provider (max. 25 MB, about 100 minutes). Please use shorter media or whisper.cpp.',
