    'whisper-cli nicht gefunden.' => 'whisper-cli not found.',
    'whisper.cpp ist fehlgeschlagen: {msg}' => 'whisper.cpp failed: {msg}',
    'Leere Pfade werden automatisch gesucht (storage/ai/bin, /opt/homebrew/bin, /usr/local/bin, /usr/bin; Modelle in storage/ai/models). Eine Stunde Video braucht mit large-v3-turbo auf 4 CPU-Kernen etwa 20–60 Minuten; es läuft immer nur ein Auftrag gleichzeitig.' => 'Empty paths are detected automatically (storage/ai/bin, /opt/homebrew/bin, /usr/local/bin, /usr/bin; models in storage/ai/models). One hour of video takes about 20–60 minutes with large-v3-turbo on 4 CPU cores; only one job runs at a time.',
    'Ollama hat kein Spracherkennungs-Modell. Lokal und ohne Datenweitergabe: whisper.cpp auf diesem Server (Programm whisper-cli, ein Modell wie ggml-large-v3-turbo-q5_0.bin in storage/ai/models/, ffmpeg). Alternativ ein OpenAI-kompatibler Dienst (OpenAI whisper-1, Mistral Voxtral, eigener faster-whisper-Server).' => 'Ollama has no speech recognition model. Locally and without sharing data: whisper.cpp on this server (program whisper-cli, a model such as ggml-large-v3-turbo-q5_0.bin in storage/ai/models/, ffmpeg). Alternatively an OpenAI-compatible service (OpenAI whisper-1, Mistral Voxtral, your own faster-whisper server).',
    'OpenAI-kompatibel: Adresse (base_url)' => 'OpenAI-compatible: address (base_url)',
    'OpenAI-kompatibel: Modell / Schlüssel' => 'OpenAI-compatible: model / key',
    'Sprache (Standard)' => 'Language (default)',
    'Sprache → Text (Untertitel für Videos und Audio)' => 'Speech → text (captions for videos and audio)',
    'Sprache → Text: Die Tonspur von Videos/Audio, die jemand transkribieren lässt, geht an den externen Dienst. Bitte nur Aufnahmen ohne Gesundheitsdaten verwenden – oder whisper.cpp auf dem eigenen Server.' => 'Speech → text: the audio track of videos/audio someone has transcribed is sent to the external service. Please only use recordings without health data – or whisper.cpp on your own server.',
