    'Bezeichnung im Player' => 'Label in the player',
    'Bitte vollständig ansehen bzw. anhören und korrigieren: Namen, Fachbegriffe, Zahlen, Zeiten. Erst „Geprüft – veröffentlichen“ zeigt die Untertitel auf der Website.' => 'Please watch or listen to it in full and correct names, technical terms, numbers and timings. Only “Reviewed – publish” shows the captions on the website.',
    'Der vollständige Text zum Mitlesen (Barrierefreiheit, WCAG 1.2.1/1.2.3) – erscheint unter dem Video als „Transkript anzeigen“ und wird von der Website-Suche gefunden. Gern mit Sprecherinnen/Sprechern und wichtigen Geräuschen oder Bildinhalten.' => 'The full text to read along (accessibility, WCAG 1.2.1/1.2.3) – appears below the video as “Show transcript” and is found by the website search. Feel free to include speakers and important sounds or visual content.',
    'Die Text-KI übersetzt „{name}“ Eintrag für Eintrag, die Zeiten bleiben gleich. Ergebnis: Entwurf zur Prüfung.' => 'The text AI translates “{name}” entry by entry, the timings stay the same. Result: a draft for review.',
    'Die Tonspur geht an einen externen Dienst. Ergebnis: Entwurf zur Prüfung.' => 'The audio track is sent to an external service. Result: a draft for review.',
