    'Aufträge' => 'Jobs',
    'Datei' => 'File',
    'Die KI-Transkription ist für diese Website nicht eingerichtet (Grundeinstellungen → KI → Sprache → Text). Untertitel lassen sich in der Mediathek hochladen (.vtt/.srt) oder von Hand schreiben.' => 'AI transcription is not set up for this website (Basic settings → AI → Speech → text). Captions can be uploaded in the media library (.vtt/.srt) or written by hand.',
    'Entwürfe prüfen' => 'Review drafts',
    'Es läuft immer nur ein Auftrag gleichzeitig; weitere warten. Die Seite aktualisiert den Stand von selbst.' => 'Only one job runs at a time; others wait. This page updates the status by itself.',
    'Noch keine Aufträge.' => 'No jobs yet.',
    'Sprache erkennen' => 'Detect language',
    'Transkribieren' => 'Transcribe',
    'Transkription ({lang})' => 'Transcription ({lang})',
    'Videos brauchen Untertitel, Audio ein Transkript (WCAG 1.2.1–1.2.3). Die KI hört die Tonspur ab und erstellt einen Entwurf – er erscheint erst auf der Website, wenn jemand ihn in der Mediathek geprüft und veröffentlicht hat.' => 'Videos need captions, audio needs a transcript (WCAG 1.2.1–1.2.3). The AI listens to the audio track and creates a draft – it only appears on the website once someone has reviewed and published it in the media library.',
    'automatisch' => 'automatic',
