    'z. B. Workshops samstags 10–14 Uhr, höchstens 12 Personen, Material inklusive, Anmeldung bis Donnerstag' => 'e.g. workshops Saturdays 10 am–2 pm, at most 12 people, materials included, sign up by Thursday',
    'Nur was hier, im Thema oder in den einbezogenen Website-Angaben steht, darf als Fakt auf die Seite. Alles andere markiert die KI mit [bitte ergänzen: …].' => 'Only what is stated here, in the topic or in the included website details may appear as fact. Anything else is marked by the AI with [bitte ergänzen: …].',
    'Website-Angaben einbeziehen' => 'Include website details',
