    // Benutzer & Rollen: 2FA zurücksetzen
    'Benutzer nicht gefunden.' => 'User not found.',
    'Die eigene Zwei-Faktor-Anmeldung ändern Sie unter „Konto“.' => 'Change your own two-factor authentication under “Account”.',
    'Zwei-Faktor-Anmeldung von {email} zurückgesetzt.' => 'Two-factor authentication of {email} reset.',
    'Zwei-Faktor-Anmeldung von {email} zurücksetzen? Alle Sitzungen des Kontos enden; verlangt die Rolle 2FA, wird sie bei der nächsten Anmeldung neu eingerichtet.' => 'Reset two-factor authentication of {email}? All sessions of the account end; if the role requires 2FA, it will be set up again at the next sign-in.',
    'Bilder ohne Alt-Text und fehlende Übersetzungen. Die KI beschreibt Bilder bzw. übersetzt vorhandene Alt-Texte – gespeichert werden nur die Vorschläge, die Sie prüfen und anhaken.' => 'Images without alt text and missing translations. The AI describes images or translates existing alt texts – only the suggestions you review and tick are saved.',
    'Übersetzen ({n})' => 'Translate ({n})',
    'Alle Alt-Texte sind übersetzt.' => 'All alt texts are translated.',
    'Übersetzt wird der vorhandene Alt-Text der Standardsprache – so bleiben beide Fassungen inhaltlich gleich.' => 'The existing alt text of the default language is translated – so both versions stay consistent.',
    'Alt-Texte übersetzen ({lang})' => 'Translate alt texts ({lang})',
    'Die KI übersetzt die vorhandenen Alt-Texte. Prüfen und ändern Sie jeden Vorschlag – gespeichert werden nur angehakte Bilder.' => 'The AI translates the existing alt texts. Review and edit each suggestion – only ticked images are saved.',
