    // Handbuch & Hilfe › Tutorials (help/tutorials.php, help/tutorial.php; Inhalte app/Admin/tutorials.php)
    'Tutorials' => 'Tutorials',
    'Schritt für Schritt' => 'Step by step',
    'Mit kurzen Videos.' => 'With short videos.',
    // Produkt-Trailer oben auf der Übersicht (tools/trailer/trailer.mjs)
    'KLXM Studio im Überblick' => 'KLXM Studio at a glance',
    'Kits, Bearbeiten und Verwalten im Überblick – mit Sprecher (Deutsch) und Untertiteln (Deutsch, Englisch). Der Ton startet erst, wenn Sie das Video abspielen.' => 'Kits, editing and administration at a glance – with narration (German) and captions (German, English). Sound only starts when you play the video.',
    'Video: KLXM Studio im Überblick' => 'Video: KLXM Studio at a glance',
    'Kurze Videos zu den wichtigsten Aufgaben – für die Redaktion, die Administration einer Website und für Agenturen. Jedes Tutorial nennt Ziel, Voraussetzungen und alle Schritte mit den genauen Bezeichnungen.' => 'Short videos on the most important tasks – for editors, website administrators and agencies. Every tutorial lists the goal, prerequisites and all steps with the exact labels. (Tutorial texts are in German.)',
    '{n} Videos mit Sprecher und Untertiteln (Deutsch, Englisch) – die Schritte darunter sind der Text zum Mitlesen.' => '{n} videos with narration and captions (German, English) – the steps below are the text to read along.',
    'Zielgruppen' => 'Audiences',
    'Für Sie empfohlen' => 'Recommended for you',
    'Min.' => 'min',
    '+ Smartphone' => '+ smartphone',
    'auf dieser Website aus' => 'off on this website',
    'Einstieg' => 'Beginner',
    'Grundlagen' => 'Basics',
    'Fortgeschritten' => 'Advanced',
    'Nach Änderungen an der Oberfläche oder für ein eigenes Kit lassen sich die Videos neu aufnehmen:' => 'After changes to the interface or for your own kit, the videos can be re-recorded:',
    'Video herunterladen' => 'Download video',
    'Video {d} Min.' => 'Video {d} min',
    'Video: {title}' => 'Video: {title}',
    'Video: {title} auf dem Smartphone' => 'Video: {title} on a smartphone',
    'Auf dieser Website ausgeschaltet' => 'Switched off on this website',
    'Diese Funktion gehört nicht zum Funktionsumfang dieser Website. Das Tutorial zeigt sie trotzdem – fragen Sie bei Bedarf Ihre Agentur.' => 'This feature is not part of this website’s feature set. The tutorial shows it anyway – ask your agency if you need it.',
    'Video mit Sprecher und Untertiteln (Deutsch, Englisch). Der Ton startet erst, wenn Sie das Video abspielen; Untertitel bleiben im Player über „CC“ verfügbar – auch ohne Ton. Die Schritte unten sind der vollständige Text zum Video.' => 'Video with narration and captions (German, English). Sound only starts when you play the video; captions stay available via “CC” in the player – also without sound. The steps below are the complete text of the video.',
    'Text zum Video – jeder Schritt entspricht einem gesprochenen Satz und einem Untertitel.' => 'Text of the video – each step is one spoken sentence and one caption.',
    'Kits, Bearbeiten und Verwalten im Überblick – ohne Ton, mit Untertiteln (Deutsch, Englisch).' => 'Kits, editing and administration at a glance – without sound, with captions (German, English).',
    '{n} Videos ohne Ton, mit Untertiteln (Deutsch, Englisch) – die Schritte darunter sind der Text zum Mitlesen.' => '{n} videos without sound, with captions (German, English) – the steps below are the text to read along.',
    'Video ohne Ton, mit Untertiteln (Deutsch, Englisch). Untertitel im Player über „CC“ ein- und ausschalten. Die Schritte unten sind der vollständige Text zum Video.' => 'Video without sound, with captions (German, English). Switch captions on and off with “CC” in the player. The steps below are the complete text of the video.',
    'Ziel dieses Tutorials' => 'Goal of this tutorial',
    'Voraussetzungen' => 'Prerequisites',
