    'Inhalt' => 'Contents',
    '{name} ist Open Source unter der MIT-Lizenz. Wir danken allen, deren Software, Schriften, Symbole, Daten und Medien wir verwenden – ihre Lizenzen stehen unten.' => '{name} is open source under the MIT License. We thank everyone whose software, fonts, icons, data and media we use – their licenses are listed below.',
    'Die MIT-Lizenz erlaubt es, {name} ohne Einschränkung zu nutzen, anzupassen, weiterzugeben und zu verkaufen – auch kommerziell und in Kundenprojekten. Bedingung ist nur, dass der Copyright- und Lizenzhinweis erhalten bleibt. Eigene Kits und Erweiterungen dürfen unter jeder beliebigen Lizenz stehen. Mitgelieferte Drittsoftware behält ihre eigene Lizenz (siehe unten).' => 'The MIT License lets you use, adapt, redistribute and sell {name} without restriction – including commercially and in client projects. The only condition is that the copyright and license notice is kept. Your own kits and extensions may use any license. Bundled third-party software keeps its own license (see below).',
    'Volltext der MIT-Lizenz (englisch)' => 'Full text of the MIT License',
    'Die folgenden Angaben stammen aus THIRD-PARTY-NOTICES.md im Projektverzeichnis (englisch). Die Lizenztexte liegen neben den ausgelieferten Dateien.' => 'The following information comes from THIRD-PARTY-NOTICES.md in the project directory. The license texts ship next to the bundled files.',
    'THIRD-PARTY-NOTICES.md fehlt in dieser Installation.' => 'THIRD-PARTY-NOTICES.md is missing in this installation.',
    'Sprecherstimmen: Piper TTS – „eva_k“ (M-AILABS Speech Dataset, © 2017–2019 M-AILABS) und „ljspeech“ (LJ Speech Dataset, gemeinfrei).' => 'Narration voices: Piper TTS – “eva_k” (M-AILABS Speech Dataset, © 2017–2019 M-AILABS) and “ljspeech” (LJ Speech Dataset, public domain).',
