    'Seiten, die den Block verwenden, verlieren nach der nächsten Freigabe die Inhalte dieses Felds.' => 'Pages using the block will lose this field’s content after the next release.',
    'Selektoren ohne Präfix schreiben – sie gelten automatisch nur innerhalb des Blocks. :scope ist der Block selbst, :dark der Block auf dunklem Hintergrund. Farben über var(--cb-accent), var(--cb-surface), var(--cb-line), var(--cb-radius), var(--cb-gap) – so wirken Design-Einstellungen weiter.' => 'Write selectors without a prefix – they automatically only apply inside the block. :scope is the block itself, :dark the block on a dark background. Colours via var(--cb-accent), var(--cb-surface), var(--cb-line), var(--cb-radius), var(--cb-gap) – so design settings keep working.',
