    // KI-Chats: Assistent der Redaktion (Core\AI\Assistant) und Besucher-Chat (Core\AI\VisitorChat)
    '0 = unbegrenzt. Zählt getrennt vom Tageslimit der Redaktion. Zusätzlich gilt je Besucher: {m} Fragen pro Minute, {d} pro Tag.' => '0 = unlimited. Counted separately from the editors’ daily limit. In addition, each visitor may ask {m} questions per minute and {d} per day.',
    'Absatz für die Datenschutzerklärung (vor dem Einschalten übernehmen):' => 'Paragraph for the privacy policy (add it before switching the chat on):',
