    'Bitte eine Frage oder einen Auftrag eingeben.' => 'Please enter a question or a task.',
    'Braucht KI für Texte und die Website-Suche. Vorher den Datenschutz-Absatz (unten) in die Datenschutzerklärung übernehmen.' => 'Requires AI for texts and the website search. Add the privacy paragraph (below) to your privacy policy first.',
    'Dafür fehlt Ihrer Rolle die Berechtigung.' => 'Your role does not have permission for this.',
    'Datenschutz-Hinweis vor der ersten Frage' => 'Privacy notice before the first question',
    'Datentabelle nicht gefunden.' => 'Data table not found.',
    'Der Assistent braucht JavaScript.' => 'The assistant requires JavaScript.',
    'Der Assistent ist auf dieser Website nicht eingeschaltet. Die Administration schaltet KI (Texte) und den Assistenten unter Grundeinstellungen → KI ein.' => 'The assistant is not switched on for this website. Administrators enable AI (texts) and the assistant under Basic settings → AI.',
    'Der Chat braucht die Website-Suche (Funktion „search“).' => 'The chat requires the website search (feature “search”).',
    'Der Hinweisbalken ist sofort auf der Website sichtbar.' => 'The notice bar is visible on the website immediately.',
    'Der Text enthält Platzhalter [bitte ergänzen: …] – vor dem Veröffentlichen ausfüllen.' => 'The text contains placeholders [bitte ergänzen: …] – fill them in before publishing.',
    'Der Vorschlag ist abgelaufen oder wurde verändert. Bitte erneut fragen.' => 'The suggestion has expired or was changed. Please ask again.',
    'Die Seite wird als unveröffentlichter Entwurf angelegt.' => 'The page is created as an unpublished draft.',
    'Diese Aktion kann der Assistent nicht ausführen (nur Entwürfe, nichts löschen oder veröffentlichen).' => 'The assistant cannot run this action (drafts only – it never deletes or publishes).',
    'Diese Unterhaltung endgültig löschen?' => 'Delete this conversation permanently?',
    'Diese Änderung wäre sofort öffentlich – dafür fehlt Ihrer Rolle das Recht „Einträge veröffentlichen“.' => 'This change would be public immediately – your role lacks the “Publish entries” permission.',
    'Dieses Feld kann der Assistent nicht ändern (nur Textfelder).' => 'The assistant cannot change this field (text fields only).',
    'Dieses Kit hat keinen Textblock.' => 'This kit has no text block.',
    'Ein Chat-Knopf auf der Website beantwortet Fragen von Besuchern – ausschließlich aus den Inhalten dieser Website (Suchindex, FAQ, Einträge, Kontakt und Öffnungszeiten) und mit Links zu den Quellen. Findet er nichts, sagt er das und bietet den Kontakt an. Fragen und Antworten werden nicht gespeichert, es gibt keine Cookies.' => 'A chat button on the website answers visitors’ questions – only from this website’s content (search index, FAQ, entries, contact details and opening hours) and with links to the sources. If it finds nothing, it says so and offers the contact options. Questions and answers are not stored, and there are no cookies.',
    'Eintrag nicht gefunden.' => 'Entry not found.',
    'Eintrag „{t}“ in {table}' => 'Entry “{t}” in {table}',
    'Eintrag „{t}“ → {lang}' => 'Entry “{t}” → {lang}',
    'Erledigt: {what}' => 'Done: {what}',
    'Es fehlt der Text.' => 'The text is missing.',
    'Es fehlt ein Seitentitel.' => 'A page title is missing.',
    'Frage oder Auftrag' => 'Question or task',
    'Fragen Sie, wie etwas geht – die Antworten stammen aus Handbuch, Tutorials und Wissensdatenbank, mit Links zu den Stellen. Der Assistent kann auch Entwürfe vorschlagen; ausgeführt wird erst nach Ihrem Klick auf „Ausführen“.' => 'Ask how something works – the answers come from the manual, tutorials and knowledge base, with links to the relevant sections. The assistant can also suggest drafts; nothing runs until you click “Run”.',
    'Gelöscht.' => 'Deleted.',
    'Gespeicherte Inhalte dieser Unterhaltung löschen? Die Unterhaltung bleibt in diesem Fenster, bis Sie sie schließen.' => 'Delete the saved content of this conversation? It stays in this window until you close it.',
    'Gespeicherte Inhalte gelöscht.' => 'Saved content deleted.',
    'Gespeicherte Unterhaltungen' => 'Saved conversations',
    'Hallo! Ich beantworte Fragen zur Bedienung aus Handbuch, Tutorials und Wissensdatenbank – mit Links zu den Stellen. Ich kann auch Entwürfe vorschlagen; Sie prüfen und führen sie aus.' => 'Hello! I answer questions about using the CMS from the manual, tutorials and knowledge base – with links to the relevant sections. I can also suggest drafts; you review and run them.',
    'Heute noch {n} KI-Aufrufe.' => '{n} AI requests left today.',
    'Heute {used} Antworten (ohne Tageslimit).' => '{used} answers today (no daily limit).',
    'Heute {used} von {cap} Antworten genutzt.' => '{used} of {cap} answers used today.',
    'Hinweisbalken der Website' => 'Website notice bar',
    'KI-Chat auf dieser Website: Wenn Sie den Chat öffnen und eine Frage stellen, wird der Text Ihrer Frage ausschließlich auf unserem eigenen Server von einer KI verarbeitet, um eine Antwort aus den Inhalten dieser Website zu erzeugen (Art. 6 Abs. 1 lit. f DSGVO, berechtigtes Interesse an einer hilfreichen Auskunft). Es werden keine Daten an Dritte übermittelt und keine Cookies gesetzt. Fragen und Antworten werden nicht gespeichert; zum Schutz vor Missbrauch zählen wir Anfragen je verschlüsselter IP-Adresse für höchstens 24 Stunden. Bitte geben Sie im Chat keine personenbezogenen Daten ein.' => 'AI chat on this website: when you open the chat and ask a question, the text of your question is processed exclusively on our own server by an AI to create an answer from the content of this website (Art. 6(1)(f) GDPR, legitimate interest in providing helpful information). No data is passed to third parties and no cookies are set. Questions and answers are not stored; to prevent abuse we count requests per encrypted IP address for at most 24 hours. Please do not enter any personal data in the chat.',
    'KI-Chat auf dieser Website: Wenn Sie den Chat öffnen und eine Frage stellen, übermitteln wir den Text Ihrer Frage (ohne IP-Adresse, ohne Cookies) an {name}, um daraus eine Antwort aus den Inhalten dieser Website zu erzeugen (Art. 6 Abs. 1 lit. f DSGVO, berechtigtes Interesse an einer hilfreichen Auskunft). Mit dem Anbieter besteht ein Vertrag zur Auftragsverarbeitung. Fragen und Antworten werden von uns nicht gespeichert; zum Schutz vor Missbrauch zählen wir Anfragen je gekürzter, verschlüsselter IP-Adresse für höchstens 24 Stunden. Bitte geben Sie im Chat keine personenbezogenen Daten ein.' => 'AI chat on this website: when you open the chat and ask a question, we send the text of your question (without IP address, without cookies) to {name} to create an answer from the content of this website (Art. 6(1)(f) GDPR, legitimate interest in providing helpful information). A data processing agreement is in place with the provider. We do not store questions or answers; to prevent abuse we count requests per shortened, encrypted IP address for at most 24 hours. Please do not enter any personal data in the chat.',
    'Keine gültigen Felder angegeben.' => 'No valid fields given.',
    'Keine Änderung gegenüber dem aktuellen Stand.' => 'No change compared with the current version.',
