    'Überall in der Verwaltung erreichbar (Seitenleiste, Suche ⌘K, Tastenkürzel). Zählt zum Tageslimit oben; Aktionen laufen mit den Rechten der Person und – falls eingestellt – über „Eingereicht“.' => 'Available everywhere in the admin (sidebar, search ⌘K, keyboard shortcut). Counts towards the daily limit above; actions run with the person’s permissions and – if configured – via “Submitted”.',
