    'Tabelle „{name}“ mit Detailseite angelegt und zugeordnet. Prüfen Sie die Zuordnung mit „Vorschau & Test“.' => 'Table “{name}” with detail page created and assigned. Check the mapping with “Preview & test”.',
    'Bitte eine ZIP- oder XML-Datei wählen (Upload fehlgeschlagen).' => 'Please choose a ZIP or XML file (upload failed).',
    'Nur ZIP (openimmo.xml + Bilder) oder XML-Dateien.' => 'Only ZIP (openimmo.xml + images) or XML files.',
    'Datei konnte nicht gespeichert werden.' => 'File could not be saved.',
    'Quelle „{name}“ und {n} Einträge gelöscht.' => 'Source “{name}” and {n} entries deleted.',
    'Quelle „{name}“ gelöscht – die übernommenen Einträge bleiben als normale, bearbeitbare Einträge erhalten.' => 'Source “{name}” deleted – the imported entries remain as normal, editable entries.',
    'Eintrag ist wieder online.' => 'Entry is online again.',
    'Eintrag ausgeblendet (Entwurf) – er bleibt es auch nach dem nächsten Abruf.' => 'Entry hidden (draft) – it stays hidden after the next fetch.',
    'Feeds, JSON-Schnittstellen, XML und OpenImmo regelmäßig abrufen und als Einträge einer Datentabelle speichern – Datenliste, Detailseiten, Suche und API funktionieren damit wie gewohnt. Besucher laden nie etwas von der Quelle.' => 'Fetch feeds, JSON APIs, XML and OpenImmo regularly and store them as entries of a data table – data lists, detail pages, search and API work as usual. Visitors never load anything from the source.',
    'Funktion für diese Website' => 'Feature for this website',
    'Eingeschaltet in der Konfiguration der Website (features → sources).' => 'Switched on in the website configuration (features → sources).',
    'Ausgeschaltet in der Konfiguration der Website (features → sources).' => 'Switched off in the website configuration (features → sources).',
    'Für diese Website einschalten' => 'Switch on for this website',
    'Nur Netzwerk-Administration und Integratoren sehen diesen Schalter. Danach vergibt die Administration das Recht „Externe Quellen einrichten und abrufen“ an Rollen (Administration hat es immer).' => 'Only network administration and integrators see this switch. Afterwards the administration grants the permission “Set up and fetch external sources” to roles (Administration always has it).',
