    'Mit einer Vorlage starten' => 'Start with a template',
    'Vorlagen bringen passende Zuordnungen und – auf Wunsch – eine fertige Datentabelle mit Detailseite mit.' => 'Templates come with suitable mappings and – if desired – a ready-made data table with detail page.',
    'So funktioniert’s' => 'How it works',
    'Quelle anlegen: Adresse, Format und – falls nötig – Anmeldung (Token, Benutzer/Passwort; wird verschlüsselt gespeichert).' => 'Create a source: address, format and – if needed – authentication (token, user/password; stored encrypted).',
    'Zieltabelle wählen oder aus der Vorlage anlegen, dann mit „Vorschau & Test“ die Felder zuordnen.' => 'Choose a target table or create it from the template, then map the fields with “Preview & test”.',
    'Speichern und „Jetzt abrufen“ – danach holt der Zeitplan neue und geänderte Einträge automatisch. Übernommene Einträge sind in der Tabelle nur lesbar.' => 'Save and “Fetch now” – afterwards the schedule fetches new and changed entries automatically. Imported entries are read-only in the table.',
    'Zuverlässig und pünktlich per Cronjob:' => 'Reliable and on time via cron job:',
    'Datum: Formate wie d.m.Y|Y-m-d H:i (leer = automatisch) · Zahl: de oder en (leer = automatisch) · Vorlage: {pfad} {pfad2}' => 'Date: formats like d.m.Y|Y-m-d H:i (empty = automatic) · Number: de or en (empty = automatic) · Template: {path} {path2}',
