    'Beliebte Suchbegriffe führen zur Ergebnisseite. „Beschriftung | Link“ verlinkt direkt, z. B. „Öffnungszeiten | /kontakt“. Die Suche muss eingeschaltet sein (Grundeinstellungen → Funktionen).' => 'Popular search terms lead to the results page. “Label | link” links directly, e.g. “Opening hours | /contact”. Site search must be switched on (Basic settings → Features).',
    'Hintergrundvideo (MP4, ohne Ton)' => 'Background video (MP4, no sound)',
    'Eigene Datei aus der Mediathek (keine Einwilligung nötig), kurz und klein (< 8 MB). Läuft stumm in Schleife, nur ohne „Bewegung reduzieren“ und mit Pause-Schaltfläche. Das Bild dient als Standbild.' => 'Your own file from the media library (no consent needed), short and small (< 8 MB). Plays muted in a loop, only without “reduce motion” and with a pause button. The image serves as the still.',
    'Abdunkelung über Bild und Video' => 'Darkening over image and video',
    'Hält die Schrift lesbar (Kontrast), auch wenn das Video helle Stellen hat.' => 'Keeps the text legible (contrast), even where the video is bright.',
    'Stark (empfohlen)' => 'Strong (recommended)',
    'Mittel' => 'Medium',
    'Verlauf von unten' => 'Gradient from the bottom',
    'Kennzahlen (3–4 empfohlen)' => 'Key figures (3–4 recommended)',
    'Nur belegbare Zahlen. Füllstand leer = aus Prozentwert berechnet, sonst neutrale Skala.' => 'Only verifiable figures. Empty fill level = calculated from a percentage, otherwise a neutral scale.',
    'Skala der Kennzahlen' => 'Scale of the key figures',
    'Termine oder Neuigkeiten aus Tabelle' => 'Events or news from table',
    'Kalender-Tabelle → die nächsten Termine ab heute (Wiederholungen einzeln). Andere Tabelle → die neuesten veröffentlichten Einträge.' => 'Calendar table → the next events from today (repeats listed individually). Other table → the latest published entries.',
