    'Tabelle mit eingeschaltetem „Öffentliches Formular“, z. B. Rückrufwunsch – kurz halten (2–4 Felder).' => 'Table with “public form” switched on, e.g. callback request – keep it short (2–4 fields).',
    'Überschrift über dem Formular' => 'Heading above the form',
    'Beschriftung des Buttons (optional)' => 'Button label (optional)',
