    'Textbreite (wie Fließtext)' => 'Text width (like running text)',
    'Textbreite: in derselben Spalte wie die Fließtexte der Seite. Normal: schmales Formular im Inhaltsbereich. Volle Breite: Felder nutzen den ganzen Inhaltsbereich.' => 'Text width: in the same column as the page’s running text. Normal: narrow form within the content area. Full width: fields use the whole content area.',
    'Mittig: Überschrift, Einleitung und Button stehen zentriert (bei „Normal“ auch das Formular selbst).' => 'Centred: heading, introduction and button are centred (with “Normal” the form itself as well).',
