    'Gebäude' => 'Building',
    'Öffnungszeiten auf der Standortkarte zeigen (falls eingetragen)' => 'Show opening hours on the location card (if entered)',
    'Hinweis zur Anfahrt (optional)' => 'Directions note (optional)',
