    'Zusammen mit „Bild“ entsteht eine Collage. Alt-Texte in der Mediathek pflegen.' => 'Together with “image” this forms a collage. Maintain alt texts in the media library.',
    'Kurze Beschriftung (optional)' => 'Short caption (optional)',
    'Nur echte, freigegebene Stimmen. Statt Porträt erscheinen die Initialen.' => 'Only real, approved testimonials. Initials are shown instead of a portrait.',
    'Zusatz (z. B. Ort, Funktion)' => 'Addition (e.g. place, role)',
