    'Laufzeile (optional)' => 'Scrolling line (optional)',
    'Begriffe mit „·“ trennen, z. B. „Beratung · Planung · Umsetzung“. Läuft langsam, hält per Schaltfläche, Maus oder Tastatur und steht bei „Bewegung reduzieren“ still.' => 'Separate terms with “·”, e.g. “Advice · Planning · Delivery”. Moves slowly, pauses via button, mouse or keyboard and stands still with “reduce motion”.',
    // Einstieg „Such-Einstieg“ (Kits)
    'Die Website-Suche ist ausgeschaltet (Grundeinstellungen → Funktionen) – es erscheinen nur die Links.' => 'Site search is switched off (Basic settings → Features) – only the links are shown.',
    // Kopfbereich-Aktionen (Core\HeaderActions)
    'Aktionen rechts' => 'Actions on the right',
    'Am Kontakt-Chip und am Statuspunkt – berechnet aus den Öffnungszeiten. Bezeichnung (z. B. „Hofladen“): Website → Darstellung.' => 'On the contact chip and the status dot – calculated from the opening hours. Label (e.g. “Farm shop”): Website → Appearance.',
