    'Anordnung' => 'Arrangement',
    'Anrufen' => 'Call',
    'Aufklappliste' => 'Drop-down list',
    'Beim Stil „Geteilt“ die kleine Schaltfläche neben der Aktion (Standard: Anrufen, sonst E-Mail).' => 'With the “Split” style, the small button next to the action (default: call, otherwise email).',
    'Bezeichnung für den Öffnungsstatus (optional)' => 'Label for the opening status (optional)',
    'E-Mail schreiben' => 'Send an email',
    'Ergibt „Hofladen geöffnet“ statt „Jetzt geöffnet“.' => 'Shows “Farm shop open” instead of “Open now”.',
    'Für den Inhalt „Eigene Beschriftung und Link“. Kurz halten, z. B. „Termin anfragen“.' => 'For the content “Custom label and link”. Keep it short, e.g. “Book an appointment”.',
