    'Stil, Suche und Anordnung: Verwaltung → Design → „Kopfbereich: Suche & Aktionen“.' => 'Style, search and arrangement: Administration → Design → “Header: search & actions”.',
    'Suche im Kopfbereich' => 'Search in the header',
    'Termin anfragen' => 'Book an appointment',
    'Z. B. der Mitgliederbereich. Erscheint, wenn im Design eingeschaltet.' => 'E.g. the members’ area. Shown when switched on in Design.',
    'Ziel und Beschriftung: Website → Darstellung.' => 'Target and label: Website → Appearance.',
