    'Zweite Aktion – Link' => 'Second action – link',
    'z. B. Hofladen, Praxis, Büro' => 'e.g. farm shop, practice, office',
    'Öffnungsstatus zeigen („jetzt geöffnet“)' => 'Show opening status (“open now”)',
    'Befehlsfeld ⌘K' => 'Command field ⌘K',
    'Beide' => 'Both',
