    'Gefüllt' => 'Filled',
    'Geteilt' => 'Split',
    'Kein' => 'None',
    'Kontur' => 'Outline',
    'Kürzel' => 'Codes',
    'Kürzel („DE · EN“), Aufklappliste oder Sprachnamen als Text. Nur bei mehreren Sprachen. Bewusst ohne Flaggen – Sprachen sind keine Länder.' => 'Codes (“DE · EN”), drop-down list or language names as text. Only with several languages. Deliberately without flags – languages are not countries.',
    'Lupe' => 'Magnifier',
    'Lupe mit Feld darunter, Suchfeld in der Leiste mit Vorschlägen, Lupe, die sich zum Feld aufzieht, Befehlsfeld „Suchen … ⌘K“ oder Suchleiste über die ganze Breite unter dem Kopf. Nur bei eingeschalteter Website-Suche; „/“ oder ⌘K bzw. Strg+K springt hinein, Escape schließt. Mobil: Lupe bzw. Feld im Menü.' => 'Magnifier with a field below, search field in the bar with suggestions, magnifier that expands into a field, command field “Search … ⌘K” or a full-width search bar below the header. Only with the website search switched on; “/” or ⌘K / Ctrl+K jumps in, Escape closes. On phones: magnifier or field in the menu.',
    'Namen' => 'Names',
    'Suche darunter' => 'Search below',
    'Suche mittig' => 'Search centred',
    'Suchfeld' => 'Search field',
    'Suchleiste' => 'Search bar',
    'Symbol + Text' => 'Icon + text',
    'Termin' => 'Appointment',
    'Textlink →' => 'Text link →',
    'Aufziehen' => 'Expand',
    '„Eigene“: Beschriftung und Link aus Website → Darstellung. Vorgaben suchen ihr Ziel selbst: Seite „kontakt“, „termin(e)“ bzw. „newsletter“, sonst den gleichnamigen Abschnitt der Startseite, bei Kontakt/Termin zuletzt E-Mail oder Telefon.' => '“Custom”: label and link from Website → Appearance. Presets find their target themselves: the page “kontakt”, “termin(e)” or “newsletter”, otherwise the section of the same name on the home page, and for contact/appointment finally email or phone.',
    '„Suche mittig“ setzt das Suchfeld zwischen Marke und Menü, „Suche darunter“ in eine eigene Zeile unter der Navigation.' => '“Search centred” places the search field between logo and menu, “Search below” in its own row below the navigation.',
    // Hinweise der Einstiegs-Varianten im Bearbeitungsmodus (Kits)
    'Bitte ein Video (MP4) wählen – das Bild dient als Standbild.' => 'Please choose a video (MP4) – the image serves as the still.',
    'Bitte in der Seitenleiste ein Video (MP4) wählen – bis dahin erscheint ein Farbverlauf bzw. das Bild.' => 'Please choose a video (MP4) in the sidebar – until then a gradient or the image is shown.',
    'Bitte in der Seitenleiste eine Tabelle wählen – Kalender-Tabelle für Termine, andere Tabelle für die neuesten Einträge.' => 'Please choose a table in the sidebar – a calendar table for events, any other table for the latest entries.',
    'Bitte in der Seitenleiste eine Tabelle wählen – es erscheinen die nächsten Termine bzw. die neuesten Einträge.' => 'Please choose a table in the sidebar – the next dates or the latest entries will appear.',
    'Kanäle: im Feld „Kennwerte“ je Zeile „Bezeichnung: Wert“ eintragen.' => 'Channels: enter one “Label: value” per line in the “Key figures” field.',
    'Laufzeile in der Seitenleiste eintragen – Begriffe mit „·“ trennen.' => 'Enter the ticker text in the sidebar – separate terms with “·”.',
    'Noch keine Karten – in der Seitenleiste unter „Karten“ hinzufügen.' => 'No cards yet – add them in the sidebar under “Cards”.',
    'Technische Angaben in der Seitenleiste eintragen – eine pro Zeile, z. B. „Gewicht: 1,2 kg“.' => 'Enter specifications in the sidebar – one per line, e.g. “Weight: 1.2 kg”.',
    'Öffnungszeiten unter „Website“ eintragen – dann erscheinen sie hier mit „Jetzt geöffnet“.' => 'Enter opening hours under “Website” – they will then appear here with “Open now”.',
    'Adressbuch' => 'Address book',
    'Headset' => 'Headset',
    'Kontakt-Menü' => 'Contact menu',
    'Menüpunkt' => 'Menu item',
    'Nur beim Stil „Kontakt-Menü“.' => 'Only with the “Contact menu” style.',
    'Sprechblasen' => 'Speech bubbles',
    'Symbol des Kontakt-Menüs' => 'Contact menu icon',
    'Es muss nicht immer ein Button sein: Button (gefüllt/Kontur) für EINE starke Handlung, „Menüpunkt“ (abgesetzter letzter Punkt der Navigation) für ruhige Websites, „Kontakt-Menü“ (Symbol mit Aufklappliste: Anrufen, E-Mail, Formular, Anfahrt, Öffnungszeiten), wenn mehrere Kontaktwege zählen. Dazu Textlink mit Pfeil, Symbol mit Text, geteilt (Aktion + Anruf-/E-Mail-Taste) und Chip mit Statuspunkt. Ecken immer 8 px, den Look bestimmt das Kit; mobil wandert die Aktion ins Menü oder wird zum Symbol.' => 'It doesn’t always have to be a button: a button (filled/outline) for ONE strong action, “Menu item” (a set-off last item of the navigation) for calm websites, “Contact menu” (icon with a drop-down: call, email, form, directions, opening hours) when several contact channels matter. Also text link with arrow, icon with text, split (action + call/email button) and chip with status dot. Corners always 8 px, the kit decides the look; on phones the action moves into the menu or becomes an icon.',

    // Tutorials: Videos auf der Produkt-Website (config docs_url)
    'Alle Videos auf {host}' => 'All videos on {host}',
    'Das Video zu diesem Tutorial' => 'The video for this tutorial',
    'Der Trailer zeigt Kits, Bearbeiten und Verwalten in rund zwei Minuten – ohne Ton, mit Untertiteln (Deutsch, Englisch, Slowenisch).' => 'The trailer shows kits, editing and admin in about two minutes – silent, with subtitles (German, English, Slovenian).',
    'Die Videos (ohne Ton, mit Untertiteln Deutsch/Englisch) stehen auf {host} – hier finden Sie dieselben Schritte als Text, auch ohne Internet.' => 'The videos (without sound, with German/English subtitles) are on {host} – here you find the same steps as text, even offline.',
    'Die Videos werden nicht mit dem CMS ausgeliefert – so bleibt die Installation klein. Die Verwaltung lädt nichts von {host}; die Links öffnen einen neuen Tab.' => 'The videos are not shipped with the CMS – this keeps the installation small. The admin loads nothing from {host}; the links open a new tab.',
    'Die wichtigsten Aufgaben für die Redaktion, die Administration einer Website und für Agenturen. Jedes Tutorial nennt Ziel, Voraussetzungen und alle Schritte mit den genauen Bezeichnungen.' => 'The key tasks for editors, website admins and agencies. Every tutorial names the goal, the prerequisites and all steps with the exact labels.',
    'Eigene Tutorials für ein Kit:' => 'Your own tutorials for a kit:',
    'Ohne Ton, mit Untertiteln (Deutsch, Englisch) – auf {host}. Die Schritte unten sind der vollständige Text zum Video.' => 'Without sound, with subtitles (German, English) – on {host}. The steps below are the full text of the video.',
    'Trailer auf {host}' => 'Trailer on {host}',
    'Video' => 'Video',
    'Video ansehen' => 'Watch video',
    'Zum Nachlesen.' => 'To read along.',
    '{n} Schritte' => '{n} steps',
    'öffnet {host} in einem neuen Tab' => 'opens {host} in a new tab',

