    'Anfragen verschlüsselt (libsodium) – lesbar nur mit dem geheimen Schlüssel' => 'Requests encrypted (libsodium) – readable only with the secret key',
    'App-Icon und installierbare Web-App (Manifest, Service-Worker).' => 'App icon and installable web app (manifest, service worker).',
    'Apps greifen mit App-Passwort über /dav auf Tabellen zu' => 'Apps access tables via /dav with an app password',
    'Assistent im KI-Bereich und in der Seitenleiste' => 'Assistant in the AI area and in the sidebar',
    'Aufbewahrungsfrist: inbox:purge (täglich empfohlen)' => 'Retention period: inbox:purge (daily recommended)',
    'Aufträge, Protokolle und optimierte Versionen in der Mediathek' => 'Jobs, logs and optimised versions in the media library',
    'Aufträge: video:work (jede Minute empfohlen)' => 'Jobs: video:work (every minute recommended)',
    'Aus = die Grundeinstellungen sind für alle gesperrt, bis die Funktion wieder an ist.' => 'Off = the basic settings are locked for everyone until the feature is on again.',
    'Aus = niemand (auch nicht die Administration) kann Benutzer anlegen oder Rollen ändern, bis die Funktion wieder an ist.' => 'Off = nobody (not even administrators) can create users or change roles until the feature is on again.',
    'Auswahl des Kits in den Grundeinstellungen' => 'Kit selection in the basic settings',
