    'Benutzer und Rollen verwalten.' => 'Manage users and roles.',
    'Bitte bestätigen Sie den Sicherheitshinweis.' => 'Please confirm the security notice.',
    'Block „Karte“, Karten-Skript nur auf Seiten mit Karte' => '“Map” block, map script only on pages with a map',
    'Block „{type}“ auf {n} Seite(n)' => 'Block “{type}” on {n} page(s)',
    'Blöcke „Datenliste“ und „Datensatz-Felder“, Detailseiten' => '“Data list” and “Entry fields” blocks, detail pages',
    'Blöcke „Kalender“ und „Nächste Termine“, öffentliche iCal-Adressen /kalender/….ics' => '“Calendar” and “Upcoming events” blocks, public iCal addresses /kalender/….ics',
    'Braucht: {dep}' => 'Requires: {dep}',
    'Bringt mit' => 'Adds',
    'Chat zwischen Benutzern der Verwaltung (Direktnachrichten, Kanäle).' => 'Chat between admin users (direct messages, channels).',
    'Chat-Knopf und Skript auf der Website (nach Einschalten unter Grundeinstellungen → KI), kein Cookie' => 'Chat button and script on the website (after enabling under Basic settings → AI), no cookie',
    'Cookie-Einwilligung: Dienste, Hinweis, Protokoll.' => 'Cookie consent: services, banner, log.',
    'Core {req} (installiert: {core})' => 'Core {req} (installed: {core})',
