    'Damit ruhen auch: {list}.' => 'This also pauses: {list}.',
    'Das Passwort ist falsch – nichts geändert.' => 'The password is wrong – nothing was changed.',
    'Dateien unter public/media bzw. public/sites/{website}/media' => 'Files under public/media or public/sites/{website}/media',
    'Daten bleiben erhalten. Routen, Menüpunkte, Rechte, CSP-Quellen und Befehle der Erweiterung entfallen ab dem nächsten Aufruf; Cron-Befehle beenden sich ohne Fehler.' => 'Data is kept. The extension’s routes, menu items, permissions, CSP sources and commands disappear from the next request; cron commands exit without an error.',
    'Daten → Externe Quellen' => 'Data → External sources',
    'Deaktivieren' => 'Deactivate',
    'Der Server ruft die eingetragenen Adressen regelmäßig ab' => 'The server regularly fetches the configured addresses',
    'Der Server ruft fremde Adressen ab und übernimmt deren Inhalte in Ihre Website. Nur vertrauenswürdige Quellen eintragen; Zugangsdaten werden verschlüsselt gespeichert, bleiben aber für Administratoren nutzbar.' => 'The server fetches third-party addresses and imports their content into your website. Only add trusted sources; credentials are stored encrypted but remain usable by administrators.',
    'Die Administration dieser Website darf Funktionen und Erweiterungen jetzt selbst schalten (Recht „Funktionen & Erweiterungen“).' => 'This website’s administrators may now switch features and extensions themselves (permission “Features & extensions”).',
    'Die Erweiterung „{name}“ ist nicht installiert.' => 'The extension “{name}” is not installed.',
    'Die REST-API öffnet die Website für Programme: Wer ein Token besitzt, kann – je nach Token – Inhalte lesen, ändern und veröffentlichen. Tokens nur sparsam, mit knapper Berechtigung und Ablaufdatum ausstellen; Änderungen auf Wunsch über „Eingereicht“ prüfen.' => 'The REST API opens the website to programs: anyone with a token can – depending on the token – read, change and publish content. Issue tokens sparingly, with minimal permissions and an expiry date; optionally review changes via “Submitted”.',
    'Dokumentation' => 'Documentation',
    'Eigene Blöcke aus Feldern, sicherer Vorlage und begrenztem CSS bauen.' => 'Build custom blocks from fields, a safe template and limited CSS.',
    'Eigene Datentabellen (Aktuelles, Team, Termine …) mit Listen und Detailseiten.' => 'Custom data tables (news, team, events …) with lists and detail pages.',
    'Ein Kit-Wechsel betrifft die ganze Website – nur einschalten, wenn wirklich gewechselt werden soll.' => 'Switching kits affects the whole website – only enable this if you really want to switch.',
    'Ein Wechsel ändert Aussehen, Blöcke und zentrale Angaben der ganzen Website' => 'A switch changes the look, blocks and central details of the whole website',
    'Eingaben der Besucher als Einträge (Entwurf)' => 'Visitor input as entries (draft)',
    'Eingereicht: Änderungen von API, MCP und KI prüfen und freigeben.' => 'Submitted: review and approve changes from the API, MCP and AI.',
    'Einschalten verlangt Bestätigung und Passwort.' => 'Switching on requires confirmation and your password.',
    'Einwilligungs-Protokoll ohne IP-Adresse und User-Agent' => 'Consent log without IP address or user agent',
    'Ergänzt Ausgabe bzw. Sicherheitsrichtlinie (CSP) der Website.' => 'Extends the website’s output or security policy (CSP).',
    'Erweiterung' => 'Extension',
    'Erweiterungen' => 'Extensions',
    'Externe Anfragen' => 'External requests',
    'Externe Quellen: RSS/Atom, JSON-APIs, XML und OpenImmo in Datentabellen übernehmen.' => 'External sources: import RSS/Atom, JSON APIs, XML and OpenImmo into data tables.',
    'Farben, Schriften und Formen im Style-Editor anpassen.' => 'Adjust colours, fonts and shapes in the style editor.',
    'Formular-Block und /formular/… – Besucher können Einträge anlegen (mit Spam-Schutz)' => 'Form block and /formular/… – visitors can create entries (with spam protection)',
    'Fragen der Besucher gehen an den KI-Anbieter' => 'Visitors’ questions go to the AI provider',
    'Fragen der Redaktion und Seitenkontext gehen an den KI-Anbieter' => 'Editors’ questions and page context go to the AI provider',
    'Freigabe' => 'Delegation',
    'Freigabe für die Website-Administration' => 'Delegation to the website administrators',
    'Freigabe zurückgenommen – Funktionen und Erweiterungen schaltet wieder nur die Agentur.' => 'Delegation withdrawn – only the agency switches features and extensions again.',
    'Freigeben: Eintrag in {file} entfernen oder auf dem Server „php bin/console features:release --site={site}“ ausführen (Sicherung .bak wird angelegt). Danach steuert diese Seite den Schalter.' => 'To release: remove the entry from {file} or run “php bin/console features:release --site={site}” on the server (a .bak backup is created). This page then controls the switch.',
    'Freigegebene eigene Blöcke erscheinen im Editor der Redaktion' => 'Released custom blocks appear in the editors’ block editor',
    'Freischaltung durch die Agentur' => 'Enabled by the agency',
    'Freischaltung durch die Agentur – hier nur lesbar.' => 'Enabled by the agency – read-only here.',
    'Freischaltung durch die Agentur: Diese Übersicht zeigt, was auf Ihrer Website eingeschaltet ist. Änderungen nimmt die Netzwerk-Administration vor.' => 'Enabled by the agency: this overview shows what is switched on for your website. Changes are made by the network administrators.',
    'Funktion' => 'Feature',
