    'Hinweis und Skript auf der Website, sobald ein einwilligungspflichtiger Dienst aktiv ist; Cookie mit der Auswahl' => 'Banner and script on the website as soon as a consent-based service is active; cookie storing the choice',
    'Ich habe den Hinweis gelesen und brauche das wirklich.' => 'I have read the notice and really need this.',
    'Ich habe den Hinweis gelesen und brauche diese Erweiterung.' => 'I have read the notice and need this extension.',
    'Ich habe den Hinweis gelesen und brauche diese Funktion.' => 'I have read the notice and need this feature.',
    'Inhalte' => 'Content',
    'Inhalte der Website – bei Bildern auch Bilddaten – werden an einen KI-Anbieter übertragen. Bei externen Anbietern brauchen Sie einen Auftragsverarbeitungsvertrag und einen Hinweis in der Datenschutzerklärung. KI-Ergebnisse können falsch sein und müssen geprüft werden.' => 'Website content – for images also the image data – is sent to an AI provider. With external providers you need a data processing agreement and a note in the privacy policy. AI results can be wrong and must be checked.',
    'Inhalte in mehreren Sprachen pflegen und ausliefern.' => 'Maintain and deliver content in several languages.',
    'Installiert im Ordner extensions/ oder per Composer. Abschalten ist nicht destruktiv: Daten und Einstellungen bleiben, die Erweiterung wird nur nicht mehr gestartet.' => 'Installed in the extensions/ folder or via Composer. Switching off is non-destructive: data and settings are kept, the extension is simply no longer started.',
    'Je Tabelle eine Datenbanktabelle data_{name}' => 'One database table data_{name} per table',
    'Jede Funktion ist zusätzliche Angriffsfläche, Pflege und ggf. Datenverarbeitung. Abgeschaltete Funktionen sperren ihre Rechte, Menüpunkte, API- und MCP-Werkzeuge automatisch.' => 'Every feature adds attack surface, maintenance and possibly data processing. Switched-off features automatically lock their permissions, menu items, API and MCP tools.',
    'KI-Assistent der Redaktion: Hilfe zur Bedienung und Aktionen mit Bestätigung.' => 'AI assistant for editors: help with using the admin and actions with confirmation.',
    'KI-Assistenten mit Token arbeiten über /mcp mit den Inhalten' => 'AI assistants with a token work with the content via /mcp',
    'KI-Bereich, KI-Knöpfe in Editor und Mediathek, Grundeinstellungen → KI' => 'AI area, AI buttons in the editor and media library, Basic settings → AI',
    'KI-Chat für Besucher, der nur aus den Inhalten der Website antwortet.' => 'AI chat for visitors that only answers from the website’s content.',
    'KI-Funktionen: Texte, Übersetzung, SEO, Alt-Texte, semantische Suche (Symfony AI).' => 'AI features: texts, translation, SEO, alt texts, semantic search (Symfony AI).',
