    'Nur beim Installieren: Download vom Fontsource-Katalog; Besucher laden nichts von Google' => 'Only when installing: download from the Fontsource catalogue; visitors load nothing from Google',
    'Nur für Netzwerk-Administration und Integratoren sichtbar. Mit Freigabe dürfen Rollen mit dem Recht „Funktionen & Erweiterungen“ (Administration hat es) auf dieser Website selbst schalten. Standard: aus.' => 'Only visible to network administrators and integrators. With delegation, roles with the “Features & extensions” permission (administrators have it) may switch things themselves on this website. Default: off.',
    'Nur mit KI-Transkription: Tonspur geht an den eingestellten Dienst (z. B. whisper.cpp lokal)' => 'Only with AI transcription: the audio track goes to the configured service (e.g. whisper.cpp locally)',
