    'Sprachumschalter und Sprach-Adressen (/en/…), hreflang' => 'Language switcher and language addresses (/en/…), hreflang',
    'Startet ffmpeg/ffprobe als Prozesse auf dem Server (proc_open) und verarbeitet hochgeladene Dateien. Nur einschalten, wenn Videos wirklich hier bearbeitet werden; Speicherplatz und CPU-Last im Blick behalten.' => 'Starts ffmpeg/ffprobe as processes on the server (proc_open) and processes uploaded files. Only switch on if videos really are edited here; keep an eye on disk space and CPU load.',
    'Suchindex abgleichen: search:index (empfohlen alle 15 min)' => 'Update the search index: search:index (recommended every 15 min)',
    'Suchindex unter storage/ (Texte der veröffentlichten Seiten), anonyme Suchbegriffe ohne Treffer' => 'Search index under storage/ (texts of published pages), anonymous search terms without results',
    'Suchseite /suche und Suchfeld im Kopf (je nach Kit)' => 'Search page /suche and search field in the header (depending on the kit)',
    'Support & Wissensdatenbank: Probleme melden, Fragen & Antworten.' => 'Support & knowledge base: report problems, questions & answers.',
    'Tabellen mit anderen Websites der Installation teilen.' => 'Share tables with other websites of the installation.',
    'Tabellen und Felder selbst anlegen und ändern (Tabellen-Designer).' => 'Create and change tables and fields yourself (table designer).',
    'Tageszähler; Gesprächsinhalte werden nicht dauerhaft gespeichert' => 'Daily counter; conversation content is not stored permanently',
    'Termine und Kontakte mit Kalender- und Adressbuch-Apps abgleichen.' => 'Sync events and contacts with calendar and address book apps.',
    'Texte und ggf. Bilder gehen an den eingestellten KI-Anbieter (Ollama auf eigenem Server oder externer Dienst)' => 'Texts and possibly images go to the configured AI provider (Ollama on your own server or an external service)',
    'Texte von Besucherinnen und Besuchern gehen an einen KI-Anbieter – auch Angaben, die sie besser nicht eingeben sollten. Datenschutzerklärung ergänzen, Tageslimit setzen, bei externen Anbietern AV-Vertrag abschließen. Antworten können falsch sein.' => 'Visitors’ texts go to an AI provider – including details they had better not enter. Update the privacy policy, set a daily limit, and sign a data processing agreement with external providers. Answers can be wrong.',
    'Token-Hashes, Zeitpunkt der letzten Nutzung, Protokoll der Änderungen' => 'Token hashes, time of last use, change log',
