    '{on} von {total} Funktionen und {ext} von {exts} Erweiterungen sind auf dieser Website eingeschaltet.' => '{on} of {total} features and {ext} of {exts} extensions are switched on for this website.',
    'Öffentliche Formulare legen Einträge in Inhaltstabellen an (z. B. Einreichungen).' => 'Public forms create entries in content tables (e.g. submissions).',
    'Öffnet /dav für Kalender- und Adressbuch-Apps. Wer ein App-Passwort hat, kann freigegebene Tabellen lesen und – je nach Passwort – ändern.' => 'Opens /dav for calendar and address book apps. Anyone with an app password can read shared tables and – depending on the password – change them.',
    'Über MCP arbeiten KI-Assistenten direkt mit den Inhalten dieser Website. Was der Assistent sieht, geht an dessen Anbieter. Tokens nur mit knapper Berechtigung ausstellen und Änderungen bevorzugt über „Eingereicht“ freigeben.' => 'Via MCP, AI assistants work directly with this website’s content. Whatever the assistant sees goes to its provider. Issue tokens only with minimal permissions and preferably approve changes via “Submitted”.',
    'Übernommene Einträge, Zugangsdaten verschlüsselt, Abruf-Protokoll' => 'Imported entries, credentials encrypted, fetch log',
    '„Eingereicht“ mit Vergleich und Freigabe' => '“Submitted” with comparison and approval',
