    '„{label}“ ist ausgeschaltet. Daten und Einstellungen bleiben erhalten; Routen, Menüpunkte, Befehle und Website-Skripte der Erweiterung entfallen.' => '“{label}” is switched off. Data and settings are kept; the extension’s routes, menu items, commands and website scripts disappear.',
    '„{label}“ ist eingeschaltet.' => '“{label}” is switched on.',
    '„{label}“ ist eingeschaltet. Datenbank-Schritte sind erledigt; Menüpunkte erscheinen ab dem nächsten Seitenaufruf.' => '“{label}” is switched on. Database steps are done; menu items appear from the next page load.',
