    '410 – als dauerhaft entfernt gemeldet (Regel #{id}).' => '410 – reported as permanently removed (rule #{id}).',
    '410 – dauerhaft entfernt (ohne Ziel)' => '410 – permanently removed (no target)',
    '410 – entfernt' => '410 – removed',
    'Administration → Weiterleitungen (mit 404-Protokoll, Import und Export)' => 'Administration → Redirects (with 404 log, import and export)',
    'Adresse testen' => 'Test an address',
    'Adressen der Verwaltung und der Schnittstellen können nicht weitergeleitet werden.' => 'Addresses of the admin area and the interfaces cannot be redirected.',
    'Adressen, die Besucher oder Suchmaschinen aufgerufen haben und die es nicht gibt – häufigste zuerst. Gespeichert werden nur Pfad, Anzahl und Zeitpunkte, keine IP-Adressen.' => 'Addresses that visitors or search engines requested and that do not exist – most frequent first. Only the path, count and times are stored, no IP addresses.',
    'Aktuell' => 'Current',
    'Alte Adresse' => 'Old address',
    'Alte Adresse (A–Z)' => 'Old address (A–Z)',
    'Alte Adresse, Ziel, Notiz …' => 'Old address, target, note …',
    'Alte Adressen führen zu Seiten, Pfaden oder anderen Websites. Weitergeleitet wird nur, wenn es unter der Adresse keine Seite gibt – bestehende Seiten gehen immer vor. Beim Umbenennen oder Verschieben veröffentlichter Seiten entstehen Weiterleitungen automatisch.' => 'Old addresses lead to pages, paths or other websites. A redirect only applies when there is no page at the address – existing pages always take precedence. Renaming or moving published pages creates redirects automatically.',
    'Alte Adressen weiterleiten (301/302) oder als entfernt melden (410); beim Umbenennen und Verschieben von Seiten automatisch.' => 'Redirect old addresses (301/302) or report them as removed (410); automatic when pages are renamed or moved.',
    'Am besten eine Seite wählen – sie bleibt verknüpft, auch wenn sie später umbenannt wird. Sonst ein Pfad (/neue-seite/) oder eine vollständige Adresse (https://…). Mit * am Ende der alten Adresse übernimmt ein * im Ziel den Rest (/news/*).' => 'Preferably choose a page – it stays linked even if it is renamed later. Otherwise a path (/new-page/) or a full address (https://…). With * at the end of the old address, a * in the target carries over the rest (/news/*).',
    'Andere Adresse testen →' => 'Test another address →',
    'Anderes Ziel …' => 'Other target …',
    'Aus dem Protokoll entfernen' => 'Remove from log',
    'Ausgeschaltet greifen auch vorhandene Weiterleitungen nicht mehr – alte Adressen enden dann mit 404.' => 'When switched off, existing redirects stop working too – old addresses then end with 404.',
    'Ausgewählte Weiterleitungen löschen? Die alten Adressen enden danach mit 404.' => 'Delete the selected redirects? The old addresses will then end with 404.',
    'Automatisch' => 'Automatic',
    'Automatisch: Adresse geändert zu {path}' => 'Automatic: address changed to {path}',
    'Beim Umbenennen und Verschieben automatisch weiterleiten' => 'Redirect automatically when pages are renamed or moved',
    'Bitte ein Ziel wählen: Seite, Pfad wie /neue-seite/ oder vollständige Adresse (https://…).' => 'Please choose a target: page, path like /new-page/ or full address (https://…).',
    'Bitte eine CSV- oder JSON-Datei wählen oder Zeilen einfügen.' => 'Please choose a CSV or JSON file or paste lines.',
    'Bitte eine alte Adresse angeben, z. B. /alte-seite/ – die Startseite selbst kann nicht weitergeleitet werden.' => 'Please enter an old address, e.g. /old-page/ – the home page itself cannot be redirected.',
    'Bitte zuerst Einträge auswählen.' => 'Please select entries first.',
    'Bitte zuerst Weiterleitungen auswählen.' => 'Please select redirects first.',
    'CSV mit Semikolon (alte Adresse;Ziel;Code;Notiz) oder JSON wie aus einem Umzugs-Mapping:' => 'CSV with semicolons (old address;target;code;note) or JSON as in a migration mapping:',
    'Das 404-Protokoll ist ausgeschaltet – neue Adressen kommen nicht hinzu.' => 'The 404 log is switched off – no new addresses are added.',
    'Das Ziel beginnt wie die alte Adresse – die Weiterleitung würde sich immer wieder selbst treffen.' => 'The target starts like the old address – the redirect would match itself again and again.',
    'Das Ziel wird selbst weitergeleitet (#{id}). Besucher werden nicht zweimal weitergeleitet – besser gleich das endgültige Ziel eintragen.' => 'The target is itself redirected (#{id}). Visitors are not redirected twice – better enter the final target directly.',
    'Das ganze 404-Protokoll leeren?' => 'Clear the entire 404 log?',
    'Das gewählte Ziel gibt es nicht mehr.' => 'The selected target no longer exists.',
    'Datei (CSV oder JSON)' => 'File (CSV or JSON)',
    'Der Aufruf kam von einer Seite dieser Website – dort ist ein Link veraltet.' => 'The request came from a page of this website – a link there is outdated.',
    'Die Adresse gehört zur Seite „{title}“ – Weiterleitungen greifen hier nicht.' => 'The address belongs to the page “{title}” – redirects do not apply here.',
    'Die Datei ist zu groß (höchstens 5 MB).' => 'The file is too large (5 MB maximum).',
    'Die JSON-Datei ist ungültig: {msg}' => 'The JSON file is invalid: {msg}',
    'Die alte Adresse endet danach mit „Seite nicht gefunden“ (404).' => 'The old address will then end with “Page not found” (404).',
    'Doppelt in der Datei (Zeile {n}).' => 'Duplicate in the file (line {n}).',
    'Ein * im Ziel ist nur zusammen mit einem * am Ende der alten Adresse möglich.' => 'A * in the target is only possible together with a * at the end of the old address.',
    'Ein * ist nur am Ende der Adresse erlaubt (alles, was so beginnt).' => 'A * is only allowed at the end of the address (everything that starts like this).',
    'Entfernt' => 'Removed',
    'Exportieren:' => 'Export:',
    'Für Sprachen die Adresse mit Präfix angeben, z. B. /en/old-page/.' => 'For languages, enter the address with its prefix, e.g. /en/old-page/.',
