    'Pfad oder vollständige Adresse, gern mit ?parameter.' => 'Path or full address, parameters (?…) welcome.',
    'Pfad ohne Domain, z. B. /agentur/team/ – Groß/Kleinschreibung und Schrägstrich am Ende sind egal. Mit * am Ende: alle Adressen, die so beginnen (/blog/*).' => 'Path without domain, e.g. /agency/team/ – upper/lower case and a trailing slash do not matter. With * at the end: all addresses starting like this (/blog/*).',
    'Probelauf (nichts gespeichert)' => 'Dry run (nothing saved)',
