    'Seite vorhanden' => 'Page exists',
    'Sobald jemand eine Adresse aufruft, die es nicht gibt, erscheint sie hier – mit Vorschlag für eine Weiterleitung.' => 'As soon as someone requests an address that does not exist, it appears here – with a suggested redirect.',
