    'Ändert sich die Adresse einer veröffentlichten Seite, führt die alte Adresse dauerhaft (301) zur Seite – auch nach weiteren Änderungen.' => 'If the address of a published page changes, the old address leads to the page permanently (301) – even after further changes.',
