    // Hinweise zu diesem Projekt (Core\Guide)
    'Anpassung entfernen' => 'Remove customisation',
    'Anpassung entfernen? Danach gilt wieder der Hinweis aus dem Kit.' => 'Remove the customisation? The note from the kit will apply again.',
    'Anpassung entfernt – es gilt wieder der Hinweis aus dem Kit.' => 'Customisation removed – the note from the kit applies again.',
    'Bezug' => 'Relates to',
    'Bitte einen Text eingeben.' => 'Please enter a text.',
    'Dateien der Website: {dir}' => 'Website files: {dir}',
    'Dateiname' => 'File name',
    'Der Text ist zu lang.' => 'The text is too long.',
    'Diesen Dateinamen gibt es schon.' => 'This file name already exists.',
    'Diesen Hinweis löschen?' => 'Delete this note?',
    'Dieser Hinweis kommt aus dem Kit. Beim Speichern entsteht eine eigene Fassung für diese Website – das Kit bleibt unverändert.' => 'This note comes from the kit. Saving creates a separate version for this website – the kit remains unchanged.',
    'Erste Zeile „# Titel“. Dann Absätze, Listen mit „-“, Zwischentitel mit „##“, **fett**, *kursiv*, `Code` und Links [Text](https://… oder /admin/…). HTML ist nicht erlaubt.' => 'First line “# Title”. Then paragraphs, lists with “-”, subheadings with “##”, **bold**, *italic*, `code` and links [text](https://… or /admin/…). HTML is not allowed.',
    'Format (Technische Dokumentation) →' => 'Format (technical documentation) →',
    'Für diese Website anpassen' => 'Customise for this website',
    'Hinweis (z. B. aus dem Kit) für diese Website ausblenden.' => 'hide a note (e.g. from the kit) for this website.',
    'Hinweis anlegen' => 'Create note',
    'Hinweis zum Projekt' => 'Project note',
    'Hinweis zum Projekt:' => 'Project note:',
    'Hinweise zu diesem Projekt' => 'Notes on this project',
    'Hinweise zu diesem Projekt ergänzen das Handbuch für die Redaktion: eigene Blöcke, Bildformate, Abläufe. Das Kit „{kit}“ kann welche mitbringen; hier legen Sie eigene für diese Website an oder passen die des Kits an. Das Kapitel im Handbuch erscheint nur, wenn es Hinweise gibt.' => 'Notes on this project supplement the editors’ manual: custom blocks, image formats, workflows. The kit “{kit}” can ship notes; here you create your own for this website or customise those of the kit. The manual chapter only appears when there are notes.',
    'Hinweise zum Projekt:' => 'Project notes:',
    'Kit: {dir}' => 'Kit: {dir}',
    'Kleinbuchstaben, Ziffern, - und _. Die Zahl vorn bestimmt die Reihenfolge im Handbuch (10-…, 20-…). Gleicher Name wie ein Hinweis aus dem Kit ersetzt diesen.' => 'Lower-case letters, digits, - and _. The leading number sets the order in the manual (10-…, 20-…). The same name as a kit note replaces it.',
    'Kopfzeilen (optional)' => 'Header lines (optional)',
    'Link im Formular dieser Blocktypen.' => 'link in the form of these block types.',
    'Link „Hinweis zum Projekt“ in diesem Bereich der Verwaltung: seiten, einstellungen, medien, daten, daten/{tabelle}, anfragen, design.' => 'link “Project note” in this admin area: seiten, einstellungen, medien, daten, daten/{tabelle}, anfragen, design.',
    'Neuer Hinweis' => 'New note',
