    'Nur Kleinbuchstaben, Ziffern, - und _ (z. B. 10-startseite) – die Zahl vorn bestimmt die Reihenfolge.' => 'Only lower-case letters, digits, - and _ (e.g. 10-homepage) – the leading number sets the order.',
