    // Einladungen (Core\Invites): Benutzer & Rollen → „Person einladen“, Seite „Einladung annehmen“, E-Mail
    'Am besten eine Passphrase aus mehreren Wörtern oder ein Passwort aus Ihrem Passwortmanager.' => 'Ideally a passphrase of several words or a password from your password manager.',
