    'Funktioniert die Schaltfläche nicht? Kopieren Sie diese Adresse in Ihren Browser:' => 'Button not working? Copy this address into your browser:',
    'Für Ihre Rolle ist ein Passkey vorgeschrieben. Legen Sie ihn hier an – oder direkt nach der ersten Anmeldung.' => 'A passkey is required for your role. Create it here – or right after your first sign-in.',
    'Für Ihre Rolle ist ein zweiter Faktor vorgeschrieben. Ein Passkey erfüllt ihn; mit Passwort richten Sie ihn nach der ersten Anmeldung ein.' => 'A second factor is required for your role. A passkey fulfils it; with a password you set it up after your first sign-in.',
