    'Bildfläche – im Werkzeug Drehen und Ausrichten ändern die Pfeiltasten den Winkel' => 'Image area – in the Rotate and Straighten tools, the arrow keys change the angle',
    'Das Entzerren dauert auf diesem Server zu lange. Bitte ein kleineres Bild verwenden.' => 'Perspective correction takes too long on this server. Please use a smaller image.',
    'Das Raster hilft, Horizont und Kanten gerade zu richten. Oder mit „Horizont ziehen“ eine Linie entlang des Horizonts oder einer Kante ziehen – der Winkel wird daraus berechnet.' => 'The grid helps you level the horizon and edges. Or use “Draw horizon” to draw a line along the horizon or an edge – the angle is calculated from it.',
    'Die Bildwerkzeuge gibt es nur für Fotos (JPG, PNG, WebP).' => 'The image tools are only available for photos (JPG, PNG, WebP).',
    'Die Ecken ergeben kein gültiges Viereck.' => 'The corners do not form a valid quadrilateral.',
    'Die vier Ecken auf die Ecken einer schrägen Fläche ziehen (Gebäude, Schild, Bildschirm, Dokument) – sie wird gerade gerückt. Pfeiltasten verschieben die gewählte Ecke, mit ⇧ in großen Schritten.' => 'Drag the four corners onto the corners of a skewed surface (building, sign, screen, document) – it will be straightened. Arrow keys move the selected corner, ⇧ in large steps.',
