    // SVG-Grafiken (Core\Svg): Bereinigen, Optimieren, Upload-Meldungen
    '1 unsicheres Element entfernt' => '1 unsafe element removed',
    '{n} unsichere Elemente entfernt' => '{n} unsafe elements removed',
    'SVG bereinigt und optimiert: {in} → {out}' => 'SVG sanitised and optimised: {in} → {out}',
    'Das App-Icon kann nicht aus einer SVG erzeugt werden: Auf diesem Server fehlt Imagick mit SVG-Unterstützung. Bitte das Logo als PNG (mind. 512 × 512 px) wählen.' => 'The app icon cannot be generated from an SVG: this server lacks Imagick with SVG support. Please choose the logo as a PNG (at least 512 × 512 px).',
    'Die SVG enthält nach dem Bereinigen nichts Darstellbares – bitte die Datei prüfen oder als PNG hochladen.' => 'After sanitising, the SVG contains nothing that can be displayed – please check the file or upload it as a PNG.',
    'Die SVG hat keine Größe (viewBox oder width/height fehlen). Bitte im Grafikprogramm mit Zeichenfläche exportieren.' => 'The SVG has no size (viewBox or width/height missing). Please export it with an artboard from your graphics program.',
    'Diese SVG enthält eingebettete Bilddaten (z. B. ein Bildschirmfoto). Bitte als PNG, JPG oder WebP hochladen – SVG ist nur für Vektorgrafiken erlaubt.' => 'This SVG contains embedded image data (e.g. a screenshot). Please upload it as PNG, JPG or WebP – SVG is only allowed for vector graphics.',
    'Diese SVG enthält eingebettete Schriftdateien. Bitte die Texte im Grafikprogramm in Pfade umwandeln und erneut als SVG speichern.' => 'This SVG contains embedded font files. Please convert the text to outlines in your graphics program and save it as SVG again.',
    'Gespeichert wird nur die bereinigte Fassung (ohne Skripte, externe Verweise, eingebettete Bilder)' => 'Only the sanitised version is stored (without scripts, external references or embedded images)',
    'Keine gültige SVG-Datei (Maße unplausibel).' => 'Not a valid SVG file (implausible dimensions).',
    'Keine gültige SVG-Datei (fehlerhafte DOCTYPE-Angabe).' => 'Not a valid SVG file (malformed DOCTYPE).',
    'Keine gültige SVG-Datei (kein lesbares XML mit <svg> als Wurzel).' => 'Not a valid SVG file (no readable XML with <svg> as root).',
    'Keine gültige SVG-Datei.' => 'Not a valid SVG file.',
    'Komprimierte SVG-Dateien (.svgz) werden nicht unterstützt – bitte als normale SVG speichern.' => 'Compressed SVG files (.svgz) are not supported – please save as a regular SVG.',
    'Mediathek nimmt .svg an' => 'Media library accepts .svg',
    'SVG ist zu groß (max. {mb} MB). Bitte vereinfachen oder als PNG hochladen.' => 'SVG is too large (max. {mb} MB). Please simplify it or upload it as a PNG.',
    'SVG ist zu komplex (mehr als {n} Elemente).' => 'SVG is too complex (more than {n} elements).',
    'SVG ist zu komplex (zu viele verschachtelte Wiederholungen).' => 'SVG is too complex (too many nested repetitions).',
    'SVG ist zu tief verschachtelt.' => 'SVG is nested too deeply.',
    'SVG-Grafik: wird immer vollständig und in jeder Größe scharf gezeigt – Fokuspunkt und Zuschnitte entfallen.' => 'SVG graphic: always shown in full and sharp at any size – focus point and crops do not apply.',
    'SVG-Grafiken hochladen (bereinigt)' => 'Upload SVG graphics (sanitised)',
    'SVG-Grafiken (Logos, Icons, Illustrationen) hochladen – nur bereinigt und optimiert.' => 'Upload SVG graphics (logos, icons, illustrations) – sanitised and optimised only.',
    'SVG-Grafiken kann die KI auf diesem Server nicht ansehen – bitte den Alt-Text selbst eingeben.' => 'The AI cannot view SVG graphics on this server – please enter the alt text yourself.',
    'SVG-Grafiken werden immer vollständig gezeigt – ein Zuschnitt ist nicht nötig.' => 'SVG graphics are always shown in full – no crop is needed.',
    'SVG-Uploads sind auf dieser Website ausgeschaltet (Funktionen & Erweiterungen → „SVG-Grafiken hochladen“).' => 'SVG uploads are switched off on this website (Features & extensions → “Upload SVG graphics”).',

