    // Anmeldedaten (Core\EmailChange, AccountController, app/Admin/views/account*.php, mail/account*.php)
    'Anmeldedaten' => 'Sign-in details',
    'Womit Sie sich bei dieser Website anmelden. Änderungen bestätigen Sie mit Ihrem Passwort bzw. Passkey; bei jeder Änderung erhalten Sie eine E-Mail.' => 'How you sign in to this website. You confirm changes with your password or passkey; every change is followed by an email.',
    'Anmeldung nur mit Passkey' => 'sign-in with passkey only',
    'festgelegt' => 'set',
    'keins' => 'none',
    'verwalten' => 'manage',
    'einrichten' => 'set up',
    'Zwei-Faktor (App)' => 'Two-factor (app)',
    'Änderung wartet' => 'Change pending',
    'Änderung wartet auf Bestätigung' => 'Change awaiting confirmation',
    'Änderung abgelaufen' => 'Change expired',
    'Neue Adresse: {email}' => 'New address: {email}',
    'Öffnen Sie den Link in der E-Mail an die neue Adresse und bestätigen Sie dort (gültig bis {date}). Bis dahin melden Sie sich weiter mit {old} an.' => 'Open the link in the email sent to the new address and confirm there (valid until {date}). Until then, keep signing in with {old}.',
    'Der Link ist am {date} abgelaufen. Ihre Adresse ist unverändert – senden Sie einen neuen Link oder brechen Sie ab.' => 'The link expired on {date}. Your address is unchanged – send a new link or cancel.',
    'Die letzte E-Mail wurde nicht zugestellt (E-Mail-Versand nicht eingerichtet oder Testumgebung). Ohne Bestätigung ändert sich nichts.' => 'The last email was not delivered (email sending not set up, or test environment). Nothing changes without confirmation.',
    'Änderung auf {email} abbrechen? Die Links in den E-Mails gelten dann nicht mehr.' => 'Cancel the change to {email}? The links in the emails will stop working.',
    'Ihr Konto hat kein Passwort. Bestätigen Sie zuerst mit Ihrem Passkey, dass Sie es sind – danach können Sie 15 Minuten lang E-Mail-Adresse und Passwort ändern.' => 'Your account has no password. First confirm it is you with your passkey – you can then change your email address and password for 15 minutes.',
    'E-Mail-Adresse ändern' => 'Change email address',
    'Wir senden einen Bestätigungslink an die neue Adresse – erst damit gilt sie. Ihre bisherige Adresse erhält einen Hinweis mit der Möglichkeit, die Änderung abzubrechen. Passkeys gelten weiter.' => 'We send a confirmation link to the new address – it only takes effect once confirmed. Your current address receives a notice with the option to cancel the change. Passkeys keep working.',
    'Neue E-Mail-Adresse' => 'New email address',
    'Bestätigungslink senden' => 'Send confirmation link',
    'Optional: Mit einem Passwort können Sie sich auch ohne Passkey anmelden, z. B. an einem fremden Gerät.' => 'Optional: with a password you can also sign in without a passkey, e.g. on someone else\'s device.',
    'Andere Sitzungen Ihres Kontos enden, diese bleibt angemeldet. Sie erhalten eine Hinweis-E-Mail.' => 'Other sessions of your account end; this one stays signed in. You will receive a notification email.',
    'Profil' => 'Profile',
    'Erscheint u. a. im Chat, bei Freigaben und in Einladungen.' => 'Shown in chat, approvals and invitations, among other places.',
    'Name speichern' => 'Save name',
    'Name gespeichert.' => 'Name saved.',
    'Ihre Anmeldedaten verwalten Sie in der Netzwerk-Verwaltung.' => 'You manage your sign-in details in the network administration.',
    'Sie sind mit Ihrem zentralen Netzwerk-Konto angemeldet. E-Mail-Adresse, Passwort, Name und Zwei-Faktor-Anmeldung ändern Sie dort – die Änderung gilt dann für alle Websites.' => 'You are signed in with your central network account. Change your email address, password, name and two-factor sign-in there – the change then applies to all websites.',
    'Zu viele Änderungsanfragen. Bitte warten Sie eine Stunde.' => 'Too many change requests. Please wait an hour.',
    'Das ist bereits Ihre E-Mail-Adresse.' => 'That is already your email address.',
    'Das aktuelle Passwort ist falsch.' => 'The current password is incorrect.',
    'Bitte bestätigen Sie zuerst mit Ihrem Passkey, dass Sie es sind.' => 'Please first confirm it is you with your passkey.',
    'Fast geschafft: Wir haben einen Bestätigungslink an {email} gesendet. Die neue Adresse gilt, sobald Sie den Link öffnen und bestätigen (24 Stunden gültig).' => 'Almost done: we have sent a confirmation link to {email}. The new address applies as soon as you open the link and confirm (valid for 24 hours).',
    'Neuer Bestätigungslink an {email} gesendet – der vorige gilt nicht mehr.' => 'New confirmation link sent to {email} – the previous one no longer works.',
    'Es gibt keine offene Änderung.' => 'There is no pending change.',
    'Änderung abgebrochen – Ihre E-Mail-Adresse bleibt unverändert, die Links gelten nicht mehr.' => 'Change cancelled – your email address stays the same, the links no longer work.',
    'Die E-Mail an {email} wurde nicht zugestellt (Testumgebung oder Versand deaktiviert – nur protokolliert, umgeleitet oder als Datei abgelegt).' => 'The email to {email} was not delivered (test environment or sending disabled – only logged, redirected or saved as a file).',
    'Ihre Adresse bleibt unverändert, bis der Link bestätigt ist. Bitten Sie die Administration, den E-Mail-Versand einzurichten oder Ihre Adresse unter „Benutzer & Rollen“ zu ändern.' => 'Your address stays unchanged until the link is confirmed. Ask the administration to set up email sending or to change your address under “Users & roles”.',
    'Passwort geändert.' => 'Password changed.',
    'Passwort festgelegt – Sie können sich jetzt auch mit Passwort anmelden.' => 'Password set – you can now also sign in with a password.',
    'Passwort bestätigt – für 15 Minuten.' => 'Password confirmed – for 15 minutes.',
    'Mit Passkey bestätigt – für 15 Minuten.' => 'Confirmed with passkey – for 15 minutes.',
    'Zum Hinzufügen oder Löschen von Passkeys bestätigen Sie bitte zuerst mit einem Passkey (gilt 15 Minuten).' => 'To add or delete passkeys, please first confirm with a passkey (valid for 15 minutes).',
    'Für Ihr Konto ist kein Passwort festgelegt und auf dieser Adresse kein Passkey eingerichtet. Melden Sie sich bitte ab und wieder an – danach gilt die Anmeldung 15 Minuten als Bestätigung.' => 'Your account has no password and no passkey for this address. Please sign out and in again – the sign-in then counts as confirmation for 15 minutes.',
    // Benutzer & Rollen: E-Mail-Adresse ändern
    'E-Mail ändern' => 'Change email',
    'Neue E-Mail-Adresse für {name}' => 'New email address for {name}',
    'Gilt sofort, ohne Bestätigung. Beide Adressen erhalten einen Hinweis, die Sitzungen des Kontos enden. Personen ändern ihre Adresse sonst selbst unter „Konto“.' => 'Applies immediately, without confirmation. Both addresses receive a notice and the account\'s sessions end. Otherwise people change their address themselves under “Account”.',
    'Adresse ändern' => 'Change address',
    'Ihre eigene Adresse ändern Sie unter „Konto › Anmeldedaten“ – mit Bestätigung.' => 'Change your own address under “Account › Sign-in details” – with confirmation.',
    'Dieses Konto hat mehr Rechte als Ihres – die Adresse kann nur eine Administration mit allen Rechten ändern.' => 'This account has more permissions than yours – only an administrator with full permissions can change its address.',
    'Zu viele Änderungen in kurzer Zeit. Bitte warten Sie eine Stunde.' => 'Too many changes in a short time. Please wait an hour.',
    'E-Mail-Adresse von {old} auf {new} geändert – beide Adressen wurden benachrichtigt, Sitzungen des Kontos beendet.' => 'Email address changed from {old} to {new} – both addresses were notified, the account\'s sessions ended.',
    // Links aus den E-Mails
    'E-Mail-Adresse bestätigen' => 'Confirm email address',
    'Änderung abbrechen' => 'Cancel change',
    'Dieser Link gilt nicht mehr' => 'This link is no longer valid',
    'Der Link ist abgelaufen, wurde bereits verwendet oder die Änderung wurde abgebrochen.' => 'The link has expired, has already been used, or the change was cancelled.',
    'Möchten Sie Ihre E-Mail-Adresse ändern? Melden Sie sich an und fordern Sie unter „Konto › Anmeldedaten“ einen neuen Link an.' => 'Want to change your email address? Sign in and request a new link under “Account › Sign-in details”.',
    'E-Mail-Adresse geändert' => 'Email address changed',
    'Ab jetzt melden Sie sich mit {email} an. Ihre Passkeys gelten weiter; andere Sitzungen Ihres Kontos wurden beendet. Eine Bestätigung ging an beide Adressen.' => 'From now on you sign in with {email}. Your passkeys keep working; other sessions of your account were ended. A confirmation went to both addresses.',
    'Zum Konto' => 'Go to account',
    'Änderung abgebrochen' => 'Change cancelled',
    'Ihre E-Mail-Adresse bleibt unverändert. Zur Sicherheit wurden alle Sitzungen Ihres Kontos beendet – auch eine, die jemand anderes vielleicht geöffnet hatte.' => 'Your email address stays the same. For your security, all sessions of your account were ended – including any that someone else may have opened.',
    'Bitte melden Sie sich an und ändern Sie Ihr Passwort. Prüfen Sie unter „Konto“ auch Ihre Passkeys und informieren Sie die Administration der Website.' => 'Please sign in and change your password. Also check your passkeys under “Account” and inform the website\'s administration.',
    'Neue E-Mail-Adresse bestätigen' => 'Confirm new email address',
    'Ihr Konto soll künftig diese E-Mail-Adresse verwenden:' => 'Your account is to use this email address from now on:',
    'Adresse bestätigen' => 'Confirm address',
    'Der Link gilt bis {date} und nur einmal. Danach melden Sie sich mit der neuen Adresse an; andere Sitzungen enden.' => 'The link is valid until {date} and only once. Afterwards you sign in with the new address; other sessions end.',
    'Das war ich nicht' => 'That wasn\'t me',
    'Brechen Sie die Änderung Ihrer E-Mail-Adresse ab, wenn Sie sie nicht selbst angefordert haben. Ihre Adresse bleibt dann unverändert.' => 'Cancel the change of your email address if you did not request it yourself. Your address then stays the same.',
    'Zur Sicherheit enden dabei alle Sitzungen Ihres Kontos. Ändern Sie danach Ihr Passwort.' => 'For your security, all sessions of your account end as well. Change your password afterwards.',
    // E-Mails
    'Diese E-Mail wurde automatisch zu Ihrem Konto versendet.' => 'This email was sent automatically about your account.',
    'Neue E-Mail-Adresse bestätigen – {site}' => 'Confirm your new email address – {site}',
    'Bitte bestätigen Sie Ihre neue E-Mail-Adresse' => 'Please confirm your new email address',
    'Sie möchten die E-Mail-Adresse Ihres Kontos bei {site} ändern. Die Änderung wird erst wirksam, wenn Sie sie hier bestätigen.' => 'You want to change the email address of your account at {site}. The change only takes effect once you confirm it here.',
    'Neue Adresse bestätigen' => 'Confirm new address',
    'Der Link gilt bis {date} und nur einmal.' => 'The link is valid until {date} and only once.',
    'Sie haben das nicht angefordert? Dann ignorieren Sie diese E-Mail – die Adresse bleibt unverändert.' => 'Didn\'t request this? Then ignore this email – the address stays the same.',
    'Hinweis zu Ihrem Konto bei {site}' => 'Notice about your account at {site}',
    'Diese Adresse hat bereits ein Konto' => 'This address already has an account',
    'Für ein anderes Konto bei {site} wurde angefragt, die E-Mail-Adresse auf {email} zu ändern. Zu dieser Adresse gibt es bereits ein Konto – deshalb wird nichts geändert.' => 'Someone requested to change the email address of another account at {site} to {email}. An account already exists for this address – so nothing will be changed.',
    'Sie müssen nichts tun. Wenn Sie zwei Konten zusammenlegen möchten, wenden Sie sich an die Administration der Website.' => 'You don\'t need to do anything. If you want to merge two accounts, contact the website\'s administration.',
    'Ihre E-Mail-Adresse soll geändert werden – {site}' => 'Your email address is about to be changed – {site}',
    'Ihre E-Mail-Adresse soll geändert werden' => 'Your email address is about to be changed',
    'Ihre E-Mail-Adresse soll geändert werden auf {email}.' => 'Your email address is about to be changed to {email}.',
    'Die Änderung wird erst wirksam, wenn der Link in der E-Mail an die neue Adresse bestätigt wird – spätestens bis {date}. Bis dahin melden Sie sich weiter mit dieser Adresse an.' => 'The change only takes effect once the link in the email to the new address is confirmed – by {date} at the latest. Until then, keep signing in with this address.',
    'Das war ich nicht – Änderung abbrechen' => 'That wasn\'t me – cancel the change',
    'Beim Abbrechen enden außerdem alle Sitzungen Ihres Kontos. Ändern Sie danach Ihr Passwort.' => 'Cancelling also ends all sessions of your account. Change your password afterwards.',
    'Waren Sie das selbst? Dann müssen Sie nichts tun.' => 'Was it you? Then you don\'t need to do anything.',
    'E-Mail-Adresse geändert – {site}' => 'Email address changed – {site}',
    'Ihre E-Mail-Adresse wurde geändert' => 'Your email address has been changed',
    'Die E-Mail-Adresse Ihres Kontos bei {site} wurde am {date} geändert. Sie melden sich ab jetzt mit der neuen Adresse an; Ihre Passkeys gelten weiter. Andere Sitzungen Ihres Kontos wurden beendet.' => 'The email address of your account at {site} was changed on {date}. From now on you sign in with the new address; your passkeys keep working. Other sessions of your account were ended.',
    'Diese Nachricht geht auch an Ihre bisherige Adresse. Waren Sie das nicht? Wenden Sie sich bitte sofort an die Administration der Website.' => 'This message also goes to your previous address. Wasn\'t that you? Please contact the website\'s administration immediately.',
    'Die Administration der Website {site} hat die E-Mail-Adresse Ihres Kontos am {date} geändert. Sie melden sich ab jetzt mit der neuen Adresse an; Ihre Passkeys gelten weiter. Bitte melden Sie sich neu an.' => 'The administration of {site} changed your account\'s email address on {date}. From now on you sign in with the new address; your passkeys keep working. Please sign in again.',
    'Haben Sie das nicht erwartet? Wenden Sie sich bitte an die Administration der Website.' => 'Didn\'t expect this? Please contact the website\'s administration.',
    'Passwort festgelegt – {site}' => 'Password set – {site}',
    'Passwort geändert – {site}' => 'Password changed – {site}',
    'Sie haben ein Passwort festgelegt' => 'You have set a password',
    'Ihr Passwort wurde geändert' => 'Your password has been changed',
    'Für Ihr Konto bei {site} wurde am {date} ein Passwort festgelegt. Sie können sich jetzt auch mit E-Mail-Adresse und Passwort anmelden; Ihre Passkeys gelten weiter.' => 'A password was set for your account at {site} on {date}. You can now also sign in with email address and password; your passkeys keep working.',
    'Das Passwort Ihres Kontos bei {site} wurde am {date} von der Administration neu gesetzt. Andere Sitzungen Ihres Kontos wurden beendet.' => 'The password of your account at {site} was reset by the administration on {date}. Other sessions of your account were ended.',
    'Das Passwort Ihres Kontos bei {site} wurde am {date} geändert. Andere Sitzungen Ihres Kontos wurden beendet.' => 'The password of your account at {site} was changed on {date}. Other sessions of your account were ended.',
    'Waren Sie das nicht? Wenden Sie sich bitte sofort an die Administration der Website.' => 'Wasn\'t that you? Please contact the website\'s administration immediately.',

    // „Passwort vergessen“ (Core\PasswordReset) und Netzwerk-Administratoren einladen (Core\Invites::createNetwork)
    '+ Netzwerk-Admin einladen' => '+ Invite network admin',
    'Bitte geben Sie eine gültige E-Mail-Adresse ein.' => 'Please enter a valid email address.',
    'Bitte sehen Sie in Ihr Postfach' => 'Please check your inbox',
    'Danach enden alle Sitzungen Ihres Kontos. Zwei-Faktor-Anmeldung und Passkeys bleiben unverändert.' => 'Afterwards, all sessions of your account end. Two-factor authentication and passkeys stay unchanged.',
    'Das Passwort Ihres Kontos bei {site} wurde am {date} über „Passwort vergessen“ neu festgelegt. Alle Sitzungen Ihres Kontos wurden beendet; Zwei-Faktor-Anmeldung und Passkeys gelten unverändert weiter.' => 'The password of your account at {site} was reset via “Forgot password” on {date}. All sessions of your account were ended; two-factor authentication and passkeys keep working unchanged.',
    'Der Link gilt {n} Minuten (bis {date}) und nur einmal.' => 'The link is valid for {n} minutes (until {date}) and can be used once.',
    'Der Link gilt {n} Minuten und nur einmal. Keine E-Mail da? Sehen Sie auch im Spam-Ordner nach oder fordern Sie in einigen Minuten einen neuen Link an.' => 'The link is valid for {n} minutes and can be used once. No email? Check your spam folder too, or request a new link in a few minutes.',
    'Der Link ist abgelaufen oder wurde bereits verwendet. Aus Sicherheitsgründen gilt jeweils nur der neueste Link.' => 'The link has expired or was already used. For security reasons, only the most recent link is valid.',
    'Die Person bekommt eine E-Mail mit einem Link ({n} Tage gültig), legt Passkey und/oder Passwort fest und richtet sofort die Zwei-Faktor-Anmeldung ein. Das Konto hat Zugriff auf alle Websites.' => 'The person receives an email with a link (valid for {n} days), sets a passkey and/or password and sets up two-factor authentication right away. The account has access to all websites.',
    'Die Zwei-Faktor-Anmeldung ist Pflicht: Sie richten sie direkt beim Annehmen ein.' => 'Two-factor authentication is mandatory: you set it up right when accepting.',
    'Ein Passkey erfüllt den zweiten Faktor bereits. Mit Passwort richten Sie im nächsten Schritt die Authenticator-App ein.' => 'A passkey already counts as the second factor. With a password, you set up the authenticator app in the next step.',
    'Eingeladen am {date}' => 'Invited on {date}',
    'Einladung zur Netzwerk-Administration' => 'Invitation to network administration',
    'Einladung zur Netzwerk-Administration – {site}' => 'Invitation to network administration – {site}',
    'Einladung · Netzwerk-Administration' => 'Invitation · Network administration',
    'Für Ihr Konto bei {site} wurde ein neues Passwort angefordert. Über die Schaltfläche legen Sie es fest.' => 'A new password was requested for your account at {site}. Use the button to set it.',
    'Für Ihre Adresse wurde bei {site} ein neues Passwort angefordert. Sie melden sich hier mit einem zentralen Netzwerk-Konto an – dessen Passwort setzen Sie auf der Netzwerk-Website zurück.' => 'A new password was requested for your address at {site}. You sign in here with a central network account – its password is reset on the network website.',
    'Für Netzwerk-Konten ist ein Passkey vorgeschrieben. Legen Sie ihn hier an – sonst direkt im nächsten Schritt.' => 'Network accounts require a passkey. Create it here – otherwise in the very next step.',
    'Geben Sie die E-Mail-Adresse Ihres Kontos ein. Wir schicken Ihnen einen Link, mit dem Sie ein neues Passwort festlegen.' => 'Enter the email address of your account. We will send you a link to set a new password.',
    'Haben Sie die Zwei-Faktor-Anmeldung oder Passkeys eingerichtet, bleiben sie unverändert – nach dem Passwort fragt die Anmeldung wie gewohnt nach dem zweiten Faktor.' => 'If you have set up two-factor authentication or passkeys, they stay unchanged – after the password, sign-in asks for the second factor as usual.',
    'Haben Sie die Zwei-Faktor-Anmeldung oder einen Passkey eingerichtet, fragt die Anmeldung danach wie gewohnt nach dem zweiten Faktor.' => 'If you have set up two-factor authentication or a passkey, sign-in then asks for the second factor as usual.',
    'Ihr Konto ist ein Netzwerk-Konto' => 'Your account is a network account',
    'Ihr neues Passwort gilt ab sofort. Alle Sitzungen Ihres Kontos wurden beendet; eine Bestätigung ist unterwegs.' => 'Your new password is valid immediately. All sessions of your account were ended; a confirmation is on its way.',
    'Jetzt anmelden' => 'Sign in now',
    'Link anfordern' => 'Request link',
    'Mit diesem Konto verwalten Sie alle Websites dieser Installation mit allen Inhalten, Daten und Konten.' => 'With this account you manage all websites of this installation, including all content, data and accounts.',
    'Mit diesem Konto verwalten Sie alle {n} Websites dieser Installation mit allen Inhalten, Daten und Konten.' => 'With this account you manage all {n} websites of this installation, including all content, data and accounts.',
    'Nach dem Klick geben Sie Ihren Namen ein und legen ein Passwort fest (mindestens 12 Zeichen). Direkt danach richten Sie die Zwei-Faktor-Anmeldung mit einer Authenticator-App ein. Danach öffnet sich die Netzwerk-Übersicht.' => 'After clicking, enter your name and set a password (at least 12 characters). Right afterwards you set up two-factor authentication with an authenticator app. Then the network overview opens.',
    'Nach dem Klick geben Sie Ihren Namen ein und legen einen Passkey und/oder ein Passwort fest (mindestens 12 Zeichen). Direkt danach richten Sie die Zwei-Faktor-Anmeldung ein – ein Passkey erfüllt sie bereits, sonst die Authenticator-App. Danach öffnet sich die Netzwerk-Übersicht.' => 'After clicking, enter your name and set a passkey and/or a password (at least 12 characters). Right afterwards you set up two-factor authentication – a passkey already counts, otherwise the authenticator app. Then the network overview opens.',
    'Netzwerk-Administratoren werden auf der Netzwerk-Website eingeladen.' => 'Network administrators are invited on the network website.',
    'Netzwerk-Konten verwalten ALLE Websites dieser Installation. Laden Sie nur Personen ein, denen Sie das anvertrauen.' => 'Network accounts manage ALL websites of this installation. Only invite people you trust with that.',
    'Netzwerk-Konto: Zugriff auf ALLE Websites' => 'Network account: access to ALL websites',
    'Neuen Link anfordern' => 'Request a new link',
    'Neues Passwort festlegen' => 'Set a new password',
    'Nur Netzwerk-Administratoren können weitere einladen.' => 'Only network administrators can invite others.',
    'Nur für Installationen ohne E-Mail-Versand – sonst besser einladen: Dann muss niemand ein Passwort weitergeben.' => 'Only for installations without email delivery – otherwise invite instead, so nobody has to pass on a password.',
    'Ohne E-Mail: mit Startpasswort anlegen' => 'Without email: create with initial password',
    'Passwort speichern' => 'Save password',
    'Passwort vergessen' => 'Forgot password',
    'Passwort vergessen?' => 'Forgot password?',
    'Passwort zurücksetzen' => 'Reset password',
    'Passwort zurücksetzen – {site}' => 'Reset password – {site}',
    'Sie haben das nicht angefordert? Dann ignorieren Sie diese E-Mail – Ihr Passwort bleibt unverändert.' => 'You did not request this? Then ignore this email – your password stays unchanged.',
    'Wenn ein Konto zu dieser Adresse existiert, haben wir Ihnen einen Link geschickt.' => 'If an account exists for this address, we have sent you a link.',
    'Willkommen in der Netzwerk-Administration' => 'Welcome to network administration',
    'Willkommen! Ihr Netzwerk-Konto ist angelegt. Richten Sie jetzt die Zwei-Faktor-Anmeldung ein – ohne sie geht es nicht weiter.' => 'Welcome! Your network account has been created. Set up two-factor authentication now – you cannot continue without it.',
    'Zu viele Anfragen von diesem Anschluss. Bitte warten Sie 15 Minuten.' => 'Too many requests from this connection. Please wait 15 minutes.',
    'Zur Netzwerk-Website' => 'Go to the network website',
    'Zurück zur Anmeldung' => 'Back to sign-in',
    'Zwei-Faktor-Anmeldung und Passkeys bleiben unverändert – nach dem neuen Passwort fragt die Anmeldung wie gewohnt nach dem zweiten Faktor.' => 'Two-factor authentication and passkeys stay unchanged – after the new password, sign-in asks for the second factor as usual.',
    '{name} hat Sie zur Netzwerk-Administration eingeladen – Zugriff auf alle Websites.' => '{name} has invited you to network administration – access to all websites.',
    '{name} hat Sie zur Netzwerk-Administration eingeladen.' => '{name} has invited you to network administration.',
    '{name} lädt Sie ein, als {role} alle Websites dieser Installation zu betreuen.' => '{name} invites you to look after all websites of this installation as {role}.',
    'Öffnen Sie dort „Passwort vergessen?“ und fordern Sie den Link noch einmal an. Das neue Passwort gilt danach auf allen Websites.' => 'Open “Forgot password?” there and request the link again. The new password then applies on all websites.',

    // Zustellung der Anfragen per E-Mail (Core\Data\Delivery, app/Admin/views/data/_inbox.php, requests/index.php, mail/request.php)
    'Abschnitt „Zustellung der Anfragen“ in den Einstellungen eines Eingangs' => 'Section “Request delivery” in the settings of an inbox',
    'Anfrage NICHT gesichert.' => 'Request NOT saved.',
    'Anfrage verschlüsselt gesichert (unter „Anfragen“).' => 'Request saved encrypted (under “Requests”).',
    'Anfragen dieses Eingangs gehen nur per E-Mail hinaus. Hier erscheinen nur Anfragen, deren Zustellung fehlgeschlagen ist (verschlüsselt gesichert).' => 'Requests in this inbox are only sent by email. Only requests whose delivery failed appear here (saved encrypted).',
    'Anfragen je Eingang zusätzlich oder ausschließlich per E-Mail zustellen – mit vollem Inhalt, Anhängen und optional S/MIME-Verschlüsselung.' => 'Deliver requests per inbox additionally or exclusively by email – with full content, attachments and optional S/MIME encryption.',
    'Anfragen per E-Mail zustellen (mit Inhalt, optional S/MIME-verschlüsselt)' => 'Deliver requests by email (with content, optionally S/MIME-encrypted)',
    'Anfragen werden hier gespeichert und zusätzlich mit vollem Inhalt per E-Mail zugestellt.' => 'Requests are stored here and additionally delivered by email with their full content.',
    'Anhänge höchstens (MB je E-Mail)' => 'Attachments at most (MB per email)',
    'Bei „Nur per E-Mail“ wird nichts gespeichert – die Frist gilt dann nur für Anfragen, die nach einem Zustellfehler verschlüsselt gesichert wurden.' => 'With “Email only” nothing is stored – the period then only applies to requests saved encrypted after a delivery failure.',
    'Betreff' => 'Subject',
    'Bitte nur das Zertifikat (öffentlicher Teil) einfügen – der private Schlüssel gehört nicht auf den Server und wurde nicht gespeichert.' => 'Please paste only the certificate (public part) – the private key does not belong on the server and was not saved.',
    'Das Zertifikat ist beschädigt (Base64).' => 'The certificate is damaged (Base64).',
    'Das Zertifikat lässt sich nicht lesen (kein gültiges X.509-Zertifikat).' => 'The certificate cannot be read (not a valid X.509 certificate).',
    'Das Zertifikat „{name}“ eignet sich nicht zum Verschlüsseln ({why}).' => 'The certificate “{name}” is not suitable for encryption ({why}).',
    'Das Zertifikat „{name}“ gilt erst ab {date}.' => 'The certificate “{name}” is only valid from {date}.',
    'Das Zertifikat „{name}“ ist am {date} abgelaufen.' => 'The certificate “{name}” expired on {date}.',
    'Dateien: höchstens (MB je Datei)' => 'Files: at most (MB per file)',
    'Dateifelder gibt es in Eingangs-Tabellen nur mit Zustellung per E-Mail (Einstellung „Zustellung der Anfragen“) – die Datei geht als Anhang hinaus und wird nie in der Mediathek gespeichert.' => 'Inbox tables only allow file fields with email delivery (setting “Request delivery”) – the file is sent as an attachment and never stored in the media library.',
    'Dateifelder nehmen PDF, JPG, PNG und WebP an – nur bei Zustellung per E-Mail, nie in die Mediathek.' => 'File fields accept PDF, JPG, PNG and WebP – only with email delivery, never into the media library.',
    'Der E-Mail-Versand ist deaktiviert (Grundeinstellungen → E-Mail-Versand).' => 'Email sending is disabled (Basic settings → Email).',
    'Die Anfrage konnte auch nicht gesichert werden. Bitte die Einstellungen prüfen:' => 'The request could not be saved either. Please check the settings:',
    'Die Anfrage liegt zusätzlich verschlüsselt im Verwaltungsbereich (Anfragen) und wird dort nach der eingestellten Frist gelöscht.' => 'The request is also stored encrypted in the admin area (Requests) and deleted there after the configured period.',
    'Die Anfrage wurde stattdessen verschlüsselt im System gesichert und ist unter „Anfragen“ mit dem Schlüssel lesbar:' => 'Instead, the request was saved encrypted in the system and can be read under “Requests” with the key:',
    'Die E-Mail konnte nicht erstellt werden.' => 'The email could not be created.',
    'Die Funktion „Anfragen per E-Mail“ ist ausgeschaltet – Anfragen werden nur im System gespeichert.' => 'The feature “Requests by email” is switched off – requests are only stored in the system.',
    'Die gespeicherte Einstellung stellt nicht per E-Mail zu – bitte zuerst „Im System und per E-Mail“ oder „Nur per E-Mail“ wählen und speichern.' => 'The saved setting does not deliver by email – please choose “In the system and by email” or “Email only” and save first.',
    'Diese Anfrage ist nicht auf der Website gespeichert – diese E-Mail ist das einzige Exemplar. Bitte gemäß Ihren Aufbewahrungspflichten archivieren.' => 'This request is not stored on the website – this email is the only copy. Please archive it according to your retention obligations.',
    'Diese E-Mail enthält aus Datenschutzgründen keine Inhalte.' => 'For data protection reasons, this email contains no content.',
    'Diesen Eingang verwaltet eine Erweiterung (z. B. Buchungen), die gespeicherte Einträge braucht – „Nur per E-Mail“ ist hier nicht möglich. Bitte „Im System und per E-Mail“ wählen.' => 'This inbox is managed by an extension (e.g. bookings) that needs stored entries – “Email only” is not possible here. Please choose “In the system and by email”.',
    'E-Mail-Versand einstellen' => 'Set up email sending',
    'Eine oder mehrere Adressen, durch Komma getrennt (höchstens 10). Ohne Empfänger werden Anfragen verschlüsselt im System gesichert.' => 'One or more addresses, separated by commas (at most 10). Without a recipient, requests are saved encrypted in the system.',
    'Eingegangen' => 'Received',
    'Empfänger (E-Mail)' => 'Recipients (email)',
    'Ende-zu-Ende-Verschlüsselung (S/MIME)' => 'End-to-end encryption (S/MIME)',
    'Für den Import in ein eigenes System (z. B. Fachsoftware, CRM oder Archiv).' => 'For importing into your own system (e.g. specialist software, CRM or archive).',
    'Gelesen – Hinweise ausblenden' => 'Read – hide notices',
    'Gesundheitsdaten nur mit S/MIME-Zertifikat der Empfänger per E-Mail zustellen.' => 'Only deliver health data by email with the recipients’ S/MIME certificate.',
    'Grund: {reason}' => 'Reason: {reason}',
    'Größere Dateien: bei „System und E-Mail“ ein Hinweis statt des Anhangs (die Datei liegt verschlüsselt im System), bei „nur per E-Mail“ lehnt das Formular sie ab.' => 'Larger files: with “System and email” a note instead of the attachment (the file is stored encrypted in the system); with “Email only” the form rejects them.',
    'Hinweise ausgeblendet.' => 'Notices hidden.',
    'Höchstens 5 Zertifikate.' => 'At most 5 certificates.',
    'Im System (verschlüsselt)' => 'In the system (encrypted)',
    'Im System und per E-Mail' => 'In the system and by email',
    'Inhalte der Anfragen gehen per E-Mail an die eingetragenen Empfänger (SMTP mit TLS; mit Zertifikat Ende-zu-Ende per S/MIME)' => 'Request contents are emailed to the configured recipients (SMTP with TLS; end-to-end via S/MIME with a certificate)',
    'Inhalte werden per E-Mail übertragen.' => 'Contents are transmitted by email.',
    'Inhalte werden per E-Mail übertragen. Für Gesundheitsdaten empfehlen wir S/MIME-Verschlüsselung mit dem Zertifikat der Empfänger – ohne sie ist die Nachricht nur auf dem Transportweg (TLS) geschützt und liegt unverschlüsselt im Postfach.' => 'Contents are transmitted by email. For health data we recommend S/MIME encryption with the recipients’ certificate – without it the message is only protected in transit (TLS) and sits unencrypted in the mailbox.',
    'Je Auswahl eine eigene Adresse, z. B. „Rezept“ → rezept@…; leer = Empfänger oben.' => 'One address per choice, e.g. “Prescription” → rezept@…; empty = recipients above.',
    'Kein Empfänger eingetragen – Anfragen liegen nur im System.' => 'No recipient entered – requests are only stored in the system.',
    'Kein Empfänger eingetragen – Anfragen werden bis dahin verschlüsselt im System gesichert (Rückfall) und die Administration gewarnt.' => 'No recipient entered – until then requests are saved encrypted in the system (fallback) and the administration is alerted.',
    'Kein Empfänger eingetragen.' => 'No recipient entered.',
    'Kein SMTP-Server eingetragen (Grundeinstellungen → E-Mail-Versand).' => 'No SMTP server entered (Basic settings → Email).',
    'Kein Zertifikat erkannt – bitte den öffentlichen Teil im PEM-Format einfügen („-----BEGIN CERTIFICATE-----“ …).' => 'No certificate recognised – please paste the public part in PEM format (“-----BEGIN CERTIFICATE-----” …).',
    'Kein öffentlicher Schlüssel – ohne ihn nimmt das Formular nichts an (auch der Rückfall-Speicher braucht ihn).' => 'No public key – without it the form accepts nothing (the fallback storage needs it too).',
    'Keine gültige Absender-Adresse (Grundeinstellungen → E-Mail-Versand).' => 'No valid sender address (Basic settings → Email).',
    'Lokale Testablage (mail_dump) – es wird nichts versendet.' => 'Local test storage (mail_dump) – nothing is sent.',
    'Maschinenlesbar im Anhang: {file}' => 'Machine-readable attachment: {file}',
    'Maschinenlesbarer Anhang' => 'Machine-readable attachment',
    'Modus „nur per E-Mail“: keine Inhalte in der Datenbank, nur ein Zustellprotokoll (ohne Inhalte)' => 'Mode “Email only”: no content in the database, only a delivery log (without content)',
    'NICHT gesichert' => 'NOT saved',
    'Neues Zertifikat (ersetzt das bisherige)' => 'New certificate (replaces the current one)',
    'Nicht zugestellt: Testumgebung ohne Weiterleitung (mail_redirect) bzw. Versand deaktiviert.' => 'Not delivered: test environment without redirect (mail_redirect) or sending disabled.',
    'Nur der öffentliche Teil (Zertifikat), nie den privaten Schlüssel. Mit Zertifikat wird jede E-Mail samt Anhängen mit S/MIME verschlüsselt (AES-256) – lesbar nur mit dem privaten Schlüssel im Mailprogramm der Empfänger. Mehrere Zertifikate (z. B. je Empfänger) nacheinander einfügen; jede E-Mail ist dann für alle lesbar. Ist das Zertifikat abgelaufen, wird nichts im Klartext versendet.' => 'Only the public part (certificate), never the private key. With a certificate every email including attachments is encrypted with S/MIME (AES-256) – readable only with the private key in the recipients’ mail program. Paste several certificates (e.g. one per recipient) one after another; every email is then readable by all of them. If the certificate has expired, nothing is sent in plain text.',
    'Nur die E-Mail mit vollem Inhalt – in der Datenbank bleibt nichts davon, nur ein Zustellprotokoll ohne Inhalte. Scheitert der Versand, wird die Anfrage verschlüsselt gesichert und die Administration gewarnt.' => 'Only the email with the full content – nothing of it remains in the database, only a delivery log without content. If sending fails, the request is saved encrypted and the administration is alerted.',
    'Nur per E-Mail – nicht im System speichern' => 'Email only – do not store in the system',
    'Ohne Standard-Empfänger gehen Anfragen ohne passende Weiterleitung nicht per E-Mail hinaus.' => 'Without default recipients, requests without a matching routing rule are not sent by email.',
    'PGP wird nicht unterstützt (keine MIT-kompatible Umsetzung ohne externes Programm).' => 'PGP is not supported (no MIT-compatible implementation without an external program).',
    'Platzhalter: {form} (Titel des Formulars), {table}, {ref} (Vorgangsnummer), {date}, {time} und {feldname} für ein Feld, z. B. „[Rezeptanfrage] {nachname} – {ref}“. Der Betreff wird auch mit S/MIME nicht verschlüsselt – deshalb stehen standardmäßig keine Inhalte darin.' => 'Placeholders: {form} (form title), {table}, {ref} (reference number), {date}, {time} and {fieldname} for a field, e.g. “[Prescription request] {nachname} – {ref}”. The subject is not encrypted even with S/MIME – that is why it contains no content by default.',
    'S/MIME-Zertifikat ungültig oder abgelaufen – es werden keine Inhalte per E-Mail versendet.' => 'S/MIME certificate invalid or expired – no content is sent by email.',
    'S/MIME-Zertifikat ungültig oder abgelaufen – kein Versand im Klartext.' => 'S/MIME certificate invalid or expired – nothing sent in plain text.',
    'S/MIME-Zertifikat „{name}“ läuft am {date} ab – bitte rechtzeitig ein neues hinterlegen.' => 'S/MIME certificate “{name}” expires on {date} – please add a new one in time.',
    'S/MIME-verschlüsselt' => 'S/MIME-encrypted',
    'SHA-256' => 'SHA-256',
    'SMTP mit STARTTLS – für Inhalte erzwungen (ohne TLS kein Versand).' => 'SMTP with STARTTLS – enforced for content (no sending without TLS).',
    'SMTP mit TLS, aber das Zertifikat des Servers wird nicht geprüft („Zertifikat prüfen“ ist aus).' => 'SMTP with TLS, but the server certificate is not verified (“Verify certificate” is off).',
    'SMTP ohne Verschlüsselung – Inhalte werden so nicht per E-Mail versendet. Bitte TLS oder SSL einstellen.' => 'SMTP without encryption – content is not sent by email this way. Please set TLS or SSL.',
    'SMTP über SSL/TLS.' => 'SMTP over SSL/TLS.',
    'Schickt eine erfundene Anfrage mit den gespeicherten Einstellungen – vorher speichern.' => 'Sends a made-up request using the saved settings – save first.',
    'Schlüsselverwendung ohne „Key Encipherment“' => 'key usage without “Key Encipherment”',
    'Sprache der Anfrage' => 'Language of the request',
    'Standard: verschlüsselt gespeichert, lesbar unter „Anfragen“ mit dem Schlüssel. Die Benachrichtigung enthält keine Inhalte.' => 'Default: stored encrypted, readable under “Requests” with the key. The notification contains no content.',
    'TESTNACHRICHT mit erfundenen Angaben („Testmail senden“ in der Verwaltung) – bitte nicht archivieren.' => 'TEST MESSAGE with made-up details (“Send test email” in the admin) – please do not archive.',
    'TESTNACHRICHT – erfundene Angaben' => 'TEST MESSAGE – made-up details',
    'Testmail an {to} gesendet{smime} (Message-ID {id}).' => 'Test email sent to {to}{smime} (Message-ID {id}).',
    'Testmail nicht gesendet: {error}' => 'Test email not sent: {error}',
    'Testmail senden' => 'Send test email',
    'Uhr' => '',
    'Versand über den Mailserver des Webhosters (sendmail) – ob die Weiterleitung per TLS verschlüsselt ist, hängt vom Server ab. Empfohlen: SMTP mit TLS.' => 'Sending via the web host’s mail server (sendmail) – whether forwarding is TLS-encrypted depends on the server. Recommended: SMTP with TLS.',
    'Versand:' => 'Sending:',
    'Verschlüsselt gespeichert und zusätzlich mit vollem Inhalt per E-Mail. Die Löschfrist unten gilt für die gespeicherte Fassung.' => 'Stored encrypted and additionally sent by email with the full content. The deletion period below applies to the stored copy.',
    'Vorgangsnummer' => 'Reference number',
    'Weiterleitung nach Auswahlfeld (optional)' => 'Routing by choice field (optional)',
    'Wohin gehen neue Anfragen?' => 'Where do new requests go?',
    'Zertifikat der Empfänger (PEM)' => 'Recipients’ certificate (PEM)',
    'Zertifikat entfernen (E-Mails dann ohne S/MIME)' => 'Remove certificate (emails then without S/MIME)',
    'Zustellung' => 'Delivery',
    'Zustellung der Anfragen' => 'Request delivery',
    'Zustellung fehlgeschlagen' => 'Delivery failed',
    'Zustellung fehlgeschlagen – Anfrage NICHT gesichert' => 'Delivery failed – request NOT saved',
    'Zustellung fehlgeschlagen – Anfrage verschlüsselt gesichert' => 'Delivery failed – request saved encrypted',
    'Zustellung per E-Mail fehlgeschlagen – hier gesichert' => 'Email delivery failed – saved here',
    'Zustellung: höchstens {n} Empfänger.' => 'Delivery: at most {n} recipients.',
    'Zustellung: {mode}. Ändern darf, wer Anfragen verwalten darf.' => 'Delivery: {mode}. Only people who may manage requests can change it.',
    'Zustellung: „{mail}“ ist keine gültige E-Mail-Adresse.' => 'Delivery: “{mail}” is not a valid email address.',
    'als Anhang' => 'as attachment',
    'ausgestellt von {issuer}' => 'issued by {issuer}',
    'eine Anfrage in „{table}“ (Vorgangsnummer {ref}) konnte nicht per E-Mail zugestellt werden.' => 'a request in “{table}” (reference {ref}) could not be delivered by email.',
    'empfohlen für Gesundheitsdaten' => 'recommended for health data',
    'erweiterte Schlüsselverwendung ohne „E-Mail-Schutz“' => 'extended key usage without “E-mail Protection”',
    'gültig bis {date} (noch {n} Tage)' => 'valid until {date} ({n} days left)',
    'abgelaufen am {date}' => 'expired on {date}',
    'nicht angehängt (zu groß für die E-Mail)' => 'not attached (too large for the email)',
    'nicht angehängt (zu groß für die E-Mail) – liegt verschlüsselt im System' => 'not attached (too large for the email) – stored encrypted in the system',
    'nur RSA-Schlüssel werden unterstützt' => 'only RSA keys are supported',
    'oder Datei wählen (.pem, .crt, .cer):' => 'or choose a file (.pem, .crt, .cer):',
    'selbst signiert' => 'self-signed',
    '– keine: immer an die Empfänger oben –' => '– none: always to the recipients above –',
    '„Antworten“ geht an die E-Mail-Adresse aus der Anfrage (Reply-To), falls das Formular ein E-Mail-Feld hat' => '“Reply” goes to the email address from the request (Reply-To) if the form has an email field',
    '„Nur per E-Mail“ ist hier nicht möglich: Eine Erweiterung (z. B. Buchungen) braucht die gespeicherten Einträge.' => '“Email only” is not possible here: an extension (e.g. bookings) needs the stored entries.',
    'Anleitung: S/MIME einrichten' => 'Guide: setting up S/MIME',
    // Entwürfe (Core\Review\Drafts, app/Admin/views/drafts/*)
    'Entwürfe' => 'Drafts',
    'Offene Entwürfe' => 'Open drafts',
    'offene Entwürfe' => 'open drafts',
    'Entwurf offen' => 'Draft pending',
    'Unveröffentlichte Änderungen – unter „Entwürfe“ vergleichen und veröffentlichen' => 'Unpublished changes – compare and publish under “Drafts”',
    'Alles, was noch nicht (oder nicht in dieser Fassung) online ist: neue Seiten, veröffentlichte Seiten mit unveröffentlichten Änderungen und Einträge im Entwurf. Prüfen, veröffentlichen oder verwerfen – vergessene Zwischenstände fallen nach {n} Tagen ohne Änderung auf.' => 'Everything that is not online yet (or not in this version): new pages, published pages with unpublished changes and draft entries. Review, publish or discard – forgotten intermediate states stand out after {n} days without changes.',
    'Außerdem wartet 1 eingereichte Änderung (API, MCP oder KI) auf Freigabe.' => 'In addition, 1 submitted change (API, MCP or AI) is awaiting approval.',
    'Außerdem warten {n} eingereichte Änderungen (API, MCP oder KI) auf Freigabe.' => 'In addition, {n} submitted changes (API, MCP or AI) are awaiting approval.',
    'Entwürfe filtern' => 'Filter drafts',
    'Meine' => 'Mine',
    'Zur Prüfung' => 'For review',
    'Vergessen?' => 'Forgotten?',
    'vergessen?' => 'forgotten?',
    'Content-Sync & KI' => 'Content sync & AI',
    'Content-Sync' => 'Content sync',
    'Externe Quelle' => 'External source',
    'Keine offenen Entwürfe.' => 'No open drafts.',
    'Keine Entwürfe in dieser Ansicht.' => 'No drafts in this view.',
    'Alle Seiten und Einträge sind so online, wie sie zuletzt bearbeitet wurden.' => 'All pages and entries are online as last edited.',
    'Unter „Alle“ stehen sämtliche offenen Entwürfe.' => '“All” lists every open draft.',
    'Ausgewählte veröffentlichen' => 'Publish selected',
    'Ausgewählte verwerfen' => 'Discard selected',
    'Ausgewählte Entwürfe veröffentlichen? Sie sind danach sofort auf der Website sichtbar.' => 'Publish the selected drafts? They will be visible on the website immediately.',
    'Ausgewählte Entwürfe verwerfen? Seiten gehen zurück auf die veröffentlichte Fassung (der Entwurf bleibt als Version gesichert), Einträge werden gelöscht und unter „Zuletzt verworfen“ gesichert.' => 'Discard the selected drafts? Pages return to the published version (the draft is kept as a version), entries are deleted and kept under “Recently discarded”.',
    'Zuletzt geändert' => 'Last changed',
    'Notiz & Zuständigkeit' => 'Note & assignee',
    'Notiz hinzufügen' => 'Add note',
    'Notiz ändern' => 'Edit note',
    'Notiz speichern' => 'Save note',
    'Notiz gespeichert.' => 'Note saved.',
    'z. B. wartet auf Freigabe durch …' => 'e.g. awaiting approval by …',
    'Im Editor öffnen' => 'Open in editor',
    'Unterschiede' => 'Differences',
    '„{title}“ veröffentlichen?' => 'Publish “{title}”?',
    'Entwurf von „{title}“ verwerfen? Die Seite geht zurück auf die veröffentlichte Fassung; der Entwurf bleibt unter „Versionen“ gesichert.' => 'Discard the draft of “{title}”? The page returns to the published version; the draft is kept under “Versions”.',
    '„{title}“ verwerfen? Der Eintrag wird gelöscht und unter „Zuletzt verworfen“ gesichert.' => 'Discard “{title}”? The entry is deleted and kept under “Recently discarded”.',
    'Neue Seite – Löschen unter „Seiten“' => 'New page – delete under “Pages”',
    'Zuletzt verworfen' => 'Recently discarded',
    'Verworfene Einträge bleiben 90 Tage gesichert und lassen sich als Entwurf wiederherstellen. Verworfene Seiten-Entwürfe finden Sie in der Seite unter „Versionen“.' => 'Discarded entries are kept for 90 days and can be restored as drafts. Discarded page drafts are listed in the page under “Versions”.',
    'Seit über {n} Tagen nicht geändert' => 'Not changed for more than {n} days',
    'offline' => 'offline',
    'Inhalt des Entwurfs' => 'Draft content',
    'Unterschiede zur veröffentlichten Fassung' => 'Differences from the published version',
    'Diese Seite bzw. dieser Eintrag war schon online und ist derzeit offline (Status „Entwurf“). Veröffentlichen stellt ihn wieder online.' => 'This page or entry was online before and is currently offline (status “Draft”). Publishing puts it back online.',
    'Keine inhaltlichen Unterschiede – der Entwurf entspricht der veröffentlichten Fassung.' => 'No content differences – the draft matches the published version.',
    'Veröffentlicht (fällt weg)' => 'Published (will be removed)',
    'Zuletzt: {when}' => 'Last: {when}',
    'Kein offener Entwurf (schon veröffentlicht oder verworfen).' => 'No open draft (already published or discarded).',
    'Bitte zuerst Entwürfe auswählen.' => 'Please select drafts first.',
    'Entwurf nicht mehr vorhanden' => 'Draft no longer exists',
    'Entwurf nicht mehr vorhanden.' => 'Draft no longer exists.',
    '1 Entwurf veröffentlicht.' => '1 draft published.',
    '{n} Entwürfe veröffentlicht.' => '{n} drafts published.',
    '1 Entwurf verworfen.' => '1 draft discarded.',
    '{n} Entwürfe verworfen.' => '{n} drafts discarded.',
    'Seiten-Entwürfe bleiben unter „Versionen“ gesichert, Einträge unter „Zuletzt verworfen“.' => 'Page drafts are kept under “Versions”, entries under “Recently discarded”.',
    'Nicht möglich: {list}' => 'Not possible: {list}',
    'Eintrag als Entwurf wiederhergestellt.' => 'Entry restored as draft.',
    'Nicht mehr vorhanden.' => 'No longer exists.',
    'Unbekannte Art.' => 'Unknown type.',
    '„{title}“ wurde noch nie veröffentlicht – eine neue Seite löschen Sie unter „Seiten“.' => '“{title}” has never been published – delete a new page under “Pages”.',
    '„{title}“: kein Entwurf zum Verwerfen.' => '“{title}”: no draft to discard.',
    '„{title}“: Verwerfen (Löschen) ist Ihrer Rolle nicht erlaubt.' => '“{title}”: your role may not discard (delete) this.',

    // Kern-Fragmente, Entwicklerhandbuch
    'Importieren aus …' => 'Import from …',
    'Kern-Fragment „{name}“ hat sich geändert, seit Kit „{kit}“ es überschreibt ({file} prüfen, dann php bin/console fragments:list --accept)' => 'Core fragment “{name}” has changed since kit “{kit}” overrides it (check {file}, then php bin/console fragments:list --accept)',
    'Kit „{kit}“: {file} wird ignoriert („{name}“ ist ein Kern-Fragment)' => 'Kit “{kit}”: {file} is ignored (“{name}” is a core fragment)',

    // Seite „Nicht gefunden (404)“ (Core\NotFound): Seiten → Sonderseiten, Block „404-Vorschläge“
    'Sonderseiten' => 'Special pages',
    '„Nicht gefunden (404)“ erscheint, wenn Besucher eine Adresse aufrufen, die es nicht gibt – mit Status 404, nicht in Menü, Sitemap und Suche. Bearbeiten wie jede Seite; solange sie nicht veröffentlicht ist, zeigt die Website die Standard-Fehlerseite des Kits.' => '“Not found (404)” appears when visitors open an address that does not exist – with status 404, not in the menu, sitemap or search. Edit it like any page; until it is published, the website shows the kit’s default error page.',
    'zeigt die Seite der Standardsprache' => 'shows the page of the default language',
    'nicht angelegt – Standard-Fehlerseite des Kits' => 'not created – kit’s default error page',
    '404-Seite bearbeiten' => 'Edit 404 page',
    '404-Seite anlegen' => 'Create 404 page',
    '404-Seite angelegt (Entwurf). Inhalte anpassen und veröffentlichen – bis dahin sehen Besucher die Standard-Fehlerseite des Kits.' => '404 page created (draft). Adjust the content and publish – until then visitors see the kit’s default error page.',
    'Sonderseite „Nicht gefunden (404)“: erscheint bei jeder Adresse, die es nicht gibt – mit Status 404, nie im Menü, in der Sitemap oder in Suchmaschinen. Zum Bearbeiten öffnen Sie {path}.' => 'Special page “Not found (404)”: appears for every address that does not exist – with status 404, never in the menu, sitemap or search engines. To edit it, open {path}.',
    'Eigene Seite für „Nicht gefunden“ mit Blöcken gestalten – statt der Standard-Fehlerseite des Kits' => 'Design your own “not found” page with blocks – instead of the kit’s default error page',
    'Nicht gefunden (404) – für alle unbekannten Adressen' => 'Not found (404) – for all unknown addresses',
    'Hier erscheinen Seiten, deren Adresse der aufgerufenen ähnelt – nur, wenn es passende gibt. Im Editor bleibt die Liste leer.' => 'Pages whose address resembles the requested one appear here – only if there are matching ones. The list stays empty in the editor.',
    'Das Suchfeld erscheint, sobald die Suche eingeschaltet ist (Verwaltung → Suche).' => 'The search field appears once search is switched on (Admin → Search).',
    '404-Vorschläge' => '404 suggestions',
    'Für die Seite „Nicht gefunden (404)“ (Seiten → Sonderseiten): Überschrift und Text, „Vielleicht meinten Sie …“ mit ähnlichen Seiten zur aufgerufenen Adresse, Suchfeld und Button zur Startseite. Die Vorschläge erscheinen nur, wenn Besucher eine Adresse aufrufen, die es nicht gibt.' => 'For the “Not found (404)” page (Pages → Special pages): heading and text, “Did you mean …” with pages similar to the requested address, a search field and a button to the home page. Suggestions only appear when visitors open an address that does not exist.',
    'Dachzeile (optional)' => 'Eyebrow (optional)',
    'z. B. Fehler 404' => 'e.g. Error 404',
    'Überschrift (optional, Hauptüberschrift der Seite)' => 'Heading (optional, main heading of the page)',
    '*Sternchen* betonen ein Wort wie im Kit.' => '*Asterisks* emphasise a word as in the kit.',
    'Text (optional)' => 'Text (optional)',
    '„Vielleicht meinten Sie …“ – ähnliche Seiten zur aufgerufenen Adresse' => '“Did you mean …” – pages similar to the requested address',
    'Überschrift der Vorschläge' => 'Heading of the suggestions',
    'Suchfeld zeigen (wenn die Suche eingeschaltet ist)' => 'Show search field (if search is switched on)',
    'Überschrift der Suche' => 'Heading of the search',
    'Button' => 'Button',
    'Button zur Startseite (leer = kein Button)' => 'Button to the home page (empty = no button)',
    'Zweiter Button (optional)' => 'Second button (optional)',
    'Ziel des zweiten Buttons' => 'Target of the second button',
    'Navigation' => 'Navigation',

    // Markdown einfügen/importieren (resources/js/_markdown.js, _rte.js, editor.js, app/Views/toolbar.php)
    'Markdown einfügen …' => 'Insert Markdown …',
    'Text mit # Überschriften, - Listen, **fett** umwandeln' => 'Convert text with # headings, - lists, **bold**',
    'Markdown einfügen' => 'Insert Markdown',
    'Dieses Feld kennt nur fett, kursiv, Links und Zeilenumbrüche – Überschriften und Listen werden zu Textzeilen.' => 'This field only supports bold, italic, links and line breaks – headings and lists become lines of text.',
    'Markdown-Text hier einfügen – Überschriften (#), Listen (-, 1.), **fett**, *kursiv*, [Links](https://…) und > Zitate werden übernommen.' => 'Paste Markdown here – headings (#), lists (-, 1.), **bold**, *italic*, [links](https://…) and > quotes are converted.',
