    'Die Datei ist zu groß (höchstens 1 MB).' => 'The file is too large (1 MB at most).',
    'Bitte eine Textdatei (.md oder .txt) wählen.' => 'Please choose a text file (.md or .txt).',
    '„{name}“ geladen.' => '“{name}” loaded.',
    'Die Datei konnte nicht gelesen werden.' => 'The file could not be read.',
    'Bitte zuerst Markdown-Text einfügen oder eine Datei wählen.' => 'Please paste Markdown text or choose a file first.',
    'Markdown in Formatierung umgewandelt.' => 'Markdown converted to formatting.',
    'Als Text einfügen' => 'Paste as plain text',
    'Hinweis schließen' => 'Close notice',
    'Bild: {alt} – {url}' => 'Image: {alt} – {url}',
    'ohne Beschreibung' => 'no description',
    'Tabelle aus Markdown – bitte als Liste oder eigenen Block umsetzen' => 'Table from Markdown – please turn into a list or a separate block',
    'Markdown importieren …' => 'Import Markdown …',
    'Text oder .md-Datei als Textblöcke einfügen' => 'Insert text or an .md file as text blocks',
    'Markdown importieren' => 'Import Markdown',
    'Am Anfang der Seite' => 'At the top of the page',
    'Nach Block {n}: {label}' => 'After block {n}: {label}',
    'Text einfügen oder eine .md-Datei wählen. Es entstehen Textblöcke als ungespeicherte Änderung – danach wie gewohnt speichern oder veröffentlichen.' => 'Paste text or choose an .md file. Text blocks are added as unsaved changes – then save or publish as usual.',
    'Dieses Kit hat keinen Textblock mit formatiertem Text – Markdown lässt sich hier nicht importieren.' => 'This kit has no text block with formatted text – Markdown cannot be imported here.',
    '1 Textblock eingefügt – noch nicht gespeichert.' => '1 text block inserted – not saved yet.',
    '{n} Textblöcke eingefügt – noch nicht gespeichert.' => '{n} text blocks inserted – not saved yet.',
    // Seiten-Editor: Klick wählt Block aus, „+ Block einfügen“ unten am Block
    'Neuen Block unter diesem Block einfügen' => 'Insert a new block below this block',
    'Block einfügen nach „{label}“' => 'Insert block after “{label}”',
    '{label} – noch leer.' => '{label} – still empty.',
    'Inhalte eingeben' => 'Enter content',
    'Zentral gepflegt – ändern unter „{title}“' => 'Managed centrally – change in “{title}”',
    'Felder ändern: „Bearbeiten“' => 'Change fields: “Edit”',
    'Blocktyp suchen …' => 'Search block type …',
