    'Blocktypen' => 'Block types',
    'Block „{label}“ eingefügt – noch nicht gespeichert.' => 'Block “{label}” inserted – not saved yet.',
    // Dateifelder: erlaubte Dateitypen, Auswahl im Eingangs-Formular
    'Bilder (JPG, PNG, WebP)' => 'Images (JPG, PNG, WebP)',
    'Bildfelder: JPG, PNG, WebP. Dateifelder: PDF und/oder Bilder – einstellbar beim Feld. Hochgeladene Dateien landen in der Mediathek (Tag „formular“) und sind über ihre Adresse erreichbar.' => 'Image fields: JPG, PNG, WebP. File fields: PDF and/or images – set per field. Uploaded files go to the media library (tag “formular”) and are reachable via their address.',
    'Datei – nur bei Zustellung per E-Mail' => 'file – only with delivery by email',
    'Dateien werden nur bei Zustellung per E-Mail angenommen – als Anhang bzw. versiegelt, nie in der Mediathek. Mehr ist nicht einzustellen: Dateifeld anlegen, unter „Felder im Formular“ anhaken, Zustellung „per E-Mail“ wählen. Welche Dateitypen erlaubt sind, legen Sie beim Dateifeld fest (Standard: PDF und Bilder).' => 'Files are only accepted with delivery by email – as an attachment or sealed, never in the media library. Nothing else to set up: add a file field, tick it under “Fields in the form”, choose delivery “by email”. Which file types are allowed is set on the file field (default: PDF and images).',
    'Die Zustellung steht auf „Im System“ – so nimmt das Formular keine Dateien an. Bitte unten „Im System und per E-Mail“ oder „Nur per E-Mail“ wählen.' => 'Delivery is set to “In the system” – the form will not accept files. Please choose “In the system and by email” or “Email only” below.',
    'Erlaubte Dateitypen' => 'Allowed file types',
    'Feld „{label}“: Bitte mindestens einen erlaubten Dateityp wählen.' => 'Field “{label}”: please choose at least one allowed file type.',
    'Geprüft wird der Inhalt der Datei, nicht nur die Endung; Word-Dateien mit Makros (DOCM) werden abgelehnt. Leer = Grenze der Tabelle; mehr als die Tabelle erlaubt, geht nicht. Dateien werden nur bei Zustellung per E-Mail angenommen – als Anhang bzw. versiegelt.' => 'The file content is checked, not just the extension; Word files with macros (DOCM) are rejected. Empty = the table’s limit; it cannot exceed the table’s limit. Files are only accepted with delivery by email – as an attachment or sealed.',
    'Gilt für Uploads über das öffentliche Formular; geprüft wird der Inhalt der Datei, nicht nur die Endung. Leer = Grenze der Tabelle; mehr als die Tabelle erlaubt, geht nicht. Word und OpenDocument gibt es nur in Eingangs-Tabellen (Zustellung per E-Mail) – die Mediathek speichert sie nicht.' => 'Applies to uploads via the public form; the file content is checked, not just the extension. Empty = the table’s limit; it cannot exceed the table’s limit. Word and OpenDocument are only available in inbox tables (delivery by email) – the media library does not store them.',
    'Höchstgröße (MB, optional)' => 'Maximum size (MB, optional)',
    'Nichts angehakt = alle Felder. Neu angelegte Felder sind automatisch dabei. Die Checkbox „Datenschutzhinweise gelesen“ wird immer ergänzt.' => 'Nothing ticked = all fields. Newly added fields are included automatically. The “privacy notice read” checkbox is always added.',
    'OpenDocument-Text (ODT)' => 'OpenDocument text (ODT)',
    'PDF' => 'PDF',
    'Word (DOCX)' => 'Word (DOCX)',
    'wie Tabelle' => 'as table',

    // Seiten-Editor: „Felder bearbeiten“ bei Formular-Blöcken (app/Views/formfields-panel.php, resources/js/_form_fields.js)
    'Alle Einstellungen der Tabelle' => 'All table settings',
    'Beim Speichern werden diese Felder samt Inhalten gelöscht: {fields}. Zum Bestätigen „Felder wirklich löschen“ anhaken.' => 'Saving will delete these fields including their content: {fields}. To confirm, tick “Really delete fields”.',
    'Dateifelder gibt es in Eingängen nur mit Zustellung per E-Mail – einstellbar unter „Alle Einstellungen der Tabelle“.' => 'Inboxes only have file fields with delivery by email – set this under “All table settings”.',
    'Die Felder enthalten Änderungen, die noch nicht gespeichert sind. „Verwerfen“ schließt die Seitenleiste ohne zu speichern.' => 'The fields contain changes that have not been saved yet. “Discard” closes the side panel without saving.',
    'Diese Tabelle gibt es nicht (mehr).' => 'This table does not exist (any more).',
    'Eingang (verschlüsselt): Änderungen gelten für die Tabelle „{table}“ und jedes Formular, das sie nutzt. Keine Bilder, Verknüpfungen oder formatierten Texte; Dateifelder nur bei Zustellung per E-Mail.' => 'Inbox (encrypted): changes apply to the table “{table}” and every form that uses it. No images, relations or formatted text; file fields only with delivery by email.',
    'Feld entfernen?' => 'Remove field?',
    'Feld entfernen? Beim Speichern werden seine Inhalte gelöscht.' => 'Remove field? Its content will be deleted when you save.',
    'Feld „{label}“ entfernt – wird beim Speichern gelöscht.' => 'Field “{label}” removed – it will be deleted when you save.',
    'Feld „{label}“ hinzugefügt.' => 'Field “{label}” added.',
    'Felder bearbeiten' => 'Edit fields',
    'Felder des Formulars bearbeiten ({label})' => 'Edit the form fields ({label})',
    'Felder wirklich löschen' => 'Really delete fields',
    'Geprüft wird der Inhalt der Datei, nicht nur die Endung. Dateien nimmt das Formular nur bei Zustellung per E-Mail an.' => 'The file content is checked, not just the extension. The form only accepts files with delivery by email.',
    'Geprüft wird der Inhalt der Datei, nicht nur die Endung. Word und OpenDocument gibt es nur in Eingangs-Tabellen.' => 'The file content is checked, not just the extension. Word and OpenDocument are only available in inbox tables.',
    'Gespeichert {time} – das Formular auf der Seite ist aktualisiert.' => 'Saved {time} – the form on the page has been updated.',
    'Gespeichert – das Formular auf der Seite ist aktualisiert.' => 'Saved – the form on the page has been updated.',
    'Gilt für die Tabelle. Texte, die im Block selbst eingetragen sind (Seitenleiste „Bearbeiten“), haben Vorrang.' => 'Applies to the table. Texts entered in the block itself (side panel “Edit”) take precedence.',
    'Inhalte gehen verloren' => 'content will be lost',
    'Kurzname: für Platzhalter und Schnittstellen – nur ändern, wenn nötig.' => 'Key: used for placeholders and interfaces – only change it if necessary.',
    'Kurzname: wird aus der Bezeichnung erzeugt.' => 'Key: generated from the label.',
    'Nichts angehakt = alle passenden Felder. Neu hinzugefügte Felder kommen beim Speichern automatisch ins Formular.' => 'Nothing ticked = all suitable fields. Newly added fields are added to the form automatically when you save.',
    'Speichern & schließen' => 'Save & close',
    'Typ geändert – wirksam nach dem Speichern.' => 'Type changed – takes effect after saving.',
    'Typ geändert: Beim Speichern werden die vorhandenen Inhalte dieses Feldes in {n} Einträgen umgewandelt – was nicht zum neuen Typ passt, geht verloren.' => 'Type changed: when you save, the existing content of this field in {n} entries is converted – anything that does not fit the new type is lost.',
    'Unterfelder, Anzahl und Beschriftungen der Gruppe ändern Sie unter „Alle Einstellungen der Tabelle“.' => 'Change the group’s sub-fields, number and labels under “All table settings”.',
    'Zustellung, Verschlüsselung, Benachrichtigung und Übersetzungen stellen Sie unter „Alle Einstellungen der Tabelle“ ein.' => 'Set delivery, encryption, notification and translations under “All table settings”.',
    'bearbeiten' => 'edit',
    'Änderungen gelten für die Tabelle „{table}“ – überall, wo sie genutzt wird ({n} Einträge).' => 'Changes apply to the table “{table}” – wherever it is used ({n} entries).',
    '„{label}“ entfernen' => 'Remove “{label}”',
    '„{label}“ ist jetzt an Position {n} von {total}.' => '“{label}” is now at position {n} of {total}.',
    '„{label}“ nach oben' => 'Move “{label}” up',
    '„{label}“ nach unten' => 'Move “{label}” down',
    // Seiten: Systemadressen (PageController::reservedSlug)
    'Diese Adresse ist reserviert: Unter /{slug} liegen Dateien oder Funktionen des Systems (z. B. Medien, Assets, Verwaltung) – eine Seite wäre dort nicht erreichbar. Bitte eine andere Adresse wählen.' => 'This address is reserved: system files or functions (e.g. media, assets, admin) live under /{slug} – a page there would not be reachable. Please choose another address.',
    'Achtung: Unter /{slug} liegen Dateien des Systems – diese Seite ist dort für Besucher nicht erreichbar. Bitte eine andere Adresse wählen.' => 'Warning: system files live under /{slug} – visitors cannot reach this page there. Please choose another address.',
    // Blöcke nebeneinander (Abschnitts-Option „row“, editor.js)
    'Neben den vorigen Block stellen' => 'Place next to the previous block',
    'Nein – eigener Abschnitt' => 'No – own section',
    'Ja – Breite automatisch' => 'Yes – automatic width',
    'Ja – {w} Breite' => 'Yes – {w} width',
    'Reihe: {w}' => 'Row: {w}',
    'In einer Reihe mit dem vorigen Block ({w})' => 'In a row with the previous block ({w})',
    'Neben den vorigen Block – wird ignoriert (kein Block davor)' => 'Next to the previous block – ignored (no block before it)',
    'Breite dieses Blocks; der vorige Block bekommt den Rest. Hintergrund, Abstände, Trennlinie und Hintergrundbild kommen vom ersten Block der Reihe – ein anderer Hintergrund macht diesen Block zur Karte. Auf schmalen Bildschirmen stehen die Blöcke untereinander.' => 'Width of this block; the previous block gets the rest. Background, spacing, divider and background image come from the first block of the row – a different background turns this block into a card. On narrow screens the blocks are stacked.',

    // Stellenangebote & Google for Jobs (Core\Data\Jobs, Vorlagen jobs/applications, Blöcke job_facts/job_apply)
    'Stellenangebote' => 'Job vacancies',
    'Stelle' => 'Position',
    'Bewerbungen' => 'Applications',
    'Bewerbung' => 'Application',
    'Stellenangebote & Google for Jobs' => 'Job vacancies & Google for Jobs',
    'Stellenangebote & Bewerbung' => 'Job vacancies & applications',
    'Stellenangebot (JobPosting – Google for Jobs)' => 'Job vacancy (JobPosting – Google for Jobs)',
    'Bewerbungsformular' => 'Application form',
    '– kein Formular –' => '– no form –',
    'Neuen Eingang „Bewerbungen“ anlegen' => 'Create new inbox “Applications”',
    'Eingang „Bewerbungen“ nutzen (Feld „Stelle“ wird ergänzt)' => 'Use inbox “Applications” (field “Position” will be added)',
    'Diese Tabelle beschreibt Stellen für Google for Jobs (JobPosting). Abgelaufene Stellen („Gültig bis“ vor heute) verschwinden automatisch aus Listen, Sitemap und Google; ihre Seite zeigt „nicht mehr ausgeschrieben“.' => 'This table describes vacancies for Google for Jobs (JobPosting). Expired vacancies (“Apply by” before today) disappear automatically from lists, the sitemap and Google; their page shows “no longer open”.',
    'Eingang, dessen Formular auf jeder Stellenseite erscheint (Block „Stelle: Bewerbung“). Das Feld „Stelle“ ist dort schon ausgefüllt und gesperrt; der Betreff der E-Mail nennt die Stelle.' => 'Inbox whose form appears on every vacancy page (block “Vacancy: application”). The field “Position” is pre-filled and locked there; the e-mail subject names the position.',
    'Google for Jobs' => 'Google for Jobs',
    'Alle Pflichtangaben vorhanden – die Detailseite liefert ein gültiges JobPosting.' => 'All required details present – the detail page provides a valid JobPosting.',
    'Entwurf – erst veröffentlicht erscheint die Stelle bei Google.' => 'Draft – the vacancy only appears on Google once published.',
    'Die Stelle ist abgelaufen („Gültig bis“) – sie erscheint nicht mehr in Listen, Sitemap und Google for Jobs.' => 'The vacancy has expired (“Apply by”) – it no longer appears in lists, the sitemap or Google for Jobs.',
    'Ohne Detailseite (Adresse + Vorlage) gibt es keine Stellenanzeige für Google.' => 'Without a detail page (address + template) there is no job posting for Google.',
    'Prüfen: Rich-Suchergebnis-Test von Google mit der Adresse der Stelle. „Gültig bis“ aktuell halten bzw. besetzte Stellen auf Entwurf stellen.' => 'Check: Google’s Rich Results Test with the vacancy’s address. Keep “Apply by” current or set filled vacancies to draft.',
    'Dieser Block gehört auf die Detailseite einer Stellen-Tabelle (schema.org-Typ „Stellenangebot“). Die Vorschau erscheint, sobald es eine Stelle gibt.' => 'This block belongs on the detail page of a vacancy table (schema.org type “Job vacancy”). The preview appears as soon as there is a vacancy.',
    'Dieser Block gehört auf die Detailseite einer Stellen-Tabelle. Die Vorschau erscheint, sobald es eine Stelle gibt.' => 'This block belongs on the detail page of a vacancy table. The preview appears as soon as there is a vacancy.',
    'Noch kein Bewerbungsformular: Daten → {table} → Felder & Einstellungen → „Bewerbungsformular“ (Eingang mit eingeschaltetem Formular).' => 'No application form yet: Data → {table} → Fields & settings → “Application form” (inbox with form switched on).',
    'Ohne Bewerbungsformular kein Button: Daten → Tabelle → Felder & Einstellungen → „Bewerbungsformular“.' => 'No button without an application form: Data → table → Fields & settings → “Application form”.',
    'Stelle: Eckdaten' => 'Vacancy: key facts',
    'Stelle: Bewerbung' => 'Vacancy: application',
    'Button zum Formular' => 'Button to the form',
    'Abschnitt ausblenden, wenn nichts da ist' => 'Hide section when empty',
    'Ohne Einträge erscheint für Besucher gar nichts – z. B. „Offene Stellen“ auf einer allgemeinen Karriereseite.' => 'Without entries visitors see nothing at all – e.g. “Open positions” on a general careers page.',
    'Für die Detailseite eines Stellenangebots: Beschäftigungsart, Arbeitsort, Beginn, Gehalt, Bewerbungsfrist und Ansprechperson auf einen Blick – mit Button „Jetzt bewerben“ zum Formular. Ist die Stelle abgelaufen, steht hier „Diese Stelle ist nicht mehr ausgeschrieben“.' => 'For a vacancy’s detail page: employment type, place of work, start, salary, deadline and contact at a glance – with an “Apply now” button to the form. If the vacancy has expired, it says “This position is no longer open”.',
    'Für die Detailseite eines Stellenangebots: das Bewerbungsformular der Tabelle (Felder & Einstellungen → „Bewerbungsformular“). Das Feld „Stelle“ ist ausgefüllt und gesperrt, der Betreff der E-Mail nennt die Stelle. Bei abgelaufenen Stellen erscheint kein Formular.' => 'For a vacancy’s detail page: the table’s application form (Fields & settings → “Application form”). The field “Position” is pre-filled and locked, the e-mail subject names the position. Expired vacancies show no form.',
    'Springt zum Block „Stelle: Bewerbung“ (Sprungmarke „bewerben“). Leer = kein Button.' => 'Jumps to the block “Vacancy: application” (anchor “bewerben”). Empty = no button.',
    // Glossar (Core\Glossary)
    'Alle Überschriften markieren' => 'Mark all headings',
    'Begriff schnell hinzufügen' => 'Quick add a term',
    'Begriff und Kurz-Erklärung sind Pflicht.' => 'Term and short explanation are required.',
    'Begriffe' => 'Terms',
    'Begriffe aus dem Glossar bekommen in diesem Abschnitt keine Erklärung zum Aufklappen (z. B. in Zitaten oder Werbetexten).' => 'Glossary terms in this section get no expandable explanation (e.g. in quotes or promotional copy).',
    'Begriffe gepunktet unterstrichen mit Erklärung zum Aufklappen; Stylesheet und kleines Skript nur auf Seiten mit Begriffen; Block „Glossar“' => 'Terms with a dotted underline and an expandable explanation; stylesheet and small script only on pages with terms; block “Glossary”',
    'Begriffe im Text markieren' => 'Mark terms in the text',
    'Bitte eine CSV-Datei wählen oder Zeilen einfügen.' => 'Please choose a CSV file or paste lines.',
    'Bitte eine Kurz-Erklärung eingeben (oder von der KI vorschlagen lassen).' => 'Please enter a short explanation (or let the AI suggest one).',
    'Bitte einen Begriff eingeben.' => 'Please enter a term.',
    'Bitte zuerst das Glossar einrichten.' => 'Please set up the glossary first.',
    'CSV mit Semikolon und Spaltennamen in der ersten Zeile: begriff;varianten;kurz;erklaerung;kategorie;link;status. Neue Begriffe werden Entwürfe, außer status = published.' => 'CSV with semicolons and column names in the first line: begriff;varianten;kurz;erklaerung;kategorie;link;status. New terms become drafts unless status = published.',
    'Das Glossar ist noch nicht eingerichtet (Verwaltung → Einstellungen → Glossar).' => 'The glossary has not been set up yet (Admin → Settings → Glossary).',
    'Datei (CSV)' => 'File (CSV)',
    'Datentabelle „glossar“, Übersichtsseite /glossar und Detailseiten /glossar/…' => 'Data table “glossar”, overview page /glossar and detail pages /glossar/…',
    'Detailseiten unter /glossar/… eingerichtet.' => 'Detail pages under /glossar/… set up.',
    'Die Adresse /glossar nutzt schon eine andere Tabelle.' => 'The address /glossar is already used by another table.',
    'Die erste Zeile braucht die Spaltennamen, mindestens „begriff“ und „kurz“.' => 'The first line needs the column names, at least “begriff” and “kurz”.',
    'Dynamische Bereiche (CSS-Selektoren)' => 'Dynamic areas (CSS selectors)',
    'Ein Pfad je Zeile; „/pfad/*“ nimmt alle Seiten darunter aus. Einzelne Abschnitte: Abschnitts-Option „Glossar-Begriffe hier nicht markieren“ im Editor.' => 'One path per line; “/path/*” excludes all pages below it. Single sections: section option “Do not mark glossary terms here” in the editor.',
    'Einrichten kann die Administration (Recht „Tabellen und Felder anlegen“).' => 'Administrators can set it up (permission “Create tables and fields”).',
    'Es gibt schon eine Tabelle „glossar“ ohne die Felder „begriff“ und „kurz“ – bitte umbenennen oder die Felder ergänzen.' => 'There is already a table “glossar” without the fields “begriff” and “kurz” – please rename it or add the fields.',
    'Fachbegriffe erklären: Das erste Vorkommen eines Begriffs im Text bekommt ein kleines Hinweisfenster, dazu eine Übersicht A–Z und Detailseiten.' => 'Explain technical terms: the first occurrence of a term in the text gets a small explanation popup, plus an A–Z overview and detail pages.',
    'Fachbegriffe kurz erklärt: Auf der Website bekommt das erste Vorkommen eines Begriffs eine gepunktete Unterstreichung – ein Klick oder Tippen zeigt die Kurz-Erklärung mit Link ins Glossar. Markiert werden nur veröffentlichte Begriffe; Entwürfe sieht nur die angemeldete Redaktion.' => 'Technical terms, briefly explained: on the website the first occurrence of a term gets a dotted underline – a click or tap shows the short explanation with a link to the glossary. Only published terms are marked; drafts are visible to logged-in editors only.',
    'Für Inhalte, die erst im Browser entstehen (z. B. Prüfergebnisse eines Werkzeugs): einfache Selektoren wie .klasse oder #id, einer je Zeile. Dort wird je Bereich das erste Vorkommen markiert. Elemente mit data-glossary="live" gelten immer.' => 'For content created in the browser (e.g. results of a tool): simple selectors such as .class or #id, one per line. The first occurrence is marked per area. Elements with data-glossary="live" always count.',
    'Glossar (Begriffe, Prüfungen, Import/Export, Einstellungen) und Tabelle Daten → Glossar' => 'Glossary (terms, checks, import/export, settings) and table Data → Glossary',
    'Glossar einrichten' => 'Set up glossary',
    'Glossar-Begriffe hier nicht markieren' => 'Do not mark glossary terms here',
    'Handbuch →' => 'Manual →',
    'Hier erscheint der aufgerufene Begriff – sobald es einen gibt.' => 'The requested term appears here – as soon as there is one.',
    'Höchstens 240 Zeichen, Klartext.' => 'At most 240 characters, plain text.',
    'Höchstens 240 Zeichen. Leer lassen und „Von der KI vorschlagen“ wählen: Die KI schreibt einen Entwurf, den Sie danach prüfen.' => 'At most 240 characters. Leave empty and choose “Suggest with AI”: the AI writes a draft that you review afterwards.',
    'In der Datentabelle bearbeiten' => 'Edit in the data table',
    'Jetzt neu zählen' => 'Count again now',
    'Keine Überschrift (h1–h6)' => 'No headings (h1–h6)',
    'Kurz-Erklärung' => 'Short explanation',
    'Legen Sie Begriffe an, fügen Sie sie rechts schnell hinzu oder importieren Sie eine CSV-Datei.' => 'Create terms, quick-add them on the right or import a CSV file.',
    'Legt die Datentabelle „Glossar“ an (Begriff, Varianten, Kurz-Erklärung, ausführliche Erklärung, Kategorie, Link), dazu Detailseiten unter /glossar/… und eine Übersichtsseite /glossar mit dem Block „Glossar“ (A–Z, Suchfeld).' => 'Creates the data table “Glossary” (term, variants, short explanation, full explanation, category, link), plus detail pages under /glossar/… and an overview page /glossar with the block “Glossary” (A–Z, search field).',
    'Mit Komma getrennt, z. B. „Sender Policy Framework, SPF-Eintrag“.' => 'Separated by commas, e.g. “Sender Policy Framework, SPF record”.',
    'Neuer Begriff' => 'New term',
    'Noch keine Begriffe.' => 'No terms yet.',
    'Seiten ausnehmen' => 'Exclude pages',
    'Seiten mit „{t}“ anzeigen' => 'Show pages with “{t}”',
    'Tabelle „Glossar“ angelegt.' => 'Table “Glossary” created.',
    'Tabelle „Glossar“ ist schon da.' => 'Table “Glossary” already exists.',
    'Tabelle „Glossar“ würde angelegt.' => 'Table “Glossary” would be created.',
    'Varianten (optional)' => 'Variants (optional)',
    'Von der KI vorschlagen' => 'Suggest with AI',
    'Vorhandene Begriffe überschreiben' => 'Overwrite existing terms',
    'Vorkommen' => 'Occurrences',
    'ohne Glossar' => 'no glossary',
    '{n} Begriffe' => '{n} terms',
    '{t} Zeilen: {c} neu, {u} geändert, {s} übersprungen.' => '{t} lines: {c} new, {u} changed, {s} skipped.',
    'Überschriften nicht markieren' => 'Do not mark headings',
    'Übersicht auf der Website' => 'Overview on the website',
    'Übersichtsseite /glossar als Entwurf angelegt.' => 'Overview page /glossar created as a draft.',
    'Übersichtsseite /glossar angelegt und veröffentlicht.' => 'Overview page /glossar created and published.',
    'Übersichtsseite gleich veröffentlichen (sonst als Entwurf)' => 'Publish the overview page right away (otherwise as a draft)',
    '„Vorkommen“: Seiten und Einträge im Text der Website-Suche, in denen der Begriff oder eine Variante steht (alle Stellen, auch Überschriften). Stand: höchstens 10 Minuten alt.' => '“Occurrences”: pages and entries in the website search text containing the term or a variant (all places, including headings). At most 10 minutes old.',
    '„{short}“ ({a}) steckt in „{long}“ ({b}) – dort gilt der längere Begriff.' => '“{short}” ({a}) is part of “{long}” ({b}) – there the longer term applies.',
    '„{t}“ als Entwurf angelegt – die Erklärung stammt von der KI. Bitte prüfen und dann veröffentlichen.' => '“{t}” created as a draft – the explanation comes from the AI. Please review, then publish.',
    '„{t}“ als Entwurf angelegt.' => '“{t}” created as a draft.',
    '„{t}“ hat keine Kurz-Erklärung und wird nicht markiert.' => '“{t}” has no short explanation and is not marked.',
    '„{t}“: Variante „{v}“ ist zu kurz.' => '“{t}”: variant “{v}” is too short.',
    '„{v}“ steht bei mehreren Begriffen ({list}) – markiert wird nur einer.' => '“{v}” belongs to several terms ({list}) – only one is marked.',
    'Erstes Vorkommen je Seite' => 'First occurrence per page',
    'Erstes Vorkommen je Abschnitt' => 'First occurrence per section',
    'Nicht automatisch markieren' => 'Do not mark automatically',
    'Keine Probleme gefunden.' => 'No problems found.',
    'Überschneidungen: {n} – dort gilt jeweils der längere Begriff' => 'Overlaps: {n} – the longer term applies there',
    // Block „Layout“ (Spalten, Core\Layout, editor.js decorateLayout)
    'Layout (Spalten)' => 'Layout (columns)',
    'Blöcke in Spalten nebeneinander: Raster wählen, dann in jede Spalte Blöcke einfügen („+ Block in diese Spalte“). Auf schmalen Bildschirmen stehen die Spalten untereinander. Hintergrund, Abstände und Sprungmarke gelten für den ganzen Abschnitt.' => 'Blocks side by side in columns: choose a grid, then add blocks to each column (“+ Block in this column”). On narrow screens the columns are stacked. Background, spacing and anchor apply to the whole section.',
    'Raster' => 'Grid',
    'Weniger Spalten als bisher: Die Blöcke der wegfallenden Spalten wandern in die letzte Spalte – es geht nichts verloren.' => 'Fewer columns than before: the blocks of removed columns move into the last column – nothing is lost.',
    'Ausrichtung vertikal' => 'Vertical alignment',
    'Oben' => 'Top',
    'Mitte' => 'Middle',
    'Unten' => 'Bottom',
    'Gestreckt (gleich hoch)' => 'Stretched (equal height)',
    'Abstand zwischen den Spalten' => 'Space between columns',
    'Auf schmalen Bildschirmen' => 'On narrow screens',
    'Untereinander (Standard des Designs, meist unter 768 px)' => 'Stacked (design default, usually below 768 px)',
    'Schon auf Tablets untereinander (unter ca. 1024 px)' => 'Stacked on tablets too (below approx. 1024 px)',
    'Reihenfolge mobil umkehren (letzte Spalte zuerst)' => 'Reverse order on mobile (last column first)',
    'Block „{type}“ kann nicht in einer Spalte stehen.' => 'Block “{type}” cannot be placed in a column.',
    'Renderer für „{type}“ fehlt.' => 'Renderer for “{type}” is missing.',
    'Block in diese Spalte einfügen' => 'Insert block into this column',
    'Block „{label}“ in Spalte {n}' => 'Block “{label}” in column {n}',
    'In die Spalte links' => 'To the column on the left',
    'In die Spalte rechts' => 'To the column on the right',
    '„{label}“ bearbeiten' => 'Edit “{label}”',
    '„{label}“ löschen' => 'Delete “{label}”',
    'Block in diese Spalte' => 'Block in this column',
    'Block in Spalte {n} einfügen' => 'Insert block into column {n}',
    'Block löschen?' => 'Delete block?',
    '„{label}“ wird aus dieser Spalte entfernt. Bis zum Speichern lässt sich das mit „Abbrechen“ rückgängig machen; danach über Versionen.' => '“{label}” will be removed from this column. Until you save, “Cancel” undoes this; afterwards use versions.',
    '„{label}“ gelöscht – noch nicht gespeichert.' => '“{label}” deleted – not saved yet.',
    '„{label}“ nach oben verschoben.' => '“{label}” moved up.',
    '„{label}“ nach unten verschoben.' => '“{label}” moved down.',
    '„{label}“ in die Spalte links verschoben.' => '“{label}” moved to the column on the left.',
