    '„{title}“ ist offline.' => '“{title}” is offline.',
    '„{title}“ ist offline. Besucher sehen die Seite nicht mehr.' => '“{title}” is offline. Visitors no longer see the page.',
    'Die Startseite ist immer online.' => 'The home page is always online.',
    'Status konnte nicht geändert werden.' => 'The status could not be changed.',
    'Seite offline nehmen?' => 'Take page offline?',
    'Eintrag offline nehmen?' => 'Take entry offline?',
    'Besucher sehen sie dann nicht mehr (Seite „Nicht gefunden“); sie verschwindet aus Menü, Sitemap und Suche, Weiterleitungen und Links auf diese Seite laufen ins Leere. Die veröffentlichte Fassung bleibt erhalten – „Online stellen“ bringt sie zurück.' => 'Visitors will no longer see it (“Not found” page); it disappears from the menu, sitemap and search, and redirects and links to this page lead nowhere. The published version is kept – “Put online” brings it back.',
    'Besucher sehen ihn dann nicht mehr; er verschwindet aus Listen, Sitemap und Suche. Der Inhalt bleibt erhalten – „Online stellen“ bringt ihn zurück.' => 'Visitors will no longer see it; it disappears from lists, the sitemap and search. The content is kept – “Put online” brings it back.',
    'Mit den offenen Änderungen online stellen?' => 'Put online with the pending changes?',
    'Diese Seite hat unveröffentlichte Änderungen. Online stellen veröffentlicht den aktuellen Entwurf.' => 'This page has unpublished changes. Putting it online publishes the current draft.',
    'War schon online und ist derzeit offline: Besucher sehen diesen Eintrag nicht – nur die angemeldete Redaktion.' => 'Was online before and is currently offline: visitors do not see this entry – only signed-in editors.',
    'War schon online und ist derzeit offline: Besucher erhalten „Nicht gefunden“, Menü, Sitemap und Suche lassen die Seite aus. Nur die angemeldete Redaktion sieht sie.' => 'Was online before and is currently offline: visitors get “Not found”, and the menu, sitemap and search leave the page out. Only signed-in editors see it.',
