    // Geteiltes Glossar (Core\Glossary\Sharing), geteilte Daten: Einladen, Beitreten, Verlassen, Canonical
    'Adresse geändert, weil sie in der geteilten Tabelle schon vergeben war: {list}' => 'Address changed because it was already taken in the shared table: {list}',
    'Alle Websites sind beteiligt.' => 'All websites take part.',
    'Anzeige und Canonical einstellen' => 'Set up display and canonical',
    'Auf dieser Website ausgeblendet' => 'Hidden on this website',
    'Begriff auf dieser Website ausgeblendet.' => 'Term hidden on this website.',
    'Begriff einer anderen Website des geteilten Glossars – ändern lässt er sich nur dort.' => 'Term from another website of the shared glossary – it can only be changed there.',
    'Begriff einer anderen Website – ändern lässt er sich nur dort.' => 'Term from another website – it can only be changed there.',
    'Begriff wird auf dieser Website wieder gezeigt.' => 'Term is shown on this website again.',
    'Begriffe der anderen Websites' => 'terms from the other websites',
    'Begriffe der anderen Websites, die hier zu sehen sind, als Kopie behalten' => 'Keep a copy of the other websites’ terms shown here',
    'Beide behalten' => 'Keep both',
    'Beim Beitreten ziehen die eigenen Begriffe in den gemeinsamen Speicher; Links auf Begriffe in Ihren Seiten werden umgestellt. Die bisherige Tabelle bleibt als Sicherung erhalten.' => 'When joining, your own terms move into the shared storage; links to terms in your pages are updated. The previous table is kept as a backup.',
    'Beitreten' => 'Join',
    'Beitreten …' => 'Join …',
    'Das Glossar dieser Website ist nicht geteilt.' => 'This website’s glossary is not shared.',
    'Das Glossar ist geteilt – diese Website ist Eigentümerin.' => 'The glossary is shared – this website is the owner.',
    'Das Glossar ist nicht geteilt.' => 'The glossary is not shared.',
    'Das Glossar wird wieder eine eigene Tabelle dieser Website mit Ihren Begriffen (gleiche Adressen und Links). Ihre Begriffe erscheinen danach nicht mehr bei den anderen Websites.' => 'The glossary becomes a table of this website again, with your terms (same addresses and links). Your terms will no longer appear on the other websites.',
    'Das Glossar wird wieder eine eigene Tabelle dieser Website. Die geteilten Daten bleiben als Sicherung erhalten.' => 'The glossary becomes a table of this website again. The shared data is kept as a backup.',
    'Detailseiten fremder Einträge gibt es auf jeder beteiligten Website unter deren eigener Adresse. Standard: Sie verweisen per Canonical auf die Ursprungs-Website (falls diese Detailseiten hat) und stehen nicht in der Sitemap – Suchmaschinen werten den gleichen Text nicht doppelt. „Diese Website“ nur wählen, wenn die Seiten hier für sich gefunden werden sollen; dann erscheinen sie auch in der Sitemap dieser Website.' => 'Every participating website has detail pages for other websites’ entries under its own address. Default: they point to the website of origin via canonical (if it has detail pages) and are not in the sitemap – search engines do not count the same text twice. Only choose “This website” if the pages should be found here in their own right; they then also appear in this website’s sitemap.',
    'Die Website, der die Tabelle gehört, kann sie nicht verlassen – sie beendet die Freigabe.' => 'The website that owns the table cannot leave it – it ends the sharing instead.',
    'Die eigenen Einträge erscheinen nicht mehr bei den anderen Websites (Sicherung unter storage/shared/{key}/left/).' => 'Your own entries no longer appear on the other websites (backup in storage/shared/{key}/left/).',
    'Diese Begriffe gibt es schon bei anderen Websites (gleicher Begriff oder gleiche Variante, ohne Rücksicht auf Groß-/Kleinschreibung und Akzente). Bitte je Begriff wählen – nichts wird stillschweigend doppelt angelegt.' => 'These terms already exist on other websites (same term or same variant, ignoring case and accents). Please choose for each term – nothing is silently duplicated.',
    'Diese Website ist an „{key}“ nicht beteiligt.' => 'This website does not take part in “{key}”.',
    'Diese Website ist jetzt beteiligt.' => 'This website now takes part.',
    'Diese Website ist nicht eingeladen – die Website, der das Glossar gehört ({site}), lädt sie ein.' => 'This website is not invited – the website that owns the glossary ({site}) invites it.',
    'Diese Website ist nicht zum Beitreten eingeladen – die Website, der die Tabelle gehört, gibt sie frei.' => 'This website is not invited to join – the website that owns the table grants access.',
    'Diese Website nutzt das geteilte Glossar schon.' => 'This website already uses the shared glossary.',
    'Diese Website nutzt das geteilte Glossar von „{site}“.' => 'This website uses the shared glossary of “{site}”.',
    'Diese Website wird Eigentümerin: Ihre Begriffe ziehen in den gemeinsamen Speicher (Adressen und Links bleiben gleich). Eingeladene Websites treten in ihren Glossar-Einstellungen selbst bei – dabei werden doppelte Begriffe abgeglichen.' => 'This website becomes the owner: your terms move into the shared storage (addresses and links stay the same). Invited websites join in their own glossary settings – duplicate terms are reconciled there.',
    'Doppelte Begriffe abgleichen' => 'Reconcile duplicate terms',
    'Eigenen übernehmen, den anderen hier ausblenden' => 'Keep mine, hide the other one here',
    'Eigener Begriff' => 'Own term',
    'Ein Glossar für mehrere Websites dieser Installation: Jede Website pflegt ihre eigenen Begriffe und zeigt zusätzlich die der anderen – markiert im Text, in der Übersicht A–Z und mit Detailseite unter der eigenen Adresse. Einzelne fremde Begriffe lassen sich hier ausblenden.' => 'One glossary for several websites of this installation: each website maintains its own terms and also shows those of the others – marked in the text, in the A–Z overview and with a detail page under its own address. Individual terms from other websites can be hidden here.',
    'Ein Glossar für mehrere Websites dieser Installation: jede pflegt eigene Begriffe und zeigt die der anderen.' => 'One glossary for several websites of this installation: each maintains its own terms and shows those of the others.',
    'Eingeladen (noch nicht beigetreten): {sites}' => 'Invited (not joined yet): {sites}',
    'Eingeladen: {sites}. Diese Websites treten in ihren Glossar-Einstellungen bei.' => 'Invited: {sites}. These websites join in their glossary settings.',
    'Einladen' => 'Invite',
    'Einladen kann nur die Website, der das geteilte Glossar gehört.' => 'Only the website that owns the shared glossary can invite.',
    'Einladungen gespeichert.' => 'Invitations saved.',
    'Einladungen speichern' => 'Save invitations',
    'Entscheidung für „{t}“' => 'Decision for “{t}”',
    'Es gibt hier schon eine eigene Tabelle „{key}“ – bitte zuerst umbenennen.' => 'There already is a table “{key}” here – please rename it first.',
    'Es gibt kein geteiltes Glossar in dieser Installation.' => 'There is no shared glossary in this installation.',
    'Geteilt – Glossar von „{site}“.' => 'Shared – glossary of “{site}”.',
    'Geteilt – diese Website ist Eigentümerin. Beteiligt: {n}.' => 'Shared – this website is the owner. Participants: {n}.',
    'Geteiltes Glossar verlassen …' => 'Leave shared glossary …',
    'Gleich: „{v}“' => 'Same: “{v}”',
    'Glossar mit anderen Websites dieser Installation teilen' => 'Share the glossary with other websites of this installation',
    'Glossar teilen' => 'Share glossary',
    'Glossar teilen …' => 'Share glossary …',
    'In dieser Installation gibt es schon ein geteiltes Glossar (Eigentümer: {site}).' => 'There already is a shared glossary in this installation (owner: {site}).',
    'Keine. Begriffe anderer Websites blenden Sie in der Begriffsliste des Glossars aus („Ausblenden“).' => 'None. You hide other websites’ terms in the glossary’s term list (“Hide”).',
    'Mit anderen Websites teilen' => 'Share with other websites',
    'Neue Begriffe gehören der Website, auf der sie angelegt werden, und erscheinen bei allen Beteiligten. Ändern lässt sich ein Begriff nur auf seiner Website.' => 'New terms belong to the website they are created on and appear on all participating websites. A term can only be changed on its own website.',
    'Oder: „{site}“ lädt diese Website zum gemeinsamen Glossar ein.' => 'Or: “{site}” invites this website to the shared glossary.',
    'Suchmaschinen: Canonical fremder Einträge' => 'Search engines: canonical of other websites’ entries',
    'Teilen beenden' => 'End sharing',
    'Teilen beenden geht erst, wenn keine andere Website mehr beteiligt ist. Beteiligt: {sites} – diese verlassen das Glossar in ihren Glossar-Einstellungen (sie behalten dabei eine Kopie).' => 'Sharing can only end once no other website takes part. Participants: {sites} – they leave the glossary in their glossary settings (keeping a copy).',
    'Teilen beenden geht erst, wenn keine andere Website mehr beteiligt ist. Die übrigen Websites verlassen das Glossar in ihren Glossar-Einstellungen – sie behalten dabei eine Kopie.' => 'Sharing can only end once no other website takes part. The other websites leave the glossary in their glossary settings – keeping a copy.',
    'Teilen beenden …' => 'End sharing …',
    'Teilen einrichten darf, wer die Grundeinstellungen ändern und geteilte Daten verwalten darf.' => 'Setting up sharing requires the rights to change the basic settings and to manage shared data.',
    'Teilen einrichten, beitreten oder verlassen darf, wer die Grundeinstellungen ändern und geteilte Daten verwalten darf.' => 'Setting up sharing, joining or leaving requires the rights to change the basic settings and to manage shared data.',
    'Teilen verwalten' => 'Manage sharing',
    'Ursprungs-Website (empfohlen)' => 'Website of origin (recommended)',
    'Verlassen' => 'Leave',
    'Verweise auf Begriffe in {n} Inhalten auf die neuen Nummern umgestellt.' => 'Links to terms in {n} contents updated to the new numbers.',
    'Vorhanden' => 'Existing',
    'Vorhandenen Begriff nutzen (eigenen nicht übernehmen)' => 'Use the existing term (don’t move mine)',
    'Wieder zeigen' => 'Show again',
    'Zum Bestätigen bitte „{key}“ eintippen.' => 'Please type “{key}” to confirm.',
    'Zum Bestätigen „glossar“ eintippen' => 'Type “glossar” to confirm',
    'Zusammenführen kann nur die Website, der die geteilte Tabelle gehört – oder eine Website, die sie zum Beitreten eingeladen hat.' => 'Only the website that owns the shared table can merge – or a website it has invited to join.',
    'doppelt' => 'duplicates',
    'eigene Begriffe' => 'own terms',
