    '{n} Einträge nicht übernommen – stattdessen gilt der vorhandene Eintrag der geteilten Tabelle.' => '{n} entries not moved – the existing entry of the shared table applies instead.',
    '{n} hier ausgeblendet.' => '{n} hidden here.',
    '„{name}“ ist wieder eine eigene Tabelle dieser Website: {own} eigene Einträge, {copies} Kopien von anderen Websites.' => '“{name}” is a table of this website again: {own} own entries, {copies} copies from other websites.',
    '„{site}“ lädt diese Website ein, das gemeinsame Glossar zu nutzen.' => '“{site}” invites this website to use the shared glossary.',
    '„{site}“ lädt diese Website zum gemeinsamen Glossar ein.' => '“{site}” invites this website to the shared glossary.',
    '„{site}“ teilt ein Glossar in dieser Installation. Diese Website ist nicht eingeladen – die Einladung spricht „{site}“ in deren Glossar-Einstellungen aus.' => '“{site}” shares a glossary in this installation. This website is not invited – “{site}” sends the invitation in its glossary settings.',
    '„{site}“ teilt ein Glossar – diese Website ist nicht eingeladen.' => '“{site}” shares a glossary – this website is not invited.',
    '„{t}“ auf dieser Website ausblenden' => 'Hide “{t}” on this website',
