    'Art des Links' => 'Link type',
    'Aus der Quelle (Beispiel)' => 'From the source (sample)',
    'Autor' => 'Author',
    'Autor (E-Mail)' => 'Author (email)',
    'Autor (Webseite)' => 'Author (website)',
    'Bedeutung' => 'Meaning',
    'Behält sichere Formatierungen (Absätze, Fett, Links, Listen) – für formatierten Text.' => 'Keeps safe formatting (paragraphs, bold, links, lists) – for formatted text.',
    'Beispiel erscheint nach „Vorschau laden“.' => 'A sample appears after “Load preview”.',
    'Beispiel erscheint, sobald eine Zieltabelle gespeichert ist.' => 'A sample appears once a target table is saved.',
    'Beschreibung (Teaser)' => 'Description (teaser)',
    'Bezeichnung für {path}' => 'Label for {path}',
    'Bild (Adresse)' => 'Image (address)',
    'Bild (Art)' => 'Image (kind)',
    'Bild (Maße)' => 'Image (dimensions)',
    'Bildbeschreibung' => 'Image description',
    'Bildnachweis' => 'Image credit',
    'Bitte mindestens ein Feld auswählen.' => 'Please select at least one field.',
    'Bitte zuerst die markierten Angaben der Quelle prüfen.' => 'Please check the marked details of the source first.',
    'Bitte zuerst eine Zieltabelle wählen.' => 'Please choose a target table first.',
    'Datum der Veröffentlichung' => 'Publication date',
    'Datum der letzten Änderung' => 'Date of last change',
    'Datum: Formate wie d.m.Y|Y-m-d H:i (leer = automatisch) · Zahl: de oder en · Kürzen/erster Absatz: Zeichenzahl, z. B. 200 · Vorlage: {pfad} {pfad2}' => 'Date: formats like d.m.Y|Y-m-d H:i (empty = automatic) · Number: de or en · Truncate/first paragraph: number of characters, e.g. 200 · Template: {path} {path2}',
    'Der Probeabruf zeigt die ersten Einträge so, wie sie gespeichert würden.' => 'The test run shows the first entries as they would be saved.',
    'Detailseite' => 'Detail page',
    'Detailseite für jeden Eintrag anlegen' => 'Create a detail page for every entry',
    'Die Datei wird geladen, neu gespeichert (ohne Kamera- und Standortdaten) und in die Mediathek übernommen.' => 'The file is downloaded, saved anew (without camera and location data) and added to the media library.',
    'Die Quelle wird dabei angelegt. Danach sehen Sie den Probeabruf.' => 'The source is created along with it. Afterwards you see the test run.',
    'Die Quelle wird dabei gespeichert. Danach sehen Sie den Probeabruf.' => 'The source is saved along with it. Afterwards you see the test run.',
    'Die Tabelle konnte nicht angelegt werden.' => 'The table could not be created.',
    'Die Tabelle wurde nicht angelegt:' => 'The table was not created:',
    'Die ersten 3 Einträge so, wie sie mit der Zuordnung oben gespeichert würden – nichts wird gespeichert. Grundlage ist die letzte Vorschau.' => 'The first 3 entries as they would be saved with the mapping above – nothing is saved. Based on the last preview.',
    'Eindeutige ID' => 'Unique ID',
    'Eine Zeile je Wert: Quelle=Ersatz (vor der Umwandlung; * = alle übrigen).' => 'One line per value: source=replacement (before the transform; * = all others).',
    'Entfernt HTML und doppelte Leerzeichen – für Titel, Namen und kurze Texte.' => 'Removes HTML and double spaces – for titles, names and short texts.',
    'Entfernt HTML und kürzt an einer Wortgrenze mit „…“ – Länge unter „Erweitert“ (Standard 200 Zeichen). Für Teaser aus Beschreibung oder Volltext.' => 'Removes HTML and cuts at a word boundary with “…” – length under “Advanced” (default 200 characters). For teasers from a description or full text.',
    'Erst Adresse eintragen und „Vorschau laden“ – dann erscheinen hier alle Felder der Quelle mit einem Beispielwert.' => 'First enter the address and “Load preview” – then all fields of the source appear here with a sample value.',
    'Erweitert' => 'Advanced',
    'Feld der Quelle wählen' => 'Choose a field of the source',
    'Feld übernehmen: {label}' => 'Include field: {label}',
    'Felder filtern' => 'Filter fields',
    'Felder in der Quelle' => 'Fields in the source',
    'Felder und Typen sind aus den Daten der Quelle vorgeschlagen. Entfernen Sie den Haken bei allem, was Sie nicht brauchen; Bezeichnung und Typ lassen sich ändern. Die Zuordnung wird automatisch ausgefüllt.' => 'Fields and types are suggested from the data of the source. Untick anything you don’t need; label and type can be changed. The mapping is filled in automatically.',
    'Füllt alle leeren Zeilen passend zu Feldname und Feldtyp (Datum ← pubDate, Bild ← enclosure@url …). Belegte Zeilen bleiben unverändert.' => 'Fills all empty rows according to field name and type (date ← pubDate, image ← enclosure@url …). Filled rows stay unchanged.',
    'Für den Vorschlag braucht es die Daten der Quelle: Erst Adresse eintragen und „Vorschau laden“.' => 'The suggestion needs the data of the source: first enter the address and “Load preview”.',
    'Für die übrigen Felder gibt es keinen passenden Pfad in der Quelle – bitte von Hand zuordnen oder leer lassen.' => 'There is no matching path in the source for the remaining fields – please map them by hand or leave them empty.',
    'Greift, wenn die Quelle nichts liefert.' => 'Applies when the source delivers nothing.',
    'ID ist zugleich Link (true/false)' => 'ID is also a link (true/false)',
    'Im ersten Eintrag leer.' => 'Empty in the first entry.',
    'In der Quelle wurden keine Felder gefunden.' => 'No fields were found in the source.',
    'Ja bei 1, true, ja, yes oder x – sonst Nein.' => 'Yes for 1, true, ja, yes or x – otherwise No.',
    'Jede Zeile füllt ein Feld Ihrer Tabelle mit einem Wert aus der Quelle. Wählen Sie den Wert mit „Auswählen“ – darunter sehen Sie sofort, was im ersten Eintrag ankommt. Beispiele für RSS:' => 'Each row fills a field of your table with a value from the source. Pick the value with “Select” – right below you see what arrives in the first entry. Examples for RSS:',
    'Kategorie (Schema)' => 'Category (scheme)',
    'Keine passenden Felder.' => 'No matching fields.',
    'Kommentare (Adresse)' => 'Comments (address)',
    'Kurzname oder Bezeichnung einer Auswahlmöglichkeit' => 'Key or label of a choice',
    'Liest Zahlen wie 1.234,56 oder 1,234.56 – Währungszeichen und Einheiten werden ignoriert.' => 'Reads numbers like 1.234,56 or 1,234.56 – currency signs and units are ignored.',
    'Liest ein Datum: RSS-Datum (RFC 822), ISO 8601, Unix-Zeit oder 01.10.2026. Feste Formate unter „Erweitert“.' => 'Reads a date: RSS date (RFC 822), ISO 8601, Unix time or 01.10.2026. Fixed formats under “Advanced”.',
    'Link (Dateityp)' => 'Link (file type)',
    'Link zum Beitrag' => 'Link to the article',
    'Macht aus dem Wert eine Kurzform für Adressen, z. B. „mein-beitrag“.' => 'Turns the value into a short form for addresses, e.g. “my-article”.',
    'Name der Tabelle' => 'Table name',
    'Neue Tabelle aus dieser Quelle' => 'New table from this source',
    'Neue Tabellen anlegen dürfen Rollen mit dem Recht „Tabellen und Felder ändern“.' => 'Roles with the permission “Change tables and fields” may create new tables.',
    'Nicht zugeordnet – das Feld bleibt leer.' => 'Not mapped – the field stays empty.',
    'Nimmt nur den ersten Absatz (ohne HTML) – optional unter „Erweitert“ zusätzlich auf eine Zeichenzahl gekürzt.' => 'Takes only the first paragraph (without HTML) – optionally also truncated to a number of characters under “Advanced”.',
    'Noch keine Felder bekannt: OpenImmo-Datei hochladen (rechts) oder Adresse eintragen und „Vorschau laden“.' => 'No fields known yet: upload an OpenImmo file (right) or enter the address and “Load preview”.',
    'Noch keine Vorschau: Erst Adresse eintragen und „Vorschau laden“.' => 'No preview yet: first enter the address and “Load preview”.',
    'Nur a–z, 0–9 und _. Gibt es ihn schon, wird _2, _3 … angehängt.' => 'Only a–z, 0–9 and _. If it exists already, _2, _3 … is appended.',
    'Nur erster Absatz' => 'First paragraph only',
    'Ohne Wert wird ein Eintrag nicht gespeichert. Pfad wählen, Standardwert unter „Erweitert“ angeben oder – bei Datumsfeldern – „jetzt (Zeitpunkt des Abrufs)“.' => 'Without a value an entry is not saved. Choose a path, enter a default value under “Advanced” or – for date fields – use “now (time of fetching)”.',
    'Passend zum Feldtyp: Datumsangaben werden gelesen, Zahlen erkannt, HTML wird bei einfachem Text entfernt.' => 'According to the field type: dates are read, numbers recognised, HTML is removed from plain text.',
    'Pfad – oder „Auswählen“' => 'Path – or “Select”',
    'Pfeiltasten wählen, Enter übernimmt, Esc schließt.' => 'Arrow keys select, Enter applies, Esc closes.',
    'Pflichtfeld – bitte eine Quelle wählen oder unter „Erweitert“ einen Standardwert angeben.' => 'Required field – please choose a source or enter a default value under “Advanced”.',
    'Pflichtfeld „{label}“ ist leer – dieser Eintrag würde nicht gespeichert.' => 'Required field “{label}” is empty – this entry would not be saved.',
    'Pflichtfeld: Einträge ohne Wert werden nicht gespeichert.' => 'Required field: entries without a value are not saved.',
    'Probeabruf' => 'Test run',
    'Probeabruf aktualisieren' => 'Refresh test run',
    'RSS-Datum (RFC 822), ISO 8601 oder Unix-Zeit werden erkannt' => 'RSS date (RFC 822), ISO 8601 or Unix time are recognised',
    'Seiten auf der Website' => 'Pages on the website',
    'Setzt mehrere Werte zusammen – Vorlage unter „Erweitert“, z. B. {author.name} · {category}.' => 'Combines several values – template under “Advanced”, e.g. {author.name} · {category}.',
    'So funktioniert die Zuordnung:' => 'How the mapping works:',
    'So sieht der erste Eintrag der Quelle aus: links, was ein Wert bedeutet, in der Mitte der Pfad für die Zuordnung, rechts ein Beispiel. In der Zuordnung unten übernehmen Sie Pfade mit „Auswählen“.' => 'This is what the first entry of the source looks like: on the left what a value means, in the middle the path for the mapping, on the right a sample. In the mapping below you apply paths with “Select”.',
    'Tabelle angelegt, die Quelle konnte aber nicht gespeichert werden.' => 'Table created, but the source could not be saved.',
    'Tabelle anlegen und zuordnen' => 'Create table and map',
    'Tabelle „{name}“ mit {n} Feldern angelegt{extra} und als Ziel zugeordnet. Prüfen Sie unten den Probeabruf – dann „Jetzt abrufen“.' => 'Table “{name}” with {n} fields created{extra} and set as target. Check the test run below – then “Fetch now”.',
    'Text oder HTML – wird bereinigt' => 'Text or HTML – will be cleaned',
    'Text – HTML wird entfernt' => 'Text – HTML is removed',
    'Text – HTML wird entfernt, Absätze bleiben' => 'Text – HTML is removed, paragraphs stay',
    'Typ für {path}' => 'Type for {path}',
    'Uhrzeit wie 14:05 oder ein vollständiges Datum' => 'Time like 14:05 or a full date',
    'Ursprüngliche Quelle' => 'Original source',
    'Volltext (HTML)' => 'Full text (HTML)',
    'Vorgeschlagene Felder' => 'Suggested fields',
    'Vorhandene Tabelle wählen – oder „Neue Tabelle aus dieser Quelle anlegen“: Felder, Typen und Zuordnung werden aus den Daten der Quelle vorgeschlagen.' => 'Choose an existing table – or “Create a new table from this source”: fields, types and mapping are suggested from the data of the source.',
    'Vorlage unter „Erweitert“: mehrere Werte in geschweiften Klammern zusammensetzen (Umwandlung „Vorlage“)' => 'Template under “Advanced”: combine several values in curly braces (transform “Template”)',
    'Vorschau laden' => 'Load preview',
    'Vorschaubild (Adresse)' => 'Thumbnail (address)',
    'Wert aus der Quelle' => 'Value from the source',
    'Wählen Sie eine Zieltabelle, um die Felder der Quelle zuzuordnen.' => 'Choose a target table to map the fields of the source.',
    'Zahl wie 1.234,56 oder 1,234.56' => 'Number like 1.234,56 or 1,234.56',
    'Zeitpunkt des Abrufs' => 'time of fetching',
    'Zeitpunkt, zu dem der Eintrag zum ersten Mal abgerufen wurde – für Quellen ohne Datum. Liefert der Pfad ein Datum, zählt dieses.' => 'Time at which the entry was first fetched – for sources without a date. If the path delivers a date, that one counts.',
    'Zieltabelle wählen oder „Neue Tabelle aus dieser Quelle anlegen“ – Felder und Zuordnung werden aus den Daten vorgeschlagen.' => 'Choose a target table or “Create a new table from this source” – fields and mapping are suggested from the data.',
    'Zuordnung vorgeschlagen für: {list}. Bitte die Beispiele prüfen und speichern.' => 'Mapping suggested for: {list}. Please check the samples and save.',
    'Zuordnung vorschlagen' => 'Suggest mapping',
    'ein Attribut mit @ (hier die Bildadresse aus <enclosure url="…">)' => 'an attribute with @ (here the image address from <enclosure url="…">)',
    'ein Element des Eintrags (hier das Datum)' => 'an element of the entry (here the date)',
    'ja/nein, true/false oder 1/0' => 'yes/no, true/false or 1/0',
    'jetzt (Zeitpunkt des Abrufs)' => 'now (time of fetching)',
    'leer – Pflichtfeld' => 'empty – required field',
    'vollständige Adresse mit https://' => 'full address with https://',
    'z. B. title' => 'e.g. title',
    '{n} Felder · Stand der Vorschau: {when}' => '{n} fields · preview from {when}',
    'Übernimmt den Wert genau so, wie er in der Quelle steht.' => 'Takes the value exactly as it is in the source.',
    'Übersicht unter /adresse, Einträge unter /adresse/titel-des-eintrags. Ist sie vergeben, wird -2, -3 … angehängt.' => 'Overview at /address, entries at /address/title-of-the-entry. If it is taken, -2, -3 … is appended.',
    'Übersichtsseite /{route}' => 'overview page /{route}',
    'Übersichtsseite in der Navigation der Website zeigen' => 'Show the overview page in the website navigation',
    'Übersichtsseite mit allen Einträgen anlegen' => 'Create an overview page with all entries',
    '„{label}“: „{value}“ ist keine vollständige Adresse (https://…).' => '“{label}”: “{value}” is not a full address (https://…).',
    'Zuordnung vorgeschlagen – bitte die Beispiele prüfen und speichern.' => 'Mapping suggested – please check the samples and save.',
    // Pools geteilter Datentabellen (Core\Data\Shared::ensurePool/cleanupPools, Grundeinstellungen → Geteilte Medien)
    'Bilder der geteilten Tabelle „{name}“' => 'Images of the shared table “{name}”',
    'Zur Tabelle' => 'Go to table',
    'Genutzt von: {sites} – automatisch alle beteiligten Websites der Tabelle.' => 'Used by: {sites} – automatically all participating websites of the table.',
    'Alt-Texte, Zuschnitte und Sammlungen in der Mediathek – Bilder der Einträge setzt jede beteiligte Website selbst' => 'Alt texts, crops and collections in the media library – every participating website sets the images of its entries itself',
    'Wird mit der Tabelle verwaltet.' => 'Managed together with the table.',
    'Leere Pools geteilter Tabellen ({n})' => 'Empty pools of shared tables ({n})',
    'Diese Pools gehören zu geteilten Datentabellen und enthalten noch keine Dateien. Sie werden mit der Tabelle verwaltet; Pools von Tabellen ohne Bild- oder Dateifelder entfernt „migrate“ automatisch.' => 'These pools belong to shared data tables and contain no files yet. They are managed together with the table; “migrate” removes pools of tables without image or file fields automatically.',
    'ohne Bild-/Dateifelder – wird beim nächsten „migrate“ entfernt' => 'no image/file fields – removed by the next “migrate”',
    'Dieser Pool gehört zu einer geteilten Datentabelle und wird mit der Tabelle verwaltet.' => 'This pool belongs to a shared data table and is managed together with the table.',
    // Verwaltung → Blöcke: Beispiele (Core\Blocks\Demos)
    'Als Vorlage übernehmen' => 'Use as template',
    'Aus Beispiel' => 'From example',
    'Beispiel als Entwurf übernommen – ändern Sie es nach Belieben. Erst „Für Redaktion freigeben“ macht es beim Bearbeiten der Seiten verfügbar.' => 'Example copied as a draft – change it as you like. Only “Save & release for editors” makes it available when editing pages.',
    'Beispiel {n}' => 'Example {n}',
    'Beispiel „{name}“ nicht gefunden.' => 'Example “{name}” not found.',
    'CSS ergänzen' => 'Add CSS',
    'Das Beispiel wurde bereits übernommen.' => 'The example has already been copied.',
    'Das CSS gilt nur innerhalb des Blocks und nutzt die Farben des Kits. Danach in der Vorschau prüfen und für die Redaktion freigeben.' => 'The CSS only applies inside the block and uses the kit’s colours. Then check the preview and release it to editors.',
    'Felder anlegen' => 'Create fields',
    'HTML mit Platzhaltern wie {{ title }} – ohne PHP und ohne JavaScript. Alle Ausgaben werden automatisch geschützt.' => 'HTML with placeholders like {{ title }} – no PHP and no JavaScript. All output is escaped automatically.',
    'Handbuch: Eigene Blöcke bauen' => 'Manual: Building custom blocks',
    'Hinweise ausblenden' => 'Hide tips',
    'Hinweise zum Beispiel einblenden' => 'Show tips for this example',
    'Im Beispiel:' => 'In this example:',
    'Jedes Beispiel zeigt ein Konzept des Block-Designers. „Als Vorlage übernehmen“ legt eine Kopie als Entwurf an – bestehende Blöcke bleiben unberührt. Im Block-Designer erklären Hinweise, was das Beispiel zeigt. Die Vorschau nutzt das aktive Kit.' => 'Each example shows one concept of the block designer. “Use as template” creates a copy as a draft – existing blocks stay untouched. In the block designer, tips explain what the example shows. The preview uses the active kit.',
    'Mit einem Beispiel anfangen' => 'Start with an example',
    'Vorlage schreiben' => 'Write the template',
    'Vorschau: {label}' => 'Preview: {label}',
    'Was zeigt dieses Beispiel?' => 'What does this example show?',
    'Weitere Hinweise stehen in den Reitern. Alles ist frei änderbar – die Vorschau rechts zeigt jede Änderung sofort. Erst „Speichern & für Redaktion freigeben“ macht den Block beim Bearbeiten der Seiten verfügbar.' => 'More tips are in the tabs. Everything can be changed – the preview on the right shows every change immediately. Only “Save & release for editors” makes the block available when editing pages.',
    'Zeigt' => 'Shows',
    'schon {n}× übernommen' => 'already copied {n}×',
    '{n} Beispiel-Blöcke – vom einfachen Hinweis bis zur Aufklappliste' => '{n} example blocks – from a simple notice to an accordion',
    // KI: Verbindungen und Verwendung (Core\AI\Profiles, Core\AI\Probe), Seitenauswahl (Core\PagePicker)
    '1 Modell' => '1 model',
    '1 Seite ausgewählt' => '1 page selected',
    'API-Schlüssel bzw. Token' => 'API key or token',
    'Adresse (base_url) fehlt oder ist ungültig.' => 'Address (base_url) is missing or invalid.',
    'Adresse gesperrt' => 'address blocked',
    'Adressen im eigenen Netz sind nur für Ollama und OpenAI-kompatible Dienste erlaubt.' => 'Addresses in your own network are only allowed for Ollama and OpenAI-compatible services.',
    'Alle Treffer auswählen' => 'Select all matches',
    'Alle sichtbaren auswählen' => 'Select all visible',
    'Antwortet, ist aber kein Dienst der Art „{type}“ – Anbieter oder Adresse prüfen.' => 'Responds, but is not a “{type}” service – check the provider or address.',
    'Ausgewählte Seiten' => 'Selected pages',
    'Beliebig viele Verbindungen, z. B. ein eigener Ollama-Server und ein EU-Anbieter. Gilt für alle Websites dieser Installation (storage/ai/config.json, nicht im Webroot); Werte aus config/config.local.php bzw. config/sites/*.php haben Vorrang und sind gesperrt.' => 'Any number of connections, e.g. your own Ollama server and an EU provider. Applies to all websites of this installation (storage/ai/config.json, outside the web root); values from config/config.local.php or config/sites/*.php take precedence and are locked.',
    'Besucher-Suche (Sekunden)' => 'Visitor search (seconds)',
    'Bitte eine Bezeichnung angeben.' => 'Please enter a name.',
    'Bitte einen Pfad angeben, der mit / beginnt (z. B. /blog/*).' => 'Please enter a path starting with / (e.g. /blog/*).',
    'Bitte zuerst eine Verbindung wählen.' => 'Please choose a connection first.',
    'Das Embedding-Modell hat sich geändert: Der Suchindex berechnet alle Vektoren neu (beim nächsten Abgleich bzw. mit „Index neu aufbauen“). Bis dahin findet die semantische Suche weniger.' => 'The embedding model has changed: the search index recalculates all vectors (at the next sync or with “Rebuild index”). Until then, semantic search finds less.',
    'Der Dienst liefert keine Liste – bekannte Modelle:' => 'The service provides no list – known models:',
    'Die Eignung erkennt KLXM Studio an den Angaben des Dienstes oder am Namen – im Zweifel mit „Verbindung testen“ prüfen.' => 'KLXM Studio detects suitability from the service’s details or the name – if in doubt, check with “Test connection”.',
    'Diese Adresse ist aus Sicherheitsgründen gesperrt.' => 'This address is blocked for security reasons.',
    'Diese Verbindung ist in einer Konfigurationsdatei festgelegt.' => 'This connection is set in a configuration file.',
    'Diese Website: KI-Funktionen' => 'This website: AI features',
    'Eigene Pfade' => 'Custom paths',
    'Eigener Pfad' => 'Custom path',
    'Eignung' => 'Suitable for',
    'Empfehlung: eigener Ollama-Server (z. B. gemma3 für Texte und Bilder, bge-m3 oder nomic-embed-text für die Suche) oder ein EU-Anbieter wie Mistral AI.' => 'Recommendation: your own Ollama server (e.g. gemma3 for text and images, bge-m3 or nomic-embed-text for search) or an EU provider such as Mistral AI.',
    'Ersatz' => 'Fallback',
    'Ersatz-Modell für „{p}“' => 'Fallback model for “{p}”',
    'Ersatz-Verbindung für „{p}“' => 'Fallback connection for “{p}”',
    'Ersatz: {label}' => 'Fallback: {label}',
    'Für Adressen ohne eigene Seite, z. B. Detailseiten von Einträgen: /blog/*' => 'For addresses without their own page, e.g. entry detail pages: /blog/*',
    'Für Aufgaben der Redaktion bzw. eine Transkription. Leer = allgemeines Zeitlimit.' => 'For editorial tasks or a transcription. Empty = general time limit.',
    'Genutzt für: {list}' => 'Used for: {list}',
    'Gewählt' => 'Selected',
    'Indexierung (Sekunden)' => 'Indexing (seconds)',
    'Je Zweck eine Verbindung und ein Modell. „Modelle …“ zeigt die Modelle der Verbindung zum Übernehmen per Klick; der Name lässt sich auch von Hand eintragen. Eine Ersatz-Verbindung springt ein, wenn die erste nicht antwortet (nicht bei Embeddings).' => 'One connection and one model per purpose. “Models …” lists the connection’s models to pick with a click; you can also type the name. A fallback connection steps in when the first one does not respond (not for embeddings).',
    'KI eingeschaltet' => 'AI switched on',
    'KI für diese Website aus' => 'AI off for this website',
    'Keine Modelle in storage/ai/models/ (ggml-*.bin).' => 'No models in storage/ai/models/ (ggml-*.bin).',
    'Keine Seiten ausgewählt.' => 'No pages selected.',
    'Keine Verbindung – Adresse, Port und Firewall prüfen.' => 'No connection – check address, port and firewall.',
    'Kontext' => 'Context',
    'Modell (leer = gleiches)' => 'Model (empty = same)',
    'Modell der Verbindung' => 'Model of the connection',
    'Modell für „{p}“' => 'Model for “{p}”',
    'Modelle' => 'Models',
    'Modelle anzeigen' => 'Show models',
    'Modelle filtern' => 'Filter models',
    'Modelle werden geladen …' => 'Loading models …',
    'Modelle …' => 'Models …',
    'Modellname „{model}“ ist ungültig.' => 'Model name “{model}” is invalid.',
    'Neu gewählte Seiten mit Unterseiten' => 'Newly selected pages include subpages',
    'Neues Embedding-Modell: Nach dem Speichern berechnet der Suchindex alle Vektoren neu – bis dahin findet die semantische Suche weniger.' => 'New embedding model: after saving, the search index recalculates all vectors – until then, semantic search finds less.',
    'Noch keine KI eingerichtet. Das übernimmt die Agentur bzw. Netzwerk-Administration.' => 'No AI set up yet. The agency or network administration takes care of this.',
    'Noch keine KI eingerichtet: zuerst unter „Verbindungen“ eine Verbindung anlegen und prüfen, dann unter „Verwendung“ Modelle zuordnen.' => 'No AI set up yet: first add and check a connection under “Connections”, then assign models under “Usage”.',
    'Noch keine Verbindung.' => 'No connection yet.',
    'Noch keinem Zweck zugeordnet' => 'Not assigned to any purpose yet',
    'Ollama: http://localhost:11434 oder die Adresse Ihres Servers. Mistral/Anthropic: leer lassen. OpenAI-kompatibel: Basis-Adresse des Dienstes.' => 'Ollama: http://localhost:11434 or your server’s address. Mistral/Anthropic: leave empty. OpenAI-compatible: base address of the service.',
