    'Block „{label}“ dupliziert – noch nicht gespeichert.' => 'Block “{label}” duplicated – not saved yet.',
    'Block „{label}“ kopiert – über „+ Block einfügen“ auf dieser oder einer anderen Seite einsetzen.' => 'Block “{label}” copied – insert it on this or another page via “+ Insert block”.',
    'Die Blöcke der Vorlage werden übernommen und lassen sich danach frei ändern.' => 'The template’s blocks are copied and can be changed freely afterwards.',
    'Duplizieren (Kopie darunter)' => 'Duplicate (copy below)',
    'Eine Seite mit dem gewünschten Aufbau anlegen – am besten offline unter einer Seite „Vorlagen“.' => 'Create a page with the desired structure – ideally offline below a page “Templates”.',
    'Hier als Vorlage hinzufügen (oder im Seitenbaum „⋯ → Als Vorlage anbieten“), Namen und Beschreibung vergeben.' => 'Add it here as a template (or in the page tree “⋯ → Offer as template”) and give it a name and description.',
    'In dieser Reihenfolge erscheinen die Vorlagen beim Anlegen einer Seite. Die Blöcke kommen aus der Quellseite – Änderungen dort gelten für alle neuen Seiten.' => 'Templates appear in this order when creating a page. The blocks come from the source page – changes there apply to all new pages.',
    'Kopieren – auf jeder Seite über „+ Block einfügen“ einsetzen' => 'Copy – insert on any page via “+ Insert block”',
