    'Nicht mehr als Vorlage anbieten' => 'Stop offering as template',
    'Ohne Blöcke beginnen.' => 'Start without blocks.',
    'Optional „Vorschlagen unter“ wählen: Neue Seiten in diesem Bereich starten dann mit der Vorlage.' => 'Optionally choose “Suggest below”: new pages in that area then start with the template.',
    'Quelle einer Seitenvorlage – neue Seiten übernehmen ihre Blöcke' => 'Source of a page template – new pages copy its blocks',
    'Quellseite' => 'Source page',
    'Quellseiten' => 'Source pages',
    'Reihenfolge mit ↑/↓ festlegen – so erscheinen die Vorlagen beim Anlegen.' => 'Set the order with ↑/↓ – this is how templates appear when creating pages.',
    'Seite aus der Vorlage angelegt. Jetzt Inhalte anpassen.' => 'Page created from the template. Now adapt the content.',
    'Seite mit dem gewünschten Aufbau – am besten offline, z. B. unter einer Seite „Vorlagen“.' => 'Page with the desired structure – ideally offline, e.g. below a page “Templates”.',
    'Seitenvorlagen' => 'Page templates',
    'Seitenvorlagen gespeichert.' => 'Page templates saved.',
    'So geht’s' => 'How it works',
    'Vorlage bearbeiten' => 'Edit template',
    'Vorlage hinzufügen' => 'Add template',
    'Vorlagen, aus denen die Redaktion neue Seiten anlegt – z. B. „Leistung“ oder „Stellenanzeige“. Jede Vorlage übernimmt die Blöcke einer Quellseite.' => 'Templates editors use to create new pages – e.g. “Service” or “Job ad”. Each template copies the blocks of a source page.',
    'Vorschlagen unter (optional)' => 'Suggest below (optional)',
    'Wird eine neue Seite unter einer dieser Seiten angelegt, ist diese Vorlage vorgewählt.' => 'When a new page is created below one of these pages, this template is preselected.',
    'z. B. Leistung, Stellenanzeige, Veranstaltung' => 'e.g. Service, Job ad, Event',
    'Symbol (optional)' => 'Icon (optional)',
    'Als Vorlage speichern' => 'Save as template',
    'Anlegen und gestalten' => 'Create and design',
    'Ausgangspunkt' => 'Starting point',
    'Blöcke bearbeiten' => 'Edit blocks',
    'Die Seite mit den Blöcken dieser Vorlage – gestalten über „Blöcke bearbeiten“ rechts.' => 'The page holding this template’s blocks – design it via “Edit blocks” on the right.',
    'Eine gelungene Seite als Ausgangspunkt kopieren – die Seite selbst bleibt unverändert.' => 'Copy a good page as a starting point – the page itself stays unchanged.',
    'In dieser Reihenfolge erscheinen die Vorlagen beim Anlegen einer Seite. Eine entfernte Vorlage wird beim Speichern gelöscht.' => 'Templates appear in this order when creating a page. A removed template is deleted when saving.',
    'Kopie von:' => 'Copy of:',
    'Leer beginnen' => 'Start empty',
    'Name, Symbol und Beschreibung vergeben; optional „Vorschlagen unter“ wählen.' => 'Set name, icon and description; optionally choose “Suggest below”.',
    'Neue Vorlage' => 'New template',
    'Noch keine Vorlagen. Legen Sie links die erste an – oder im Seitenbaum „⋯ → Als Vorlage speichern“.' => 'No templates yet. Create the first one on the left – or in the page tree “⋯ → Save as template”.',
    'Reihenfolge mit ↑/↓ festlegen – so erscheinen die Vorlagen beim Anlegen einer Seite.' => 'Set the order with ↑/↓ – this is how templates appear when creating a page.',
    'Seitenvorlagen bearbeitet nur die Administration.' => 'Only administrators can edit page templates.',
    'Vorlage angelegt. Gestalten Sie jetzt die Blöcke – Name, Symbol und Reihenfolge unter Einrichtung › Website › Seitenvorlagen.' => 'Template created. Now design the blocks – name, icon and order under Setup › Website › Page templates.',
    'Vorlage anlegen – leer oder als Kopie einer Seite – und die Blöcke gestalten. Platzhalter wie „[bitte ergänzen: Preis]“ verhindern, dass eine Seite unfertig online geht.' => 'Create a template – empty or as a copy of a page – and design the blocks. Placeholders like “[bitte ergänzen: Preis]” keep unfinished pages from going online.',
    'Vorlagen, aus denen die Redaktion neue Seiten anlegt – z. B. „Leistung“ oder „Stellenanzeige“. Vorlagen sind keine Seiten der Website: keine Adresse, nicht im Seitenbaum, Menü oder in der Suche; bearbeiten kann sie nur die Administration.' => 'Templates editors use to create new pages – e.g. “Service” or “Job ad”. Templates are not pages of the website: no address, not in the page tree, menu or search; only administrators can edit them.',
    'Vorlagenseite' => 'Template page',
    'Anordnen und benennen' => 'Arrange and name',
    'Ausgangspunkt für neue Seiten der Redaktion – keine eigene Adresse, nur die Administration kann sie ändern.' => 'Starting point for new pages by editors – no address of their own, only administrators can change them.',
    'Erste Vorlage anlegen' => 'Create the first template',
    'Sonderseiten & Vorlagen' => 'Special pages & templates',
    'Auf eine andere Seite ziehen = Unterseite, zwischen zwei Seiten = Reihenfolge, unter die letzte Zeile = ans Ende.' => 'Drop onto another page = subpage, between two pages = order, below the last row = at the end.',
    'Doppelklick öffnet den Editor, Rechtsklick weitere Aktionen.' => 'Double-click opens the editor, right-click shows more actions.',
    'Hilfe: Seiten ordnen und bearbeiten' => 'Help: arranging and editing pages',
    'Ohne Ziehen: Seite wählen und Alt + Pfeiltasten (oder „⋯“ → Nach oben/unten, Einrücken, Ausrücken).' => 'Without dragging: select a page and press Alt + arrow keys (or “⋯” → Move up/down, Indent, Outdent).',
    'Detailseiten-Vorlagen gelten für alle Einträge einer Datentabelle und werden unter „Daten“ gestaltet.' => 'Detail page templates apply to all entries of a data table and are designed under “Data”.',
    'Seitenvorlagen sind der Ausgangspunkt für neue Seiten der Redaktion – ohne eigene Adresse, nur die Administration kann sie ändern.' => 'Page templates are the starting point for new pages by editors – without an address of their own, only administrators can change them.',
    '„Nicht gefunden (404)“ erscheint, wenn Besucher eine Adresse aufrufen, die es nicht gibt – mit Status 404, nicht in Menü, Sitemap und Suche. Solange sie nicht veröffentlicht ist, zeigt die Website die Standard-Fehlerseite des Kits.' => '“Not found (404)” appears when visitors open an address that does not exist – with status 404, not in menu, sitemap or search. Until it is published, the website shows the kit’s default error page.',
