    // Adresse der Verwaltung (Core\AdminPath)
    '5–40 Zeichen: Kleinbuchstaben, Ziffern, Bindestriche. Nicht erlaubt sind übliche Adressen wie admin, login, wp-admin, backend oder verwaltung.' => '5–40 characters: lowercase letters, digits, hyphens. Common addresses such as admin, login, wp-admin, backend or verwaltung are not allowed.',
    'Adresse der Verwaltung' => 'Admin address',
    'Bitte 5–40 Zeichen: Kleinbuchstaben, Ziffern und Bindestriche (nicht am Anfang).' => 'Please use 5–40 characters: lowercase letters, digits and hyphens (not at the start).',
    'Bitte eine Adresse eintragen.' => 'Please enter an address.',
    'Bitte melden Sie sich ab und wieder an – danach gilt die Anmeldung 15 Minuten als Bestätigung.' => 'Please sign out and sign in again – your sign-in then counts as confirmation for 15 minutes.',
    'Die Adresse der Verwaltung gilt für alle Websites – ändern kann sie nur die Netzwerk-Administration.' => 'The admin address applies to all websites – only network administrators can change it.',
    'Die Adresse gilt für alle Websites dieser Installation – ändern kann sie nur die Netzwerk-Administration.' => 'The address applies to all websites of this installation – only network administrators can change it.',
    'Die Adresse ist über die Umgebungsvariable KLXM_ADMIN_PATH festgelegt – bitte dort ändern.' => 'The address is set via the environment variable KLXM_ADMIN_PATH – please change it there.',
    'Die Verwaltung liegt jetzt unter {url} – bitte Lesezeichen und die App auf dem Homescreen neu anlegen. /admin zeigt ohne Anmeldung „Seite nicht gefunden“.' => 'The admin area is now at {url} – please update bookmarks and re-add the app to your home screen. Without signing in, /admin shows “page not found”.',
    'Die Verwaltung liegt wieder unter /admin.' => 'The admin area is back at /admin.',
    'Diese Adresse ist zu üblich oder schon vergeben – bitte eine eigene wählen.' => 'This address is too common or already taken – please choose your own.',
    'Festgelegt über die Umgebungsvariable KLXM_ADMIN_PATH beim Hosting – dort ändern.' => 'Set via the environment variable KLXM_ADMIN_PATH at your hosting – change it there.',
    'Gilt für' => 'Applies to',
    'Ihr Passwort zur Bestätigung' => 'Your password to confirm',
    'Nach dem Ändern geht es sofort unter der neuen Adresse weiter. Lesezeichen und die App auf dem Homescreen bitte neu anlegen. /admin zeigt ohne Anmeldung nur noch „Seite nicht gefunden“.' => 'After the change you continue right away at the new address. Please update bookmarks and re-add the app to your home screen. Without signing in, /admin only shows “page not found”.',
    'Neue Adresse' => 'New address',
    'Sie haben sich gerade angemeldet bzw. bestätigt – das Passwort ist für 15 Minuten nicht nötig.' => 'You signed in or confirmed recently – no password needed for 15 minutes.',
    'Unter /{slug} gibt es bereits eine Seite – bitte eine andere Adresse wählen.' => 'There is already a page at /{slug} – please choose another address.',
    'Unter dieser Adresse melden Sie sich an. Eine eigene Adresse statt der üblichen /admin hält automatische Login-Scanner fern – sie ersetzt aber keine starken Passwörter und keinen zweiten Faktor.' => 'This is where you sign in. Your own address instead of the usual /admin keeps automated login scanners away – but it does not replace strong passwords or a second factor.',
    'Vorschlag:' => 'Suggestion:',
    'Zurück zu /admin' => 'Back to /admin',
    'alle Websites dieser Installation' => 'all websites of this installation',
    'config/config.local.php ist nicht beschreibbar – bitte per Konsole setzen: {cmd}' => 'config/config.local.php is not writable – please set it on the console: {cmd}',
    'config/config.local.php ist nicht lesbar.' => 'config/config.local.php is not readable.',
    'übliche Adresse' => 'common address',
    'Unter dieser Adresse melden Sie sich an. Standard ist /admin. Optional eine eigene Adresse: Sie hält automatische Login-Scanner fern – ersetzt aber keine starken Passwörter und keinen zweiten Faktor.' => 'This is where you sign in. The default is /admin. Optionally use your own address: it keeps automated login scanners away – but does not replace strong passwords or a second factor.',
    'eigene Adresse' => 'own address',
    'Adresse der Verwaltung ändern' => 'Change the admin address',
    'Die Anmeldung liegt noch unter /admin – dort suchen automatische Login-Scanner zuerst. Eine eigene Adresse hält sie fern.' => 'Sign-in is still at /admin – the first place automated login scanners look. Your own address keeps them away.',
    // Medien: Löschen gesperrt, solange verwendet
    'Bitte zuerst dort entfernen – oder „Ersetzen“ nutzen, dann bleiben alle Verwendungen erhalten.' => 'Please remove it there first – or use “Replace”, which keeps all usages.',
