    'Symbolstil auf der Website' => 'Icon style on the website',
    'Gilt für alle Symbole der Website (Blöcke, Kit). Lucide und Tabler sind freie Linien-Sätze – Symbole, die es dort nicht gibt, kommen aus Phosphor „Linie“. Die Verwaltung bleibt unverändert.' => 'Applies to all icons on the website (blocks, kit). Lucide and Tabler are free line sets – icons they don’t have come from Phosphor “regular”. The admin area stays unchanged.',
    // Erststart: Willkommen-Bildschirm (Core\Onboarding)
    'Anleitungen: Handbuch & Hilfe in der Verwaltung, für Technik das Entwicklerhandbuch.' => 'Guides: handbook & help in the admin, the developer handbook for technical topics.',
    'Beim ersten Anmelden entscheiden' => 'Decide at first sign-in',
    'Beim ersten Anmelden wählen' => 'Choose at first sign-in',
    'Bis zur Einrichtung sehen Besucher den Hinweis „Diese Website wird gerade eingerichtet“ – die Website wird nicht von Suchmaschinen erfasst.' => 'Until then, visitors see the notice “This website is being set up” – search engines do not index it.',
    'Bitte ein Kit wählen.' => 'Please choose a kit.',
    'Bitte wählen, ob Startinhalte eingespielt werden sollen.' => 'Please choose whether starter content should be installed.',
    'Das Kit lässt sich später unter Grundeinstellungen wechseln; Startinhalte werden nur beim ersten Einrichten eingespielt.' => 'The kit can be changed later under Basic settings; starter content is only installed during the first setup.',
    'Eine leere Startseite sowie Impressum und Datenschutz als Vorlagen – Sie bauen die Website selbst auf.' => 'An empty home page plus legal notice and privacy policy as templates – you build the website yourself.',
    'Ersteinrichtung' => 'First setup',
    'Erster Aufruf legt Datenbank und Medienordner an. Sind Kit und Startinhalte noch offen, fragt der Willkommen-Bildschirm nach dem ersten Anmelden – sonst werden die Startinhalte sofort eingespielt.' => 'The first request creates the database and media folder. If kit and starter content are still open, the welcome screen asks after the first sign-in – otherwise the starter content is installed right away.',
    'KLXM Studio läuft. Bevor die Website online geht, legen Sie zwei Dinge fest – beides lässt sich später ändern:' => 'KLXM Studio is running. Before the website goes online, decide two things – both can be changed later:',
    'Kit und Startinhalte wählt die Administration.' => 'Kit and starter content are chosen by the administration.',
    'Kit und Startinhalte wählt die Administration. Bis dahin sehen Besucher den Hinweis „Diese Website wird gerade eingerichtet“.' => 'Kit and starter content are chosen by the administration. Until then, visitors see the notice “This website is being set up”.',
    'Kit wählen' => 'Choose a kit',
    'Mit Startinhalten' => 'With starter content',
    'Mit Startinhalten beginnen?' => 'Start with starter content?',
    'Musterseiten, Beispieltexte und – je nach Kit – Demo-Bilder. Ideal zum Kennenlernen; alles lässt sich später ändern oder löschen.' => 'Sample pages, example texts and – depending on the kit – demo images. Ideal for getting to know it; everything can be changed or deleted later.',
    'Ohne Startinhalte' => 'Without starter content',
    'Ohne Startinhalte (leere Startseite, Rechtstexte als Vorlage)' => 'Without starter content (empty home page, legal texts as templates)',
    'Startinhalte' => 'Starter content',
    'Startinhalte des Kits einspielen' => 'Install the kit’s starter content',
    'Website einrichten' => 'Set up website',
    'Weitere Websites legen Sie in der Netzwerk-Übersicht an („Neue Website“) – dort lassen sich Kit und Startinhalte auch gleich vorgeben.' => 'Create further websites in the network overview (“New website”) – kit and starter content can be preset there as well.',
    'Welches Kit soll die Website nutzen?' => 'Which kit should the website use?',
    'Willkommen! Die Website nutzt das Kit „{kit}“ mit seinen Startinhalten. Die Checkliste unten zeigt die nächsten Schritte.' => 'Welcome! The website uses the kit “{kit}” with its starter content. The checklist below shows the next steps.',
    'Willkommen! Die Website nutzt das Kit „{kit}“ – mit leerer Startseite sowie Impressum und Datenschutz als Vorlagen. Die Checkliste unten zeigt die nächsten Schritte.' => 'Welcome! The website uses the kit “{kit}” – with an empty home page plus legal notice and privacy policy as templates. The checklist below shows the next steps.',
    'Willkommen, {name}!' => 'Welcome, {name}!',
    'Zur Hilfe' => 'To the help',
    'Zur Netzwerk-Übersicht' => 'To the network overview',
    'danach führt die Übersicht mit einer Checkliste weiter: Verschlüsselung, E-Mail-Versand, Domain, Angaben der Website.' => 'then the overview continues with a checklist: encryption, e-mail sending, domain, website details.',
    'das Gestaltungs- und Funktionspaket der Website: Blöcke, Design, Musterseiten.' => 'the website’s design and feature package: blocks, design, sample pages.',
    'mit Musterseiten zum Ausprobieren oder leer zum eigenen Aufbau.' => 'with sample pages to try out or empty to build yourself.',
    // Ersteinrichtung: Einzelinstallation oder Netzwerk
    'Art der Installation' => 'Type of installation',
    'Einzelinstallation' => 'Single installation',
    'Netzwerk (mehrere Websites)' => 'Network (several websites)',
    'Netzwerk-Konto angelegt – bitte anmelden.' => 'Network account created – please sign in.',
    'Sie werden Netzwerk-Administration: weitere Websites anlegen und alle zentral verwalten. Beim ersten Anmelden richten Sie die Zwei-Faktor-Anmeldung ein.' => 'You become the network administration: create further websites and manage all of them centrally. At the first sign-in you set up two-factor sign-in.',
    'eine Website, Sie werden Administrator dieser Website.' => 'one website, you become its administrator.',
    // Willkommen-Bildschirm: Gruppen der Kits
    'Allgemein' => 'General',
    'Ausgangspunkt für eigene Kits.' => 'Starting point for your own kits.',
    'Empfohlen' => 'Recommended',
    'Für Branchen und Themen' => 'For industries and topics',
    'Für Entwickler' => 'For developers',
    'Für jede Art von Website – Unternehmen, Organisationen, Projekte.' => 'For any kind of website – companies, organisations, projects.',
    'Mit passenden Blöcken, Datentabellen und Musterseiten für einen bestimmten Zweck.' => 'With matching blocks, data tables and sample pages for a specific purpose.',
    'Unsicher? Alle Kits mit Vorschau für Desktop und Handy, hell und dunkel:' => 'Not sure? All kits with previews for desktop and mobile, light and dark:',
    'Kits ansehen' => 'View kits',
    // Netzwerk-Übersicht: Erststart offen
    'Einrichtung offen' => 'Setup pending',
    'Jetzt einrichten' => 'Set up now',
    'Kit und Startinhalte wählen. Bis dahin sehen Besucher „Hier entsteht eine neue Website“.' => 'Choose kit and starter content. Until then visitors see “A new website is coming soon”.',
    'Willkommen! Als Erstes die Website „{site}“ einrichten.' => 'Welcome! First set up the website “{site}”.',
    'Wählen Sie Kit und Startinhalte – danach legen Sie hier weitere Websites an.' => 'Choose kit and starter content – afterwards you create further websites here.',
    'noch nicht gewählt' => 'not chosen yet',
    // Begrüßungsfenster (Core\Welcome)
    'Absender und Empfänger für Anfragen, Einladungen und Passwort-Links – mit Testmail.' => 'Sender and recipient for requests, invitations and password links – with a test mail.',
    'Die feste Adresse für Links in E-Mails, Sitemap und Suchmaschinen.' => 'The fixed address for links in e-mails, sitemap and search engines.',
    'Erledigen' => 'Do it',
    'Erste Schritte' => 'First steps',
    'Ihre Website ist eingerichtet. Mit diesen Schritten wird sie startklar – in beliebiger Reihenfolge, jederzeit wieder hier unter Hilfe & Support → Erste Schritte.' => 'Your website is set up. These steps make it ready to launch – in any order, available any time under Help & support → First steps.',
    'Ihre Website nutzt das Kit „{kit}“. Wechseln geht unter Grundeinstellungen.' => 'Your website uses the kit “{kit}”. You can switch it under Basic settings.',
    'In der Netzwerk-Übersicht: Kurzname, Domain – Kit und Startinhalte wählt, wer die Website zuerst öffnet.' => 'In the network overview: short name, domain – kit and starter content are chosen by whoever opens the website first.',
    'Kit und Startinhalte gewählt' => 'Kit and starter content chosen',
    'Los geht’s' => 'Let’s go',
    'Name, Adresse, Kontakt und Logo – erscheinen automatisch überall auf der Website.' => 'Name, address, contact and logo – appear automatically everywhere on the website.',
    'Per Cron jede Nacht Datenbank und Medien sichern – Befehle im Entwicklerhandbuch.' => 'Back up database and media every night via cron – commands in the developer handbook.',
    'Schön, dass Sie da sind, {name}!' => 'Great to have you here, {name}!',
    'Schützt Anfragen aus Formularen – der geheime Schlüssel wird nur einmal angezeigt, gut aufbewahren.' => 'Protects requests from forms – the secret key is shown only once, keep it safe.',
    'Texte in [eckigen Klammern] sind Platzhalter der Startinhalte – vor dem Livegang ersetzen.' => 'Texts in [square brackets] are placeholders of the starter content – replace them before going live.',
    'Tägliche Sicherung einrichten' => 'Set up daily backups',
    'Video-Tutorials' => 'Video tutorials',
    'Weitere Websites anlegen' => 'Create further websites',
    'Willkommen bei KLXM Studio' => 'Welcome to KLXM Studio',
    'erledigt' => 'done',
    'Angaben der Website' => 'Website details',
    'Noch offen: {list}' => 'Still open: {list}',
    // Formulare: Eingangsbestätigung (DataForms::RECEIPT)
    'An die Adresse aus dem Feld' => 'To the address in the field',
    'Anrede, Zeitpunkt des Eingangs und Grußformel ergänzt das System. Pflicht z. B. beim Widerruf (§ 356a BGB): Bestätigung unverzüglich per E-Mail.' => 'The system adds greeting, time of receipt and closing. Required e.g. for withdrawals (§ 356a BGB): confirmation by email without delay.',
    'Braucht ein Feld vom Typ „E-Mail“ in dieser Tabelle.' => 'Needs a field of type “Email” in this table.',
    'Die eingegebenen Angaben in die Bestätigung aufnehmen' => 'Include the submitted details in the confirmation',
    'Eingangsbestätigung an die absendende Person' => 'Confirmation of receipt to the sender',
    'Eingangsbestätigung: Die Tabelle braucht ein Feld vom Typ „E-Mail“.' => 'Confirmation of receipt: the table needs a field of type “Email”.',
    'Eingangsbestätigung: {name}' => 'Confirmation of receipt: {name}',
    'Nach dem Absenden eine Bestätigung per E-Mail senden' => 'Send a confirmation by email after submitting',
    'Nur, was die Person selbst eingegeben hat. Bei vertraulichen Angaben ausgeschaltet lassen – E-Mails sind nicht Ende-zu-Ende verschlüsselt.' => 'Only what the person entered themselves. Leave off for confidential details – emails are not end-to-end encrypted.',
    'Text der Bestätigung' => 'Confirmation text',
    'wir bestätigen den Eingang Ihrer Angaben.' => 'we confirm that we have received your details.',
    // Kits als Pakete (Core\KitPackages, Grundeinstellungen → Kits)
    'Assets nicht veröffentlicht' => 'Assets not published',
    'Bitte bestätigen, dass das Kit aus einer vertrauenswürdigen Quelle stammt.' => 'Please confirm that the kit comes from a trusted source.',
    'Bitte eine ZIP-Datei auswählen.' => 'Please choose a ZIP file.',
    'Composer' => 'Composer',
    'Das Hochladen ist auf dieser Installation abgeschaltet (Konfiguration kit_upload bzw. PHP-Erweiterung zip fehlt). Kits lassen sich weiter per Kommandozeile installieren: php bin/console kit:install datei.zip' => 'Uploading is switched off on this installation (configuration kit_upload, or the PHP extension zip is missing). Kits can still be installed on the command line: php bin/console kit:install file.zip',
    'Das Hochladen von Kits ist abgeschaltet (Konfiguration kit_upload).' => 'Uploading kits is switched off (configuration kit_upload).',
    'Das Kit stammt aus einer vertrauenswürdigen Quelle.' => 'The kit comes from a trusted source.',
    'Das Kit verlangt Core {req} – installiert ist {core}.' => 'The kit requires core {req} – installed is {core}.',
    'Das bisherige Kit konnte nicht ersetzt werden.' => 'The existing kit could not be replaced.',
    'Datei bzw. Ordner nicht gefunden.' => 'File or folder not found.',
    'Datei konnte nicht entpackt werden: {path}' => 'File could not be extracted: {path}',
    'Die Datei ist zu groß für den Server (upload_max_filesize/post_max_size).' => 'The file is too large for the server (upload_max_filesize/post_max_size).',
    'Ein Kit enthält PHP-Code.' => 'A kit contains PHP code.',
    'Entpackt zu groß (höchstens {mb} MB).' => 'Too large when extracted (at most {mb} MB).',
    'Er läuft auf jeder Website dieser Installation, die das Kit nutzt, mit vollen Rechten. Installieren Sie Kits nur aus vertrauenswürdiger Quelle (z. B. von KLXM oder Ihrer Agentur).' => 'It runs with full privileges on every website of this installation that uses the kit. Only install kits from a trusted source (e.g. from KLXM or your agency).',
    'Ersetzen, falls bereits hochgeladen' => 'Replace if already uploaded',
    'Es gibt bereits ein mitgeliefertes bzw. lokales Kit „{name}“ (kits/{name}) – es wird nie ersetzt. Bitte das Paket umbenennen.' => 'There is already a bundled or local kit “{name}” (kits/{name}) – it is never replaced. Please rename the package.',
    'Geprüft werden: Größe, Pfade (keine absoluten Pfade, kein „..“, keine symbolischen Links), Kit-Name, Angaben label/version, die verlangte Core-Version (requires) und die PHP-Syntax. Hochgeladene Kits liegen unter storage/kits/{name}, ihre Assets unter public/assets/kits/{name}. Per Composer: Paket vom Typ klxm-studio-kit, danach php bin/console kits:publish.' => 'Checked: size, paths (no absolute paths, no “..”, no symbolic links), kit name, label/version, the required core version (requires) and the PHP syntax. Uploaded kits are stored in storage/kits/{name}, their assets in public/assets/kits/{name}. Via Composer: package of type klxm-studio-kit, then php bin/console kits:publish.',
    'Höchstens {mb} MB. Inhalt: theme.php bzw. kit.php mit Templates und Blöcken, composer.json (Typ klxm-studio-kit) und die fertig gebauten Assets im Ordner public/.' => 'At most {mb} MB. Contents: theme.php or kit.php with templates and blocks, composer.json (type klxm-studio-kit) and the prebuilt assets in the folder public/.',
    'Installierte Kits' => 'Installed kits',
    'Kein Kit gefunden: theme.php bzw. kit.php fehlt (im ZIP direkt oder in genau einem Ordner).' => 'No kit found: theme.php or kit.php is missing (directly in the ZIP or in exactly one folder).',
    'Keine fertigen Assets (Ordner public/) – das Kit hat auf der Website kein CSS/JS.' => 'No prebuilt assets (folder public/) – the kit has no CSS/JS on the website.',
    'Keine gültige ZIP-Datei.' => 'Not a valid ZIP file.',
    'Kit konnte nicht entfernt werden.' => 'The kit could not be removed.',
    'Kit konnte nicht nach {dir} verschoben werden.' => 'The kit could not be moved to {dir}.',
    'Kit „{label}“ ({name} {version}) {verb}.' => 'Kit “{label}” ({name} {version}) {verb}.',
    'Kit „{name}“ entfernen? Dateien unter storage/kits/{name} und public/assets/kits/{name} werden gelöscht.' => 'Remove kit “{name}”? Files in storage/kits/{name} and public/assets/kits/{name} will be deleted.',
    'Kit „{name}“ entfernt.' => 'Kit “{name}” removed.',
    'Kit „{name}“ ist bereits installiert. Zum Ersetzen erneut mit „Ersetzen“ (bzw. --force) installieren.' => 'Kit “{name}” is already installed. To replace it, install again with “Replace” (or --force).',
    'Kit „{name}“ ist bereits per Composer installiert – bitte dort aktualisieren.' => 'Kit “{name}” is already installed via Composer – please update it there.',
    'Kit „{name}“ nicht gefunden.' => 'Kit “{name}” not found.',
    'Kit „{name}“ unter {dir} ({source}) ist verdeckt – es gilt {active}' => 'Kit “{name}” in {dir} ({source}) is shadowed – {active} is used',
    'Kit „{name}“ verlangt Core {req}' => 'Kit “{name}” requires core {req}',
    'Kit „{name}“ wird noch verwendet: {sites}. Bitte dort zuerst ein anderes Kit wählen.' => 'Kit “{name}” is still in use: {sites}. Please choose another kit there first.',
    'Kit „{name}“: Assets nicht veröffentlicht – php bin/console kits:publish' => 'Kit “{name}”: assets not published – php bin/console kits:publish',
    'Kit-Paket hochladen' => 'Upload kit package',
    'Kits' => 'Kits',
    'Kits bringen Gestaltung, Blöcke und Startinhalte einer Website mit. Sie gelten für die ganze Installation: Jede Website wählt ihr Kit unter Grundeinstellungen → Aktives Kit. Zusätzliche Kits lassen sich als Paket installieren – per Composer oder als ZIP-Datei.' => 'Kits provide a website\'s design, blocks and starter content. They apply to the whole installation: each website chooses its kit under Basic settings → Active kit. Additional kits can be installed as a package – via Composer or as a ZIP file.',
    'Ordner templates/ fehlt.' => 'Folder templates/ is missing.',
    'Ordner {dir} ist nicht beschreibbar.' => 'Folder {dir} is not writable.',
    'PHP-Erweiterung zip fehlt.' => 'PHP extension zip is missing.',
    'Prüfen und installieren' => 'Check and install',
    'Symbolische Links sind im Kit nicht erlaubt: {path}' => 'Symbolic links are not allowed in a kit: {path}',
    'Syntaxfehler: {msg}' => 'Syntax error: {msg}',
    'Syntaxprüfung (php -l) nicht möglich – proc_open fehlt.' => 'Syntax check (php -l) not possible – proc_open is missing.',
    'Ungültiger Kit-Name „{name}“ (erlaubt: a–z, 0–9, - und _, beginnt mit einem Buchstaben, 2–41 Zeichen).' => 'Invalid kit name “{name}” (allowed: a–z, 0–9, - and _, starting with a letter, 2–41 characters).',
